<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LSMexa - Aprende Lenguas de Señas</title>
<script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/inter@5.0.0/index.css">
<style>
*{margin:0;padding:0;box-sizing:border-box}
:root{
--orange:#F28C28;--violet:#6657C8;--black:#171717;--yellow:#FFD447;--white:#FFFFFF;
--bg:#0f0f1a;--surface:#1a1a2e;--surface2:#252540;--surface3:#2f2f4a;
--text:#e8e8f0;--text2:#a0a0b8;--text3:#6b6b80;
--success:#4ade80;--error:#f87171;--info:#60a5fa;
--radius:12px;--radius-sm:8px;--radius-lg:16px;
--shadow:0 4px 24px rgba(0,0,0,0.3);
--transition:all 0.3s cubic-bezier(0.4,0,0.2,1);
}
html{font-size:16px}
body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;overflow-x:hidden}
body.high-contrast{--bg:#000;--surface:#111;--surface2:#222;--text:#fff;--text2:#ddd}
body.large-text{font-size:18px}
body.xlarge-text{font-size:20px}
body.reduce-motion *{transition-duration:0.01ms!important;animation-duration:0.01ms!important}
#root{min-height:100vh}
::-webkit-scrollbar{width:6px}
::-webkit-scrollbar-track{background:var(--surface)}
::-webkit-scrollbar-thumb{background:var(--violet);border-radius:3px}
@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@keyframes slideIn{from{opacity:0;transform:translateX(-20px)}to{opacity:1;transform:translateX(0)}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
@keyframes bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
.animate-in{animation:fadeIn 0.4s ease-out}
.animate-slide{animation:slideIn 0.3s ease-out}
</style>
</head>
<body>
<div id="root"></div>
<script type="text/babel">
const {useState,useEffect,useContext,createContext,useCallback,useMemo,useRef} = React;

// ============ SVG COMPONENTS ============
const LSMexaLogo = ({size=48}) => (
<svg width={size} height={size} viewBox="0 0 120 120" fill="none">
<path d="M60 15 C75 15, 90 25, 90 40 C90 50, 75 55, 60 55 C45 55, 30 50, 30 40 C30 25, 45 15, 60 15Z" fill="url(#greenGrad)"/>
<path d="M25 50 C35 45, 50 50, 55 65 C55 80, 45 95, 35 100 C25 95, 15 80, 20 65 C20 55, 25 50, 25 50Z" fill="url(#blueGrad)"/>
<path d="M95 50 C85 45, 70 50, 65 65 C65 80, 75 95, 85 100 C95 95, 105 80, 100 65 C100 55, 95 50, 95 50Z" fill="url(#orangeGrad)"/>
<defs>
<linearGradient id="greenGrad" x1="30" y1="15" x2="90" y2="55"><stop stopColor="#4ade80"/><stop offset="1" stopColor="#16a34a"/></linearGradient>
<linearGradient id="blueGrad" x1="15" y1="45" x2="55" y2="100"><stop stopColor="#818cf8"/><stop offset="1" stopColor="#4338ca"/></linearGradient>
<linearGradient id="orangeGrad" x1="65" y1="45" x2="105" y2="100"><stop stopColor="#fbbf24"/><stop offset="1" stopColor="#ea580c"/></linearGradient>
</defs>
</svg>
);

const LSMexaLogoFull = () => (
<div style={{display:'flex',flexDirection:'column',alignItems:'center',gap:8}}>
<svg width="80" height="80" viewBox="0 0 120 120" fill="none">
<path d="M60 15 C75 15, 90 25, 90 40 C90 50, 75 55, 60 55 C45 55, 30 50, 30 40 C30 25, 45 15, 60 15Z" fill="url(#gG)"/>
<path d="M25 50 C35 45, 50 50, 55 65 C55 80, 45 95, 35 100 C25 95, 15 80, 20 65 C20 55, 25 50, 25 50Z" fill="url(#bG)"/>
<path d="M95 50 C85 45, 70 50, 65 65 C65 80, 75 95, 85 100 C95 95, 105 80, 100 65 C100 55, 95 50, 95 50Z" fill="url(#oG)"/>
<defs>
<linearGradient id="gG" x1="30" y1="15" x2="90" y2="55"><stop stopColor="#4ade80"/><stop offset="1" stopColor="#16a34a"/></linearGradient>
<linearGradient id="bG" x1="15" y1="45" x2="55" y2="100"><stop stopColor="#818cf8"/><stop offset="1" stopColor="#4338ca"/></linearGradient>
<linearGradient id="oG" x1="65" y1="45" x2="105" y2="100"><stop stopColor="#fbbf24"/><stop offset="1" stopColor="#ea580c"/></linearGradient>
</defs>
</svg>
<span style={{fontSize:22,fontWeight:800,color:'#a78bfa',letterSpacing:2}}>LSMEXA</span>
</div>
);

const DigiMascot = ({expression='happy', size=120}) => {
const expressions = {
happy:{mouth:'M42 68 Q50 78 58 68',eyes:'open'},
excited:{mouth:'M40 66 Q50 80 60 66',eyes:'sparkle'},
thinking:{mouth:'M44 70 Q50 72 56 70',eyes:'side'},
encouraging:{mouth:'M42 68 Q50 76 58 68',eyes:'open'},
sad:{mouth:'M42 72 Q50 66 58 72',eyes:'open'},
celebrating:{mouth:'M38 64 Q50 82 62 64',eyes:'sparkle'}
};
const exp = expressions[expression] || expressions.happy;
return (
<svg width={size} height={size} viewBox="0 0 100 100" fill="none">
{/* Tail */}
<path d="M72 70 Q85 60 88 45 Q90 55 85 70 Q80 80 72 75Z" fill="#6657C8" opacity="0.9"/>
<path d="M82 50 Q88 42 88 45 Q86 52 82 55Z" fill="#F28C28"/>
{/* Body */}
<ellipse cx="50" cy="72" rx="22" ry="20" fill="#6657C8"/>
<ellipse cx="50" cy="75" rx="14" ry="12" fill="#FFD447" opacity="0.3"/>
{/* Head */}
<circle cx="50" cy="42" r="22" fill="#6657C8"/>
{/* Ears */}
<path d="M32 28 L28 10 L42 22Z" fill="#6657C8"/>
<path d="M33 26 L30 14 L40 23Z" fill="#F28C28" opacity="0.7"/>
<path d="M68 28 L72 10 L58 22Z" fill="#6657C8"/>
<path d="M67 26 L70 14 L60 23Z" fill="#F28C28" opacity="0.7"/>
{/* Face */}
<circle cx="50" cy="45" r="16" fill="#F28C28" opacity="0.25"/>
{/* Eyes */}
{exp.eyes === 'open' && <>
<ellipse cx="42" cy="40" rx="5" ry="6" fill="white"/>
<ellipse cx="58" cy="40" rx="5" ry="6" fill="white"/>
<circle cx="43" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="59" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="44" cy="38" r="1.5" fill="white"/>
<circle cx="60" cy="38" r="1.5" fill="white"/>
</>}
{exp.eyes === 'sparkle' && <>
<ellipse cx="42" cy="40" rx="5.5" ry="6.5" fill="white"/>
<ellipse cx="58" cy="40" rx="5.5" ry="6.5" fill="white"/>
<circle cx="43" cy="40" r="3.5" fill="#1e3a5f"/>
<circle cx="59" cy="40" r="3.5" fill="#1e3a5f"/>
<circle cx="44" cy="38" r="2" fill="white"/>
<circle cx="60" cy="38" r="2" fill="white"/>
<circle cx="41" cy="42" r="1" fill="white"/>
<circle cx="57" cy="42" r="1" fill="white"/>
</>}
{exp.eyes === 'side' && <>
<ellipse cx="44" cy="40" rx="5" ry="6" fill="white"/>
<ellipse cx="58" cy="40" rx="5" ry="6" fill="white"/>
<circle cx="46" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="60" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="47" cy="38" r="1.5" fill="white"/>
<circle cx="61" cy="38" r="1.5" fill="white"/>
</>}
{/* Nose */}
<ellipse cx="50" cy="47" rx="3" ry="2.5" fill="#1a1a2e"/>
{/* Mouth */}
<path d={exp.mouth} stroke="#1a1a2e" strokeWidth="1.5" fill="none" strokeLinecap="round"/>
{/* Cheeks */}
<circle cx="36" cy="48" r="4" fill="#F28C28" opacity="0.2"/>
<circle cx="64" cy="48" r="4" fill="#F28C28" opacity="0.2"/>
{/* Arm with OK gesture */}
<path d="M30 65 Q20 60 18 50 Q16 45 20 42" stroke="#6657C8" strokeWidth="5" fill="none" strokeLinecap="round"/>
<circle cx="19" cy="42" r="4" fill="#6657C8"/>
<path d="M17 38 Q15 34 17 32" stroke="#6657C8" strokeWidth="2.5" fill="none" strokeLinecap="round"/>
<path d="M19 37 Q18 32 20 30" stroke="#6657C8" strokeWidth="2.5" fill="none" strokeLinecap="round"/>
<path d="M21 38 Q22 33 21 31" stroke="#6657C8" strokeWidth="2.5" fill="none" strokeLinecap="round"/>
<path d="M23 40 Q26 37 25 35" stroke="#6657C8" strokeWidth="2.5" fill="none" strokeLinecap="round"/>
<path d="M22 43 Q24 44 23 45" stroke="#6657C8" strokeWidth="2" fill="none" strokeLinecap="round"/>
</svg>
);
};

// ============ DATA ============
const LANGUAGES = {
lsm:{id:'lsm',name:'Lengua de Señas Mexicana',code:'LSM',supportLang:'Español',flag:'🇲🇽'},
lsf:{id:'lsf',name:'Langue des Signes Française',code:'LSF',supportLang:'Français',flag:'🇫🇷'},
asl:{id:'asl',name:'American Sign Language',code:'ASL',supportLang:'English',flag:'🇸'},
lsc:{id:'lsc',name:'Lengua de Señas Colombiana',code:'LSC',supportLang:'Español',flag:'🇨🇴'}
};

const STAGES = [
{id:1,nameKey:'fundamentos',color:'#4ade80'},
{id:2,nameKey:'vocabulario',color:'#60a5fa'},
{id:3,nameKey:'comprension',color:'#a78bfa'},
{id:4,nameKey:'gramatica',color:'#f28c28'},
{id:5,nameKey:'comunicacion',color:'#fbbf24'},
{id:6,nameKey:'consolidacion',color:'#f87171'}
];

const STAGE_NAMES = {
fundamentos:{es:'Fundamentos',fr:'Fondements',en:'Fundamentals'},
vocabulario:{es:'Vocabulario Esencial',fr:'Vocabulaire Essentiel',en:'Essential Vocabulary'},
comprension:{es:'Comprensión Cotidiana',fr:'Compréhension Quotidienne',en:'Everyday Comprehension'},
gramatica:{es:'Gramática',fr:'Grammaire',en:'Grammar'},
comunicacion:{es:'Comunicación Contextualizada',fr:'Communication Contextualisée',en:'Contextual Communication'},
consolidacion:{es:'Consolidación',fr:'Consolidation',en:'Consolidation'}
};

// Content data per language
const CONTENT_DATA = {
lsm:{
stages:[
{
id:1,name:'Fundamentos de LSM',blocks:[
{id:'lsm-b1',name:'Introducción a la LSM',lessons:[
{id:'lsm-l1',title:'Bienvenida a la LSM',steps:[
{type:'intro',text:'La Lengua de Señas Mexicana (LSM) es la lengua natural de la comunidad sorda de México. Tiene su propia gramática y estructura, independiente del español.',digi:'happy'},
{type:'concept',title:'¿Qué es una lengua de señas?',text:'Es una lengua visual-gestual que utiliza las manos, el cuerpo y las expresiones faciales para comunicarse. No es una traducción del español.',digi:'thinking'},
{type:'demo',title:'Atención visual',text:'Antes de señalar, es importante establecer contacto visual. En la LSM, la atención visual es fundamental para iniciar la comunicación.',digi:'encouraging',signDetail:'Configuración: mano abierta. Movimiento: leve oscilación frente al rostro del interlocutor.'},
{type:'practice',question:'¿Cuál es el primer paso para comunicarse en LSM?',options:['Gritar más fuerte','Establecer contacto visual','Escribir en papel','Usar el teléfono'],correct:1,explanation:'La atención visual es el primer paso fundamental en la comunicación en LSM.'},
{type:'concept',title:'Configuraciones manuales',text:'Las configuraciones manuales son las formas que adopta la mano al realizar una seña. Son uno de los parámetros fundamentales de la LSM.',digi:'encouraging'},
{type:'demo',title:'Configuración: mano abierta (B)',text:'La mano abierta con los dedos extendidos y juntos es una de las configuraciones básicas de la LSM. Se usa en muchas señas como "casa", "ayuda" y otras.',digi:'happy',signDetail:'Configuración: todos los dedos extendidos y juntos. Palma orientada hacia adelante. Muñeca recta.'},
{type:'quiz',question:'¿Qué parámetro de la LSM describe la forma de la mano?',options:['Ubicación','Configuración manual','Movimiento','Expresión facial'],correct:1,explanation:'La configuración manual describe la forma que adopta la mano al realizar una seña.'}
]},
{id:'lsm-l2',title:'El alfabeto manual de la LSM',steps:[
{type:'intro',text:'El alfabeto manual (dactilológico) de la LSM se utiliza para deletrear nombres propios, palabras técnicas o cuando no se conoce la seña específica.',digi:'happy'},
{type:'demo',title:'Letras A, B, C',text:'A: puño cerrado con el pulgar al lado. B: mano abierta, dedos juntos, pulgar cruzado. C: mano en forma de C.',digi:'encouraging',signDetail:'A: puño cerrado, pulgar al lado del índice. B: palma abierta, dedos juntos, pulgar cruzado sobre la palma. C: dedos curvados formando una C.'},
{type:'demo',title:'Letras D, E, F',text:'D: índice extendido, demás dedos tocando el pulgar. E: dedos curvados tocando el pulgar. F: pulgar e índice en círculo, demás extendidos.',digi:'encouraging',signDetail:'D: índice apuntando arriba, demás dedos curvados tocando la yema del pulgar. E: todos los dedos curvados tocando la yema del pulgar. F: pulgar e índice forman un círculo, dedos medio, anular y meñique extendidos.'},
{type:'practice',question:'¿Para qué se usa principalmente el alfabeto manual en LSM?',options:['Para saludar','Para deletrear nombres propios','Para contar','Para despedirse'],correct:1,explanation:'El alfabeto manual se usa principalmente para deletrear nombres propios, palabras técnicas o cuando no se conoce la seña.'},
{type:'quiz',question:'¿Cuál configuración representa la letra "A" en LSM?',options:['Mano abierta','Puño cerrado con pulgar al lado','Dedo índice extendido','Mano en forma de C'],correct:1,explanation:'La letra A en LSM se representa con un puño cerrado y el pulgar al lado del índice.'}
]}
]},
{id:'lsm-b2',name:'Saludos y presentaciones',lessons:[
{id:'lsm-l3',title:'Saludos básicos en LSM',steps:[
{type:'intro',text:'Los saludos en LSM son fundamentales para iniciar cualquier interacción. Vamos a aprender los más comunes.',digi:'happy'},
{type:'demo',title:'HOLA',text:'Seña: mano abierta en forma de B, se lleva de la frente hacia adelante como un saludo militar suave.',digi:'encouraging',signDetail:'Configuración: mano abierta (B). Ubicación: frente. Movimiento: de la frente hacia adelante, como saludando. Expresión facial: sonrisa amable.'},
{type:'demo',title:'BUENOS DÍAS',text:'Seña: mano abierta toca la barbilla y luego se mueve hacia adelante. Se puede acompañar con la seña de "día" (brazo curvo sobre la cabeza representando el sol).',digi:'encouraging',signDetail:'Configuración: mano abierta. Ubicación: barbilla. Movimiento: hacia adelante. Expresión facial: amable.'},
{type:'demo',title:'BUENAS NOCHES',text:'Seña: mano abierta toca la barbilla y luego se mueve hacia adelante, similar a "buenos días" pero con contexto nocturno. Alternativamente, se usa la seña de "noche" (mano curvada sobre la cabeza como un techo oscuro).',digi:'encouraging',signDetail:'Configuración: mano abierta. Ubicación: barbilla. Movimiento: hacia adelante.'},
{type:'practice',question:'¿Cómo se dice "HOLA" en LSM?',options:['Puño cerrado golpeando el pecho','Mano abierta de la frente hacia adelante','Dos dedos en V','Mano cerrada moviéndose en círculo'],correct:1,explanation:'HOLA en LSM se realiza con la mano abierta (configuración B) moviéndose de la frente hacia adelante.'},
{type:'demo',title:'GRACIAS',text:'Seña: mano abierta toca la barbilla y se mueve hacia adelante y abajo, como enviando un beso de agradecimiento.',digi:'happy',signDetail:'Configuración: mano abierta. Ubicación: barbilla. Movimiento: hacia adelante y ligeramente hacia abajo. Expresión facial: agradecida.'},
{type:'quiz',question:'¿Cuál es la configuración manual principal para decir "HOLA" en LSM?',options:['Puño cerrado','Mano abierta (B)','Dedo índice','Mano en forma de C'],correct:1,explanation:'La seña de HOLA utiliza la configuración de mano abierta (B).'}
]},
{id:'lsm-l4',title:'Presentaciones personales',steps:[
{type:'intro',text:'Aprender a presentarse es esencial en cualquier lengua. En LSM, las presentaciones tienen su propia estructura.',digi:'happy'},
{type:'demo',title:'YO / ME LLAMO',text:'Seña de YO: dedo índice apunta al pecho. ME LLAMO: dedos índice y medio de ambas manos se tocan y luego se separan hacia los lados.',digi:'encouraging',signDetail:'YO: índice pointing al centro del pecho. ME LLAMO: ambas manos con índice y medio extendidos, se tocan en el centro y se mueven hacia los lados.'},
{type:'demo',title:'¿CÓMO TE LLAMAS?',text:'Seña: cejas fruncidas (marca interrogativa), dedos índice y medio de ambas manos se tocan y separan, seguido de señalar a la persona.',digi:'encouraging',signDetail:'Expresión facial: cejas fruncidas (indicador de pregunta). Manos: índice y medio extendidos, movimiento de tocar y separar.'},
{type:'practice',question:'¿Qué elemento no manual es importante en la pregunta "¿Cómo te llamas?"?',options:['Sonrisa','Cejas fruncidas','Boca abierta','Ojos cerrados'],correct:1,explanation:'En LSM, las preguntas wh- (qué, cómo, dónde, etc.) se marcan con cejas fruncidas.'},
{type:'quiz',question:'¿Cómo se señala "YO" en LSM?',options:['Señalando la cabeza','Dedo índice apuntando al pecho','Mano abierta en el pecho','Puño cerrado'],correct:1,explanation:'YO se señala apuntando con el dedo índice al centro del pecho.'}
]}
]}
]
},
{
id:2,name:'Vocabulario Esencial LSM',blocks:[
{id:'lsm-b3',name:'Familia y relaciones',lessons:[
{id:'lsm-l5',title:'Miembros de la familia',steps:[
{type:'intro',text:'Vamos a aprender las señas de los miembros de la familia en LSM.',digi:'happy'},
{type:'demo',title:'MAMÁ',text:'Seña: mano abierta en configuración 5, se toca la barbilla con el pulgar. Movimiento: abrir y cerrar los dedos dos veces.',digi:'encouraging',signDetail:'Configuración: mano abierta (5). Ubicación: barbilla. Movimiento: abrir y cerrar dedos. Nota: el lado de la barbilla indica género femenino.'},
{type:'demo',title:'PAPÁ',text:'Seña: similar a MAMÁ pero tocando la frente con el pulgar. El lado de la frente indica género masculino.',digi:'encouraging',signDetail:'Configuración: mano abierta (5). Ubicación: frente. Movimiento: abrir y cerrar dedos. Nota: el lado de la frente indica género masculino.'},
{type:'demo',title:'HERMANO/HERMANA',text:'Seña: configuración 1 (índice extendido). HERMANO: se mueve desde la frente hacia abajo. HERMANA: se mueve desde la barbilla hacia abajo.',digi:'encouraging',signDetail:'Configuración: índice extendido. HERMANO: de frente hacia abajo. HERMANA: de barbilla hacia abajo.'},
{type:'practice',question:'¿Qué diferencia la seña de MAMÁ de la de PAPÁ en LSM?',options:['El movimiento','La ubicación (barbilla vs frente)','La configuración manual','La expresión facial'],correct:1,explanation:'MAMÁ se señala en la barbilla y PAPÁ en la frente. Esta diferenciación de ubicación por género es común en LSM.'},
{type:'quiz',question:'¿Dónde se ubica la seña de PAPÁ?',options:['En el pecho','En la barbilla','En la frente','En el hombro'],correct:2,explanation:'PAPÁ se señala tocando la frente con el pulgar de la mano abierta.'}
]}
]}
]
}
]
},
lsf:{
stages:[
{
id:1,name:'Fondements de la LSF',blocks:[
{id:'lsf-b1',name:'Introduction à la LSF',lessons:[
{id:'lsf-l1',title:'Bienvenue en LSF',steps:[
{type:'intro',text:'La Langue des Signes Française (LSF) est la langue naturelle de la communauté sourde de France. Elle possède sa propre grammaire, indépendante du français.',digi:'happy'},
{type:'concept',title:'Qu\'est-ce qu\'une langue des signes?',text:'C\'est une langue visuo-gestuelle qui utilise les mains, le corps et les expressions faciales. Ce n\'est pas une traduction du français.',digi:'thinking'},
{type:'demo',title:'Attention visuelle',text:'Avant de signer, il est important d\'établir un contact visuel. En LSF, l\'attention visuelle est fondamentale.',digi:'encouraging',signDetail:'Configuration: main ouverte. Mouvement: léger mouvement devant le visage de l\'interlocuteur.'},
{type:'practice',question:'Quel est le premier pas pour communiquer en LSF?',options:['Crier plus fort','Établir un contact visuel','Écrire sur papier','Utiliser le téléphone'],correct:1,explanation:'L\'attention visuelle est le premier pas fondamental en communication LSF.'},
{type:'quiz',question:'La LSF est-elle une traduction du français?',options:['Oui, toujours','Non, c\'est une langue indépendante','Parfois','Seulement à l\'écrit'],correct:1,explanation:'La LSF est une langue indépendante avec sa propre grammaire, pas une traduction du français.'}
]},
{id:'lsf-l2',title:'L\'alphabet manuel de la LSF',steps:[
{type:'intro',text:'L\'alphabet manuel (dactylologie) de la LSF sert à épeler les noms propres et les mots techniques.',digi:'happy'},
{type:'demo',title:'Lettres A, B, C en LSF',text:'A: poing fermé avec le pouce sur le côté. B: main ouverte, doigts joints, pouce devant. C: main en forme de C.',digi:'encouraging',signDetail:'Note: L\'alphabet de la LSF diffère de celui de l\'ASL et de la LSM dans certaines lettres.'},
{type:'practice',question:'À quoi sert principalement l\'alphabet manuel en LSF?',options:['Pour saluer','Pour épeler les noms propres','Pour compter','Pour dire au revoir'],correct:1,explanation:'L\'alphabet manuel sert principalement à épeler les noms propres et mots techniques.'},
{type:'quiz',question:'Quelle configuration représente la lettre "A" en LSF?',options:['Main ouverte','Poing fermé avec pouce sur le côté','Index tendu','Main en forme de C'],correct:1,explanation:'La lettre A en LSF se fait avec un poing fermé et le pouce sur le côté.'}
]}
]},
{id:'lsf-b2',name:'Salutations et présentations',lessons:[
{id:'lsf-l3',title:'Salutations de base en LSF',steps:[
{type:'intro',text:'Les salutations sont essentielles pour commencer toute interaction en LSF.',digi:'happy'},
