<div style={{marginBottom:24}}>
<label style={{display:'block',fontSize:14,fontWeight:600,color:'var(--text)',marginBottom:10}}>Tamaño del texto</label>
<div style={{display:'flex',gap:8}}>
{['normal','large','xlarge'].map(s=>(
<button key={s} onClick={()=>setTextSize(s)} style={{
padding:'10px 20px',background:textSize===s?'var(--violet)':'var(--surface2)',
border:'1px solid '+(textSize===s?'var(--violet)':'var(--surface3)'),
borderRadius:'var(--radius-sm)',color:'var(--text)',cursor:'pointer',fontSize:14,fontWeight:600
}}>{s==='normal'?'Normal':s==='large'?'Grande':'Muy grande'}</button>
))}
</div>
</div>

<div style={{marginBottom:24}}>
<label style={{display:'flex',alignItems:'center',gap:12,cursor:'pointer'}}>
<input type="checkbox" checked={highContrast} onChange={e=>setHighContrast(e.target.checked)} style={{width:20,height:20,accentColor:'var(--violet)'}}/>
<div>
<div style={{fontSize:14,fontWeight:600}}>Alto contraste</div>
<div style={{fontSize:12,color:'var(--text2)'}}>Aumenta el contraste para mejor legibilidad</div>
</div>
</label>
</div>

<div style={{marginBottom:24}}>
<label style={{display:'flex',alignItems:'center',gap:12,cursor:'pointer'}}>
<input type="checkbox" checked={reduceMotion} onChange={e=>setReduceMotion(e.target.checked)} style={{width:20,height:20,accentColor:'var(--violet)'}}/>
<div>
<div style={{fontSize:14,fontWeight:600}}>Reducir animaciones</div>
<div style={{fontSize:12,color:'var(--text2)'}}>Minimiza movimientos y transiciones</div>
</div>
</label>
</div>

<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
Aplicar cambios
</button>
</div>
</div>
);
}

