<p style={{color:'var(--text2)'}}>{lesson.title} — {lang.code}</p>
<p style={{color:'var(--text3)',fontSize:13,marginTop:8}}>Lección {lessonIdx+1} de {block.lessons.length} en este bloque</p>
</div>

<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
{nextLessonId && (
<button onClick={()=>{onBack();setTimeout(()=>onNavigate('lesson',{blockId:blockId,lessonId:nextLessonId}),100)}} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}
onMouseOver={e=>e.target.style.background='#e07b1a'} onMouseOut={e=>e.target.style.background='var(--orange)'}>
▶ Siguiente lección
