function AuthPage({onAuth}) {
const [mode,setMode] = useState('register');
const [name,setName] = useState('');
const [email,setEmail] = useState('');
const [password,setPassword] = useState('');
const [showPass,setShowPass] = useState(false);
const [errors,setErrors] = useState({});
const [success,setSuccess] = useState('');
const [loading,setLoading] = useState(false);

const validate = () => {
const e = {};
if(!name.trim()) e.name = 'El nombre o apodo es requerido';
if(!email.trim()) e.email = 'El correo electrónico es requerido';
else if(!validateEmail(email)) e.email = 'Formato de correo inválido';
if(!password) e.password = 'La contraseña es requerida';
else if(password.length < 8) e.password = 'Mínimo 8 caracteres';
else if(!/[A-Z]/.test(password)) e.password = 'Debe incluir una mayúscula';
else if(!/[0-9]/.test(password)) e.password = 'Debe incluir un número';
setErrors(e);
return Object.keys(e).length === 0;
};

const handleRegister = () => {
if(!validate()) return;
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
if(users[email]) {setErrors({email:'Este correo ya está registrado'});setLoading(false);return}
users[email] = {name,email,passwordHash:hashPassword(password),createdAt:new Date().toISOString()};
setStorage('users',users);
setSuccess('¡Cuenta creada exitosamente!');
setTimeout(()=>onAuth({name,email}),500);
setLoading(false);
},500);
};

const handleLogin = () => {
if(!email.trim()||!validateEmail(email)){setErrors({email:'Correo inválido'});return}
if(!password){setErrors({password:'Contraseña requerida'});return}
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
const user = users[email];
if(!user||user.passwordHash!==hashPassword(password)){setErrors({password:'Credenciales incorrectas'});setLoading(false);return}
setStorage('currentUser',{name:user.name,email:user.email});
onAuth({name:user.name,email:user.email});
setLoading(false);
},500);
};

return (
<div style={{minHeight:'100vh',display:'flex',alignItems:'center',justifyContent:'center',padding:20,background:'linear-gradient(135deg,#0f0f1a 0%,#1a1a2e 50%,#0f0f1a 100%)'}}>
<div style={{width:'100%',maxWidth:440,animation:'fadeIn 0.5s ease-out'}}>
<div style={{textAlign:'center',marginBottom:32}}><LSMexaLogoFull/></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius-lg)',padding:32,boxShadow:'var(--shadow)',border:'1px solid var(--surface3)'}}>
<div style={{textAlign:'center',marginBottom:24}}>
<DigiMascot expression="happy" size={100}/>
<h2 style={{fontSize:22,fontWeight:700,marginTop:12,color:'var(--text)'}}>
{mode==='register'?'¡Bienvenido a LSMexa!':'¡Hola de nuevo!'}
</h2>
<p style={{color:'var(--text2)',fontSize:14,marginTop:4}}>
{mode==='register'?'Crea tu cuenta para comenzar':'Inicia sesión para continuar'}
</p>
</div>

{success && <div style={{background:'#064e3b',color:'#4ade80',padding:12,borderRadius:'var(--radius-sm)',marginBottom:16,fontSize:14,textAlign:'center'}}>{success}</div>}

<div style={{display:'flex',gap:8,marginBottom:24}}>
<button onClick={()=>{setMode('register');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='register'?'var(--violet)':'var(--surface2)',color:mode==='register'?'white':'var(--text2)'}}>Registro</button>
<button onClick={()=>{setMode('login');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='login'?'var(--violet)':'var(--surface2)',color:mode==='login'?'white':'var(--text2)'}}>Iniciar Sesión</button>
</div>

{mode==='register' && (
<div style={{marginBottom:16}}>
<label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre o apodo</label>
<input value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.name?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}} onFocus={e=>e.target.style.borderColor='var(--violet)'} onBlur={e=>e.target.style.borderColor=errors.name?'var(--error)':'var(--surface3)'}/>
{errors.name && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.name}</p>}
</div>
)}

<div style={{marginBottom:16}}>
<label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo electrónico</label>
<input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="tu@correo.com" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.email?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}} onFocus={e=>e.target.style.borderColor='var(--violet)'} onBlur={e=>e.target.style.borderColor=errors.email?'var(--error)':'var(--surface3)'}/>
{errors.email && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.email}</p>}
</div>

<div style={{marginBottom:24}}>
<label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Contraseña</label>
<div style={{position:'relative'}}>
<input value={password} onChange={e=>setPassword(e.target.value)} type={showPass?'text':'password'} placeholder="Mínimo 8 caracteres" style={{width:'100%',padding:'12px 40px 12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.password?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}} onFocus={e=>e.target.style.borderColor='var(--violet)'} onBlur={e=>e.target.style.borderColor=errors.password?'var(--error)':'var(--surface3)'}/>
<button onClick={()=>setShowPass(!showPass)} style={{position:'absolute',right:10,top:'50%',transform:'translateY(-50%)',background:'none',border:'none',color:'var(--text2)',cursor:'pointer',fontSize:18}}>{showPass?'🙈':'👁️'}</button>
</div>
{errors.password && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.password}</p>}
<p style={{color:'var(--text3)',fontSize:11,marginTop:4}}>Mín. 8 caracteres, 1 mayúscula, 1 número</p>
</div>

<button onClick={mode==='register'?handleRegister:handleLogin} disabled={loading} style={{width:'100%',padding:'14px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',fontSize:16,fontWeight:700,cursor:'pointer',opacity:loading?0.7:1}}
onMouseOver={e=>!loading&&(e.target.style.background='#e07b1a')} onMouseOut={e=>e.target.style.background='var(--orange)'}>
{loading?'Procesando...':mode==='register'?'Crear Cuenta':'Iniciar Sesión'}
</button>

<div style={{marginTop:20,textAlign:'center'}}>
<p style={{fontSize:12,color:'var(--text3)'}}>
Al continuar aceptas nuestros <a href="#" onClick={e=>e.preventDefault()} style={{color:'var(--violet)',textDecoration:'none'}}>Términos</a> y <a href="#" onClick={e=>e.preventDefault()} style={{color:'var(--violet)',textDecoration:'none'}}>Privacidad</a>
</p>
</div>
</div>
</div>
</div>
);
}

