function LearningPath({currentLang,progress,onNavigate}) {
const lang = LANGS[currentLang];
const content = CONTENT_DATA[currentLang];

const isLessonUnlocked = (stageIdx, blockIdx, lessonIdx) => {
if(stageIdx === 0 && blockIdx === 0 && lessonIdx === 0) return true;
const stages = content.stages;
let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx;
let prevLessonIdx = lessonIdx - 1;

if(prevLessonIdx < 0){
prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
prevLessonIdx = stages[prevStageIdx].blocks[prevBlockIdx].lessons.length - 1;
}

const prevLessonId = stages[prevStageIdx].blocks[prevBlockIdx].lessons[prevLessonIdx].id;
return progress.lessonProgress?.[prevLessonId]?.completed || false;
};

const isBlockUnlocked = (stageIdx, blockIdx) => {
if(stageIdx === 0 && blockIdx === 0) return true;
const stages = content.stages;
let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
const prevBlockId = stages[prevStageIdx].blocks[prevBlockIdx].id;
return progress.blockProgress?.[prevBlockId]?.passed || false;
};

return (
<div className="animate-in">
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>Ruta de Aprendizaje</h1>
<p style={{color:'var(--text2)',marginBottom:24}}>{lang.flag} {lang.name} — {lang.supportLang} | Sistema Clase + 5/9</p>

{content.stages.map((stage,si)=>{
const stageColor = STAGE_COLORS[si];
const stageLessons = stage.blocks.reduce((s,b)=>s+b.lessons.length,0);
const stageCompleted = stage.blocks.reduce((s,b)=>s+b.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length,0);
const stageProgress = stageLessons > 0 ? Math.round((stageCompleted/stageLessons)*100) : 0;
const stageUnlocked = si === 0 || progress.stageProgress?.[currentLang]?.[si] >= 100;

return (
<div key={stage.id} style={{marginBottom:32,opacity:stageUnlocked?1:0.5}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:16,flexWrap:'wrap'}}>
<div style={{width:44,height:44,borderRadius:'50%',background:stageColor,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,fontWeight:800,color:'white',flexShrink:0}}>{si+1}</div>
<div style={{flex:1,minWidth:200}}>
<div style={{fontSize:20,fontWeight:700}}>{stage.name}</div>
<div style={{fontSize:13,color:'var(--text2)'}}>Etapa {si+1} de {content.stages.length} • {stageCompleted}/{stageLessons} lecciones ({stageProgress}%)</div>
</div>
<div style={{width:200,height:10,background:'var(--surface3)',borderRadius:5}}>
<div style={{height:'100%',background:stageColor,borderRadius:5,width:stageProgress+'%',transition:'width 0.5s'}}/>
</div>
</div>

{stage.blocks.map((block,bi)=>{
const blockUnlocked = isBlockUnlocked(si, bi);
const blockPassed = progress.blockProgress?.[block.id]?.passed || false;
const blockLessonsCompleted = block.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
const blockProgress = Math.round((blockLessonsCompleted/block.lessons.length)*100);

return (
<div key={block.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:16,border:'1px solid '+(blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)'),opacity:blockUnlocked?1:0.6,transition:'var(--transition)'}}>
<div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:12,flexWrap:'wrap',gap:8}}>
<div style={{display:'flex',alignItems:'center',gap:10}}>
<div style={{width:32,height:32,borderRadius:'50%',background:blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>
{blockPassed?'✓':bi+1}
</div>
<div>
<div style={{fontSize:16,fontWeight:700}}>{block.name}</div>
<div style={{fontSize:12,color:'var(--text2)'}}>Bloque {bi+1} • {blockLessonsCompleted}/{block.lessons.length} lecciones • {blockProgress}%</div>
</div>
</div>
{blockPassed && <span style={{fontSize:12,color:'var(--success)',fontWeight:600,padding:'4px 12px',background:'#064e3b',borderRadius:12}}>✓ APROBADO</span>}
{!blockUnlocked && <span style={{fontSize:12,color:'var(--text3)',padding:'4px 12px',background:'var(--surface3)',borderRadius:12}}>🔒 BLOQUEADO</span>}
</div>

<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:16}}>
<div style={{height:'100%',background:blockPassed?'var(--success)':'var(--violet)',borderRadius:3,width:blockProgress+'%',transition:'width 0.5s'}}/>
</div>

<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:8}}>
{block.lessons.map((lesson,li)=>{
const lessonUnlocked = isLessonUnlocked(si, bi, li);
const lessonCompleted = progress.lessonProgress?.[lesson.id]?.completed || false;
const lessonScore = progress.lessonProgress?.[lesson.id]?.correct || 0;
const isNext = lessonUnlocked && !lessonCompleted;

return (
<div key={lesson.id} onClick={()=>lessonUnlocked&&onNavigate('lesson',{blockId:block.id,lessonId:lesson.id})} style={{
padding:'10px 12px',background:lessonCompleted?'#064e3b':isNext?'var(--violet)':'var(--surface2)',
border:'1px solid '+(lessonCompleted?'var(--success)':isNext?'var(--orange)':'var(--surface3)'),
borderRadius:'var(--radius-sm)',cursor:lessonUnlocked?'pointer':'default',
transition:'var(--transition)',opacity:lessonUnlocked?1:0.5,
display:'flex',alignItems:'center',gap:8
}}
onMouseOver={e=>lessonUnlocked&&!lessonCompleted&&(e.target.style.borderColor='var(--orange)')}
onMouseOut={e=>lessonUnlocked&&!lessonCompleted&&(e.target.style.borderColor=lessonCompleted?'var(--success)':'var(--violet)')}
>
<div style={{width:24,height:24,borderRadius:'50%',background:lessonCompleted?'var(--success)':lessonUnlocked?'var(--orange)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:'white',flexShrink:0}}>
{lessonCompleted?'✓':li+1}
</div>
<div style={{flex:1,minWidth:0}}>
<div style={{fontSize:12,fontWeight:600,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{lesson.title}</div>
<div style={{fontSize:10,color:'var(--text3)'}}>
{lessonCompleted ? `${lessonScore}/9 correctas` : `Lección ${li+1}`}
</div>
</div>
{!lessonUnlocked && <span style={{fontSize:10}}>🔒</span>}
{isNext && <span style={{fontSize:10,color:'var(--yellow)'}}>▶</span>}
</div>
);
})}
</div>

{blockUnlocked && blockLessonsCompleted === block.lessons.length && !blockPassed && (
<div style={{marginTop:12,padding:12,background:'var(--orange)',borderRadius:'var(--radius-sm)',textAlign:'center',cursor:'pointer',fontWeight:700,color:'white'}}
onClick={()=>onNavigate('exam',{blockId:block.id})}>
📝 PRESENTAR EXAMEN DEL BLOQUE →
</div>
)}
</div>
);
})}
</div>
);
})}
</div>
);
}

function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
const lang = LANGS[currentLang];
const [phase,setPhase] = useState('teaching'); // 'teaching' or 'quiz'
const [teachingStep,setTeachingStep] = useState(0);
const [currentQIdx,setCurrentQIdx] = useState(0);
const [selectedAnswer,setSelectedAnswer] = useState(null);
const [showFeedback,setShowFeedback] = useState(false);
const [isCorrect,setIsCorrect] = useState(null);
const [lessonComplete,setLessonComplete] = useState(false);
const [lessonFailed,setLessonFailed] = useState(false);
const [correctCount,setCorrectCount] = useState(0);
const [showUnlock,setShowUnlock] = useState(false);
const [answers,setAnswers] = useState([]);

let block=null, lesson=null, lessonIdx=-1, blockIdx=-1, stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<content.stages[si].blocks.length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];
blockIdx=bi;stageIdx=si;
lesson=block.lessons.find(l=>l.id===lessonId);
lessonIdx=block.lessons.findIndex(l=>l.id===lessonId);
break;
}
}
if(block) break;
}
if(!lesson) return <div style={{padding:40,textAlign:'center'}}>Lección no encontrada.</div>;

const lessonContent = lesson.content;
const teaching = lessonContent.teaching;
const questions = lessonContent.questions;
const totalQuestions = questions.length;
const currentQ = questions[currentQIdx];
const MIN_CORRECT = 5;

// Teaching phases
const teachingPhases = [
{title:'Introducción',content:teaching.introduction,icon:'📖'},
{title:'Anatomía de la seña',content:(
<div>
<div style={{marginBottom:12}}><strong>Configuración manual:</strong> {teaching.anatomy.handshape}</div>
<div style={{marginBottom:12}}><strong>Posición del pulgar:</strong> {teaching.anatomy.thumb}</div>
<div style={{marginBottom:12}}><strong>Orientación de la palma:</strong> {teaching.anatomy.palm}</div>
<div style={{marginBottom:12}}><strong>Orientación general:</strong> {teaching.anatomy.orientation}</div>
<div style={{marginBottom:12}}><strong>Ubicación:</strong> {teaching.anatomy.location}</div>
<div style={{marginBottom:12}}><strong>Movimiento:</strong> {teaching.anatomy.movement}</div>
<div style={{marginBottom:12}}><strong>Expresión facial:</strong> {teaching.anatomy.facialExpression}</div>
<div><strong>Repetición:</strong> {teaching.anatomy.repetition}</div>
</div>
),icon:''},
{title:'Paso a paso',content:(
<ol style={{paddingLeft:20,lineHeight:2}}>
{teaching.stepByStep.map((step,i)=><li key={i} style={{marginBottom:8}}>{step}</li>)}
</ol>
),icon:'📝'},
{title:'Errores comunes',content:(
<ul style={{paddingLeft:20,lineHeight:2}}>
{teaching.commonMistakes.map((err,i)=><li key={i} style={{marginBottom:8,color:'var(--error)'}}>✗ {err}</li>)}
</ul>
),icon:'⚠️'},
{title:'Contexto de uso',content:(
<div>
<p style={{marginBottom:12,lineHeight:1.7}}>{teaching.context}</p>
<p style={{marginBottom:12,lineHeight:1.7}}><strong>Nota cultural:</strong> {teaching.culturalNote}</p>
<p style={{lineHeight:1.7}}><strong>Ayuda visual:</strong> {teaching.visualCue}</p>
</div>
),icon:'💬'}
];

const startQuiz = () => {
setPhase('quiz');
setCurrentQIdx(0);
setSelectedAnswer(null);
setShowFeedback(false);
setIsCorrect(null);
setCorrectCount(0);
setAnswers([]);
};

const handleAnswer = (idx) => {
if(showFeedback) return;
setSelectedAnswer(idx);
const correct = currentQ.correct === idx;
setIsCorrect(correct);
setShowFeedback(true);
setAnswers([...answers, idx]);

if(correct){
setCorrectCount(correctCount + 1);
}

const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
const prev = lp[lessonId] || {completed:false,correct:0,total:0,attempts:0};
lp[lessonId] = {
...prev,
correct: correct ? prev.correct + 1 : prev.correct,
total: prev.total + 1,
attempts: prev.attempts + 1
};
newProgress.lessonProgress = lp;
onComplete(newProgress);
};

const nextQuestion = () => {
if(currentQIdx < totalQuestions - 1){
setCurrentQIdx(currentQIdx + 1);
setSelectedAnswer(null);
setShowFeedback(false);
setIsCorrect(null);
} else {
const passed = correctCount >= MIN_CORRECT;

if(passed){
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
lp[lessonId] = {
...(lp[lessonId] || {correct:0,total:0,attempts:0}),
completed: true,
correct: correctCount,
total: totalQuestions
};
newProgress.lessonProgress = lp;

const totalLessons = content.stages.reduce((s,st)=>s+st.blocks.reduce((bs,b)=>bs+b.lessons.length,0),0);
const completedLessons = Object.values(lp).filter(v=>v.completed).length;
const cp = {...(newProgress.courseProgress||{})};
cp[currentLang] = Math.round((completedLessons/totalLessons)*100);
newProgress.courseProgress = cp;

const today = new Date().toDateString();
if(newProgress.lastActiveDate !== today){
newProgress.todayLessons = 1;
newProgress.lastActiveDate = today;
const yesterday = new Date(Date.now()-86400000).toDateString();
if(newProgress.lastActiveDateBefore === yesterday || !newProgress.lastActiveDateBefore){
newProgress.streak = (newProgress.streak||0) + 1;
} else {
newProgress.streak = 1;
}
newProgress.lastActiveDateBefore = today;
newProgress.activeDays = (newProgress.activeDays||0) + 1;
} else {
newProgress.todayLessons = (newProgress.todayLessons||0) + 1;
}

const hour = new Date().getHours();
if(hour < 8) newProgress.earlyLessons = (newProgress.earlyLessons||0) + 1;
if(hour >= 22) newProgress.nightLessons = (newProgress.nightLessons||0) + 1;

const stage = content.stages[stageIdx];
const stageLessons = stage.blocks.reduce((s,b)=>s+b.lessons.length,0);
const stageCompleted = stage.blocks.reduce((s,b)=>s+b.lessons.filter(l=>lp[l.id]?.completed).length,0);
const sp = {...(newProgress.stageProgress||{})};
sp[currentLang] = {...(sp[currentLang]||{})};
sp[currentLang][stageIdx+1] = Math.round((stageCompleted/stageLessons)*100);
newProgress.stageProgress = sp;

onComplete(newProgress);
setLessonComplete(true);

let nextLessonExists = false;
if(lessonIdx < block.lessons.length - 1) nextLessonExists = true;
else if(blockIdx < content.stages[stageIdx].blocks.length - 1) nextLessonExists = true;
if(nextLessonExists){
setShowUnlock(true);
setTimeout(()=>setShowUnlock(false),3000);
}
} else {
setLessonFailed(true);
}
}
};

const restartLesson = () => {
setPhase('teaching');
setTeachingStep(0);
setCurrentQIdx(0);
setSelectedAnswer(null);
setShowFeedback(false);
setIsCorrect(null);
setLessonFailed(false);
setLessonComplete(false);
setCorrectCount(0);
setAnswers([]);
};

// Failed screen
if(lessonFailed){
return (
<div className="animate-in shake-anim" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide message={`Obtuviste ${correctCount} de ${totalQuestions} correctas. Necesitas mínimo ${MIN_CORRECT}/9 para avanzar. ¡Repasa la clase y vuelve a intentarlo!`} expression="sad"/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'2px solid var(--error)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>😔</div>
<h2 style={{fontSize:28,fontWeight:800,color:'var(--error)',marginBottom:8}}>Lección No Aprobada</h2>
<p style={{color:'var(--text2)',fontSize:16,marginBottom:8}}>{lesson.title}</p>

<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:20,marginTop:16}}>
<div style={{fontSize:48,fontWeight:800,color:'var(--error)'}}>{correctCount}/{totalQuestions}</div>
<div style={{fontSize:14,color:'var(--text2)',marginTop:8}}>Necesitas {MIN_CORRECT}/{totalQuestions} para avanzar</div>
<div style={{fontSize:13,color:'var(--text3)',marginTop:4}}>Te faltaron {MIN_CORRECT - correctCount} respuestas correctas</div>
</div>

<div style={{marginTop:16,padding:16,background:'#7f1d1d',borderRadius:'var(--radius-sm)',border:'1px solid var(--error)'}}>
<p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>
<strong>📚 Regla de continuidad:</strong> Para mantener la calidad del aprendizaje, debes demostrar comprensión suficiente antes de avanzar. Vuelve a estudiar la clase y repite la lección.
</p>
</div>
</div>

<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
<button onClick={restartLesson} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}
onMouseOver={e=>e.target.style.background='#e07b1a'} onMouseOut={e=>e.target.style.background='var(--orange)'}>
🔄 Reiniciar lección (volver a la clase)
</button>
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>
Volver a la ruta
</button>
</div>
</div>
);
}

// Completed screen
if(lessonComplete){
const nextLessonId = lessonIdx < block.lessons.length - 1
? block.lessons[lessonIdx + 1].id
: (blockIdx < content.stages[stageIdx].blocks.length - 1
? content.stages[stageIdx].blocks[blockIdx + 1].lessons[0].id
: null);

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide message={`¡Excelente! Obtuviste ${correctCount}/${totalQuestions} correctas en "${lesson.title}". ${nextLessonId?'¡La siguiente lección ha sido desbloqueada!':'¡Has completado todas las lecciones de este bloque!'}`} expression="celebrating"/>

{showUnlock && nextLessonId && (
<div className="unlock-anim" style={{background:'linear-gradient(135deg,var(--orange),var(--yellow))',borderRadius:'var(--radius)',padding:20,marginTop:20,textAlign:'center',color:'var(--black)'}}>
<div style={{fontSize:40,marginBottom:8}}>🔓</div>
<div style={{fontSize:20,fontWeight:800}}>¡NUEVA LECCIÓN DESBLOQUEADA!</div>
<div style={{fontSize:14,marginTop:8}}>Continúa tu progreso en {lang.code}</div>
</div>
)}

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:48,marginBottom:12}}>🎉</div>
<h2 style={{fontSize:24,fontWeight:700,marginBottom:8}}>¡Lección Aprobada!</h2>
<p style={{color:'var(--text2)'}}>{lesson.title} — {lang.code}</p>

<div style={{background:'#064e3b',borderRadius:'var(--radius-sm)',padding:20,marginTop:16,border:'1px solid var(--success)'}}>
<div style={{fontSize:48,fontWeight:800,color:'var(--success)'}}>{correctCount}/{totalQuestions}</div>
<div style={{fontSize:14,color:'var(--text)',marginTop:8}}>✓ Superaste el mínimo de {MIN_CORRECT}/{totalQuestions}</div>
<div style={{fontSize:13,color:'var(--text2)',marginTop:4}}>Lección {lessonIdx+1} de {block.lessons.length} en este bloque</div>
</div>

<div style={{marginTop:16,display:'flex',gap:6,justifyContent:'center',flexWrap:'wrap'}}>
{answers.map((a,i)=>(
<div key={i} style={{width:28,height:28,borderRadius:'50%',background:a===questions[i].correct?'var(--success)':'var(--error)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:'white'}}>{i+1}</div>
))}
</div>
</div>

<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
{nextLessonId && (
<button onClick={()=>{onBack();setTimeout(()=>onNavigate('lesson',{blockId:blockId,lessonId:nextLessonId}),100)}} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}
onMouseOver={e=>e.target.style.background='#e07b1a'} onMouseOut={e=>e.target.style.background='var(--orange)'}>
▶ Siguiente lección
</button>
)}
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>
Volver a la ruta
</button>
</div>
</div>
);
}

// TEACHING PHASE
if(phase === 'teaching'){
const currentTeachingPhase = teachingPhases[teachingStep];
const teachingProgress = ((teachingStep + 1) / teachingPhases.length) * 100;

// Determine which hand sign SVG to show
const handSignMap = {
'Letra A': 'A', 'Letra B': 'B', 'Letra C': 'C', 'Letra D': 'D',
'Letra E': 'E', 'Letra F': 'F',
'Vocal A': 'VOWEL_A', 'Vocal E': 'VOWEL_E', 'Vocal I': 'VOWEL_I',
'Vocal O': 'VOWEL_O', 'Vocal U': 'VOWEL_U',
'Número 1': 'NUM1', 'Número 2': 'NUM2', 'Número 3': 'NUM3',
'HOLA': 'HELLO', 'GRACIAS': 'THANKS', 'MAMÁ': 'MOM', 'PAPÁ': 'DAD',
'SÍ': 'YES', 'NO': 'NO'
};
const svgType = handSignMap[lesson.title];

return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}}>← Volver</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:16,marginBottom:16,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<div style={{width:36,height:36,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>
{lessonIdx+1}
</div>
<div style={{flex:1,minWidth:200}}>
<div style={{fontSize:12,color:'var(--text2)'}}>{block.name}</div>
<div style={{fontSize:16,fontWeight:700}}>{lesson.title}</div>
</div>
<div style={{background:'var(--violet)',padding:'4px 12px',borderRadius:12,fontSize:12,fontWeight:700,color:'white'}}>
📚 CLASE
</div>
</div>

<div style={{marginBottom:20}}>
<div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}>
<span style={{fontSize:13,color:'var(--text2)'}}>Progreso de la clase</span>
<span style={{fontSize:13,color:'var(--text2)'}}>{teachingStep+1}/{teachingPhases.length}</span>
</div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3}}>
<div style={{height:'100%',background:'var(--violet)',borderRadius:3,width:teachingProgress+'%',transition:'width 0.3s'}}/>
</div>
</div>

<DigiGuide
message={`Fase ${teachingStep+1}: ${currentTeachingPhase.title}. ${teachingStep===0?'Lee atentamente la introducción.':teachingStep===1?'Estudia la anatomía de la seña.':teachingStep===2?'Sigue los pasos en orden.':teachingStep===3?'Evita estos errores comunes.':'Aprende el contexto y uso.'}`}
expression="teaching"
/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:20}}>
<span style={{fontSize:32}}>{currentTeachingPhase.icon}</span>
<h2 style={{fontSize:22,fontWeight:700,color:'var(--orange)'}}>{currentTeachingPhase.title}</h2>
</div>

{svgType && teachingStep === 1 && (
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,textAlign:'center',marginBottom:20,border:'2px solid var(--violet)'}}>
<HandSVG type={svgType} size={220}/>
<p style={{fontSize:12,color:'var(--text3)',marginTop:8,fontStyle:'italic'}}>Ilustración anatómica de referencia</p>
</div>
)}

<div style={{fontSize:15,lineHeight:1.8,color:'var(--text)'}}>
{currentTeachingPhase.content}
</div>

{teachingStep === 1 && svgType && (
<div style={{marginTop:20,padding:16,background:'var(--surface2)',borderRadius:'var(--radius-sm)',borderLeft:'3px solid var(--violet)'}}>
<div style={{fontSize:13,fontWeight:700,color:'var(--violet)',marginBottom:8}}>📋 Detalles anatómicos completos:</div>
<div style={{fontSize:13,color:'var(--text2)',lineHeight:1.8}}>
<div><strong>• Configuración:</strong> {teaching.anatomy.handshape}</div>
<div><strong>• Pulgar:</strong> {teaching.anatomy.thumb}</div>
<div><strong>• Palma:</strong> {teaching.anatomy.palm}</div>
<div><strong>• Orientación:</strong> {teaching.anatomy.orientation}</div>
<div><strong>• Ubicación:</strong> {teaching.anatomy.location}</div>
<div><strong>• Movimiento:</strong> {teaching.anatomy.movement}</div>
<div><strong>• Expresión facial:</strong> {teaching.anatomy.facialExpression}</div>
<div><strong>• Repetición:</strong> {teaching.anatomy.repetition}</div>
</div>
</div>
)}
</div>

<div style={{marginTop:20,display:'flex',justifyContent:'space-between',gap:12}}>
{teachingStep > 0 && (
<button onClick={()=>setTeachingStep(teachingStep-1)} style={{padding:'12px 24px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600}}>
← Anterior
</button>
)}
<div style={{flex:1}}/>
<button onClick={()=>{
if(teachingStep < teachingPhases.length - 1){
setTeachingStep(teachingStep + 1);
} else {
startQuiz();
}
}} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
{teachingStep < teachingPhases.length - 1 ? 'Siguiente fase →' : 'Comenzar evaluación (9 preguntas) →'}
</button>
</div>
</div>
);
}

// QUIZ PHASE
const quizProgress = ((currentQIdx)/totalQuestions)*100;

return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}}>← Volver</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:16,marginBottom:16,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<div style={{width:36,height:36,borderRadius:'50%',background:'var(--orange)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>
{lessonIdx+1}
</div>
<div style={{flex:1,minWidth:200}}>
<div style={{fontSize:12,color:'var(--text2)'}}>{block.name}</div>
<div style={{fontSize:16,fontWeight:700}}>{lesson.title}</div>
</div>
<div style={{background:'var(--orange)',padding:'4px 12px',borderRadius:12,fontSize:12,fontWeight:700,color:'white'}}>
📝 EVALUACIÓN
</div>
</div>

<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:12,marginBottom:16,border:'1px solid '+(correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)')}}>
<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6,flexWrap:'wrap',gap:8}}>
<span style={{fontSize:13,fontWeight:600}}>Progreso de lección</span>
<span style={{fontSize:13,fontWeight:600,color:correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)'}}>
{correctCount} correctas de {currentQIdx + (showFeedback?1:0)} | Mínimo: {MIN_CORRECT}/{totalQuestions}
</span>
</div>
<div style={{height:8,background:'var(--surface3)',borderRadius:4}}>
<div style={{height:'100%',background:'var(--violet)',borderRadius:4,width:quizProgress+'%',transition:'width 0.3s'}}/>
</div>
<div style={{display:'flex',justifyContent:'space-between',marginTop:4}}>
<span style={{fontSize:11,color:'var(--text3)'}}>{Math.round(quizProgress)}% completado</span>
<span style={{fontSize:11,color:correctCount>=MIN_CORRECT?'var(--success)':'var(--text3)'}}>
{correctCount>=MIN_CORRECT?'✓ Ya aprobaste':'Necesitas '+(MIN_CORRECT-correctCount)+' más'}
</span>
</div>
</div>

<DigiGuide
message={
currentQIdx === 0 ? '¡Comenzamos la evaluación! Responde las 9 preguntas basándote en la clase. Necesitas 5 correctas para avanzar.' :
correctCount >= MIN_CORRECT ? `¡Ya tienes ${correctCount} correctas! Sigue así para completar la lección.` :
`Llevas ${correctCount} correctas. Necesitas ${MIN_CORRECT} para avanzar. ¡Tú puedes!`
}
expression={correctCount >= MIN_CORRECT ? 'excited' : currentQIdx > 5 && correctCount < MIN_CORRECT ? 'thinking' : 'encouraging'}
/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
{currentQ.handSign && (
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,textAlign:'center',marginBottom:16,border:'2px solid var(--surface3)'}}>
<HandSVG type={currentQ.handSign} size={180}/>
<p style={{fontSize:11,color:'var(--text3)',marginTop:8,fontStyle:'italic'}}>Ilustración de referencia</p>
</div>
)}

<h3 style={{fontSize:17,fontWeight:700,marginBottom:20}}>{currentQ.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{currentQ.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showFeedback){
if(i===currentQ.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}
else if(i===selectedAnswer&&i!==currentQ.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}
} else if(selectedAnswer===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (
<button key={i} onClick={()=>handleAnswer(i)} disabled={showFeedback} style={{
padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',
color:color,cursor:showFeedback?'default':'pointer',fontSize:15,textAlign:'left',transition:'var(--transition)',fontWeight:selectedAnswer===i?600:400
}}
onMouseOver={e=>!showFeedback&&(e.target.style.borderColor='var(--violet)')}
onMouseOut={e=>!showFeedback&&(e.target.style.borderColor=selectedAnswer===i?'var(--violet)':'var(--surface3)')}
>
