function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
const [currentQ,setCurrentQ] = useState(0);
const [answers,setAnswers] = useState([]);
const [selected,setSelected] = useState(null);
const [showResult,setShowResult] = useState(false);
const [examComplete,setExamComplete] = useState(false);

let block=null,blockIdx=-1,stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<content.stages[si].blocks.length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];blockIdx=bi;stageIdx=si;break;
}
}
if(block) break;
}
if(!block) return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;

const questions = [];
block.lessons.forEach(l=>{
l.content.questions.forEach(q=>{
questions.push({question:q.question,options:q.options,correct:q.correct,explanation:q.explanation,lessonId:l.id,lessonTitle:l.title});
});
});
const examQuestions = questions.slice(0, 10);

const q = examQuestions[currentQ];
const passThreshold = 80;
const score = answers.filter((a,i)=>a===examQuestions[i]?.correct).length;
const scorePct = examQuestions.length > 0 ? Math.round((score/examQuestions.length)*100) : 0;
const passed = scorePct >= passThreshold;

const handleAnswer = (idx) => {
if(showResult) return;
setSelected(idx);
setShowResult(true);
};

const nextQuestion = () => {
const newAnswers = [...answers, selected];
setAnswers(newAnswers);
if(currentQ < examQuestions.length-1){
setCurrentQ(currentQ+1);
setSelected(null);
setShowResult(false);
} else {
setExamComplete(true);
const newProgress = {...progress};
const bp = {...(newProgress.blockProgress||{})};
bp[blockId] = {passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};
newProgress.blockProgress = bp;
const er = {...(newProgress.examResults||{})};
er[blockId] = {score:scorePct,passed:scorePct>=passThreshold,date:new Date().toISOString(),attempts:(er[blockId]?.attempts||0)+1};
newProgress.examResults = er;

if(scorePct>=passThreshold){
const sp = {...(newProgress.stageProgress||{})};
sp[currentLang] = {...(sp[currentLang]||{})};
sp[currentLang][stageIdx+1] = 100;
newProgress.stageProgress = sp;
}
onComplete(newProgress);
}
};

if(examComplete){
let nextBlockId = null;
if(blockIdx < content.stages[stageIdx].blocks.length - 1){
nextBlockId = content.stages[stageIdx].blocks[blockIdx + 1].id;
} else if(stageIdx < content.stages.length - 1){
nextBlockId = content.stages[stageIdx + 1].blocks[0].id;
}

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide
message={passed?`¡Felicidades! Aprobaste con ${scorePct}%. ¡Siguiente bloque desbloqueado!`:`Obtuviste ${scorePct}%. Necesitas ${passThreshold}%. ¡Repasa y vuelve a intentar!`}
expression={passed?'celebrating':'encouraging'}
action={onBack}
actionLabel={passed?'Continuar':'Repasar lecciones'}
/>

{passed && nextBlockId && (
<div className="unlock-anim" style={{background:'linear-gradient(135deg,var(--success),#22c55e)',borderRadius:'var(--radius)',padding:20,marginTop:20,textAlign:'center',color:'white'}}>
<div style={{fontSize:40,marginBottom:8}}>🔓</div>
<div style={{fontSize:20,fontWeight:800}}>¡NUEVO BLOQUE DESBLOQUEADO!</div>
<div style={{fontSize:14,marginTop:8}}>Continúa tu progreso en {LANGS[currentLang].code}</div>
</div>
)}

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div>
<h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2>
<p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'¡EXAMEN APROBADO!':'Necesitas repasar'}</p>
<p style={{color:'var(--text3)',fontSize:14,marginTop:4}}>{score} de {examQuestions.length} correctas</p>
</div>

<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
{passed && nextBlockId && (
<button onClick={()=>{onBack();setTimeout(()=>{const nextStage=content.stages.find(s=>s.blocks.some(b=>b.id===nextBlockId));const nextBlock=nextStage?.blocks.find(b=>b.id===nextBlockId);if(nextBlock)onNavigate('lesson',{blockId:nextBlockId,lessonId:nextBlock.lessons[0]?.id})},100)}} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}>
▶ Ir al siguiente bloque
</button>
)}
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>
Volver a la ruta
</button>
</div>
</div>
);
}

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}}>← Salir del examen</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}>
<div>
<div style={{fontSize:13,color:'var(--text2)'}}>Examen de bloque</div>
<div style={{fontSize:18,fontWeight:700}}>{block.name}</div>
</div>
<div style={{textAlign:'right'}}>
<div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div>
<div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{examQuestions.length}</div>
</div>
</div>

<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}>
<div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/examQuestions.length*100)+'%',transition:'width 0.3s'}}/>
</div>

<DigiGuide message="Responde cuidadosamente. Necesitas 80% para aprobar." expression="thinking"/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<h3 style={{fontSize:18,fontWeight:700,marginBottom:20}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{q.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showResult){
if(i===q.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}
else if(i===selected&&i!==q.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}
} else if(selected===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (
<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{
padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',
color:color,cursor:showResult?'default':'pointer',fontSize:15,textAlign:'left'
}}>
<span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}
</button>
);
})}
</div>
{showResult && (
