{menuItems.map(item=>(<button key={item.id} onClick={()=>{onNavigate(item.id);onCloseSidebar()}} style={{width:'100%',display:'flex',alignItems:'center',gap:12,padding:'12px 20px',background:currentScreen===item.id?'var(--surface2)':'transparent',border:'none',borderLeft:currentScreen===item.id?'3px solid var(--violet)':'3px solid transparent',color:currentScreen===item.id?'var(--text)':'var(--text2)',cursor:'pointer',fontSize:14,textAlign:'left',fontWeight:currentScreen===item.id?600:400}}><span style={{fontSize:18}}>{item.icon}</span>{item.label}</button>))}
</nav>
<div style={{padding:16,borderTop:'1px solid var(--surface3)'}}><button onClick={onLogout} style={{width:'100%',padding:'10px',background:'transparent',border:'1px solid var(--error)',borderRadius:'var(--radius-sm)',color:'var(--error)',cursor:'pointer',fontSize:14,fontWeight:600}}>🚪 Cerrar Sesión</button></div>
