function App() {
const [user,setUser] = useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang] = useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen] = useState('home');
const [sidebarOpen,setSidebarOpen] = useState(false);
const [progress,setProgress] = useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0}));
const [settings,setSettings] = useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson] = useState(null);
const [activeExam,setActiveExam] = useState(null);
const [newAchievement,setNewAchievement] = useState(null);

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
let changed = false;
ACHIEVEMENT_DEFS.forEach(a=>{if(!newAchievements.includes(a.id) && a.condition(progress)){newAchievements.push(a.id);changed = true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});
if(changed) setProgress(p=>({...p,achievements:newAchievements}));
},[progress]);

const handleAuth = (userData) => {setUser(userData);setStorage('currentUser',userData);setCurrentScreen('home');};
const handleLogout = () => {setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};
const handleLangChange = (lang) => {if(activeLesson || activeExam){if(!confirm('¿Cambiar lengua?')) return;}setCurrentLang(lang);setActiveLesson(null);setActiveExam(null);setCurrentScreen('home');};

const handleNavigate = (screen, params) => {
if(screen==='lesson' && params){setActiveLesson(params);setCurrentScreen('lesson');window.scrollTo(0,0);}
else if(screen==='exam' && params){setActiveExam(params);setCurrentScreen('exam');window.scrollTo(0,0);}
else {setActiveLesson(null);setActiveExam(null);setCurrentScreen(screen);window.scrollTo(0,0);}
};

const handleProgressUpdate = (newProgress) => {setProgress(newProgress);};
const handleStartReview = (lessonId) => {for(const lang of Object.keys(CONTENT_DATA)){for(const stage of CONTENT_DATA[lang].stages){for(const block of stage.blocks){const lesson = block.lessons.find(l=>l.id===lessonId);if(lesson){setActiveLesson({blockId:block.id,lessonId:lessonId});setCurrentScreen('lesson');return;}}}}};

if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
if(currentScreen==='lesson' && activeLesson) return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={()=>handleNavigate('path')}/>;
if(currentScreen==='exam' && activeExam) return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={()=>handleNavigate('path')}/>;
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate}/>;
case 'review': return <div className="animate-in"><h1 style={{fontSize:28,fontWeight:800,marginBottom:24}}>Repaso</h1><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></div>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress}/>;
case 'achievements': return <AchievementsPage progress={progress}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings}/>;
case 'help': return <HelpPage/>;
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress}/>;
}
};

return (
<div style={{display:'flex',minHeight:'100vh'}}>
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)}/>
<div style={{flex:1,marginLeft:0,transition:'var(--transition)',minHeight:'100vh'}}>
<header style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
