const getHardQuestions = (lessonName, data) => {
const questions = [
{question:'Al realizar esta sena, un observador nota que el ejecutante mantiene los dedos ligeramente separados entre si. ¿Que problema presenta esta ejecucion?',options:['La sena sigue siendo valida porque los dedos siempre tienen pequenas separaciones naturales','Se esta usando una configuracion diferente a la requerida, lo que puede cambiar el significado','Es un error menor que no afecta la comprension del mensaje','La separacion entre dedos es requerida en todas las senas de LSM'],correct:1,explanation:'En LSM, la configuracion de los dedos (juntos o separados) es un parametro distintivo. Usar dedos separados cuando deben estar juntos puede cambiar completamente el significado.'},
{question:'Durante una conversacion, una persona realiza esta sena mirando hacia el suelo en lugar de mantener contacto visual. ¿Como afecta esto a la comunicacion?',options:['No afecta porque lo importante es el movimiento de la mano','La sena pierde parte de su significado porque el contacto visual es un componente gramatical en LSM','Solo afecta si la otra persona es muy exigente con la etiqueta','El contacto visual solo es necesario al inicio de la conversacion'],correct:1,explanation:'En las lenguas de senas, el contacto visual es parte de la gramatica. Interrumpir el contacto visual equivale a "dejar de escuchar" en una lengua oral.'},
{question:'Un estudiante observa que al ejecutar esta sena, su muneca se flexiona ligeramente hacia adelante durante el movimiento. ¿Es esto aceptable?',options:['Si, porque la flexion de muneca anade naturalidad al movimiento','No, porque la muneca debe mantenerse alineada con el antebrazo para una ejecucion correcta','Depende de la velocidad del movimiento','Solo es problema si la flexion es muy pronunciada'],correct:1,explanation:'La muneca debe mantenerse alineada con el antebrazo. Una muneca flexionada puede distorsionar la configuracion manual y hacer la sena menos clara.'},
{question:'¿En que situacion seria MAS apropiado usar una expresion facial seria en lugar de sonriente al realizar esta sena?',options:['Cuando se saluda a un superior jerarquico','Nunca, porque todas las senas requieren sonrisa','Cuando el contexto emocional de la conversacion lo requiere','Solo en contextos formales de trabajo'],correct:2,explanation:'La expresion facial en LSM debe coincidir con el contexto emocional de la comunicacion.'},
{question:'Dos personas ejecutan esta misma sena: una con la mano derecha y otra con la mano izquierda. ¿Ambas ejecuciones son correctas?',options:['No, solo la mano derecha es valida en LSM','Si, siempre que cada persona use su mano dominante de forma consistente','Depende de la region de Mexico donde se encuentren','Solo es correcto si ambas usan la misma mano'],correct:1,explanation:'En LSM, cada persona usa su mano dominante. Lo importante es la consistencia.'},
{question:'Al observar esta sena desde atras del ejecutante, ¿que elemento seria MAS dificil de identificar correctamente?',options:['La configuracion de los dedos','La expresion facial','La posicion general de la mano','El movimiento del brazo'],correct:1,explanation:'La expresion facial es un componente crucial que solo es visible de frente.'},
{question:'Un principiante ejecuta esta sena muy rapidamente, completandola en menos de un segundo. ¿Que problema presenta?',options:['Ninguno, la velocidad demuestra fluidez','La sena puede volverse irreconocible porque no da tiempo a percibir sus componentes','Es preferible hacerla rapido para no aburrir al interlocutor','Solo es problema si la otra persona no entiende'],correct:1,explanation:'Las senas deben ejecutarse con claridad y ritmo adecuado.'},
{question:'¿Que diferencia fundamental existe entre esta sena y una sena similar que se ejecuta en una posicion corporal diferente?',options:['Ninguna, la posicion corporal no afecta el significado','Puede cambiar completamente el significado o referirse a un concepto diferente','Solo cambia la formalidad del mensaje','La diferencia es meramente estetica'],correct:1,explanation:'En LSM, la ubicacion es uno de los parametros fundamentales. Cambiarla puede cambiar el significado completamente.'},
{question:'Si esta sena se ejecuta con la palma mirando hacia el ejecutante en lugar de hacia el interlocutor, ¿que sucede?',options:['El significado se mantiene igual porque la palma no es importante','Se altera la orientacion, que es un parametro distintivo de la sena','Solo afecta la estetica del movimiento','Es una variacion aceptada en algunas regiones'],correct:1,explanation:'La orientacion de la palma es uno de los cinco parametros fundamentales de las senas.'}
];
return questions.sort(() => Math.random() - 0.5).slice(0, 9);
