if(compact) {return (<div style={{position:'relative'}}><button onClick={()=>setOpen(!open)} style={{display:'flex',alignItems:'center',gap:8,padding:'8px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',cursor:'pointer',fontSize:14,fontWeight:600}}><span>{current.flag}</span><span>{current.code}</span><span style={{fontSize:10}}>{open?'▲':'▼'}</span></button>{open && (<div style={{position:'absolute',top:'100%',right:0,marginTop:4,background:'var(--surface)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',boxShadow:'var(--shadow)',zIndex:200,minWidth:200}}>{langs.map(l=>(<button key={l.id} onClick={()=>{onSelect(l.id);setOpen(false)}} style={{width:'100%',display:'flex',alignItems:'center',gap:10,padding:'12px 16px',background:currentLang===l.id?'var(--violet)':'transparent',border:'none',color:'var(--text)',cursor:'pointer',fontSize:14,textAlign:'left'}}><span>{l.flag}</span><div><div style={{fontWeight:600}}>{l.code}</div><div style={{fontSize:11,color:'var(--text2)'}}>{l.name}</div></div></button>))}</div>)}</div>);}
return (<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))',gap:12}}>{langs.map(l=>(<button key={l.id} onClick={()=>onSelect(l.id)} style={{padding:20,background:currentLang===l.id?'var(--violet)':'var(--surface2)',border:currentLang===l.id?'2px solid var(--orange)':'2px solid var(--surface3)',borderRadius:'var(--radius)',cursor:'pointer',textAlign:'left',color:'var(--text)'}}><div style={{fontSize:28,marginBottom:8}}>{l.flag}</div><div style={{fontSize:18,fontWeight:700}}>{l.code}</div><div style={{fontSize:13,color:'var(--text2)',marginTop:4}}>{l.name}</div>{currentLang===l.id && <div style={{marginTop:8,fontSize:12,color:'var(--yellow)',fontWeight:600}}>Activa</div>}</button>))}</div>);
