const buildContent = (lang) => {
try {
const stages = STAGE_DATA[lang] || STAGE_DATA.lsm;
return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: stage.blocks.map((block, bi) => ({
id: lang+'-s'+(si+1)+'-b'+(bi+1),
name: block.name,
lessons: block.lessons.map((lessonName, li) => {
const lessonData = getLessonData(lessonName);
const handSignMap = {'Letra A':'A','Letra B':'B','Leccion 1 - HOLA':'HELLO','Leccion 4 - GRACIAS':'THANKS','MAMA':'MOM','PAPA':'DAD','SI':'YES','NO':'NO','Numero 1':'NUM1','Numero 2':'NUM2','Numero 3':'NUM3','Numero 5':'NUM5'};
return {
id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),
title: lessonName,
handSign: handSignMap[lessonName] || null,
content: {
teaching: lessonData,
questions: getHardQuestions(lessonName, lessonData)
}
};
})
}))
}))
};
} catch(e) {
console.error('Error building content for', lang, e);
return {stages:[]};
}
};

const getHardQuestions = (lessonName, data) => {
return [
{question:'¿Que configuracion manual usa esta sena?',options:['Configuracion A','Configuracion B',data.anatomy.handshape,'Configuracion 5'],correct:2,explanation:'La configuracion correcta es: '+data.anatomy.handshape},
{question:'¿Donde se ubica esta sena?',options:['Pecho','Cabeza','Abdomen',data.anatomy.location],correct:3,explanation:'Ubicacion: '+data.anatomy.location},
{question:'¿Que tipo de movimiento tiene?',options:['Sin movimiento','Circular','Lateral',data.anatomy.movement],correct:3,explanation:'Movimiento: '+data.anatomy.movement},
{question:'¿Cual es un error comun?',options:['Rapido',data.mistakes[0],'Sin mirar','Todas'],correct:1,explanation:'Error: '+data.mistakes[0]},
{question:'¿Que expresion facial usa?',options:['Neutra','Enojada','Triste',data.anatomy.facialExpression],correct:3,explanation:'Expresion: '+data.anatomy.facialExpression},
{question:'¿En que contexto se usa?',options:['Solo formal','Solo familia',data.context.split('.')[0],'Solo escuela'],correct:2,explanation:data.context},
{question:'¿Cuantas veces se repite?',options:['Una','Dos','Tres',data.anatomy.repetition],correct:3,explanation:'Repeticion: '+data.anatomy.repetition},
{question:'¿Que nota cultural es importante?',options:['Sin importancia','Solo Mexico',data.cultural.split('.')[0],'Igual en todas'],correct:2,explanation:data.cultural},
{question:'¿Cual es el primer paso?',options:['Rapido',data.steps[0],'Gritar','Cerrar ojos'],correct:1,explanation:'Primer paso: '+data.steps[0]}
];
};

const CONTENT_DATA = {};
try {
CONTENT_DATA.lsm = buildContent('lsm');
CONTENT_DATA.lsf = buildContent('lsf');
CONTENT_DATA.asl = buildContent('asl');
CONTENT_DATA.lsc = buildContent('lsc');
} catch(e) {
