const buildContent = (lang) => {
const stages = STAGE_DATA[lang] || STAGE_DATA.lsm;
const handSignMap = {'Letra A':'A','Letra B':'B','Leccion 1 - HOLA':'HELLO','Leccion 4 - GRACIAS':'THANKS','MAMA':'MOM','PAPA':'DAD','SI':'YES','NO':'NO','Numero 1':'NUM1','Numero 2':'NUM2','Numero 3':'NUM3','Numero 5':'NUM5'};

return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: (stage.blocks || []).map((block, bi) => ({
id: lang+'-s'+(si+1)+'-b'+(bi+1),
name: block.name,
lessons: (block.lessons || []).map((lessonName, li) => {
const lessonData = getLessonData(lessonName);
return {
id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),
title: lessonName,
handSign: handSignMap[lessonName] || null,
content: {
teaching: lessonData,
questions: getHardQuestions(lessonName, lessonData)
}
};
})
}))
}))
};
};

