const buildContent = (lang) => {
const stageMap = {lsm: STAGE_DATA_LSM, lsf: STAGE_DATA_LSF, asl: STAGE_DATA_ASL, lsc: STAGE_DATA_LSC};
const stages = stageMap[lang] || STAGE_DATA_LSM;
const handSignMap = {'Letra A':'A','Letra B':'B','Letter A':'A','Letter B':'B','Lettre A':'A','Lettre B':'B','Leccion 1 - HOLA':'HELLO','Lesson 1 - HELLO':'HELLO','Lecon 1 - BONJOUR':'HELLO','Leccion 3 - GRACIAS':'THANKS','Lesson 3 - THANK YOU':'THANKS','Lecon 3 - MERCI':'THANKS','MAMA':'MOM','MAMAN':'MOM','PAPA':'DAD','PAPA':'DAD','SI':'YES','OUI':'YES','NO':'NO','NON':'NO'};

return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: (stage.blocks || []).map((block, bi) => ({
id: lang+'-s'+(si+1)+'-b'+(bi+1),
name: block.name,
lessons: (block.lessons || []).map((lessonName, li) => {
const lessonData = getLessonData(lessonName, lang);
return {
id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),
title: lessonName,
handSign: handSignMap[lessonName] || null,
content: {
teaching: lessonData,
questions: getHardQuestions(lessonName, lessonData, lang)
}
};
})
}))
}))
};
};

