<style>
*{margin:0;padding:0;box-sizing:border-box}
:root{--orange:#F28C28;--violet:#6657C8;--black:#171717;--yellow:#FFD447;--white:#FFFFFF;--bg:#0f0f1a;--surface:#1a1a2e;--surface2:#252540;--surface3:#2f2f4a;--text:#e8e8f0;--text2:#a0a0b8;--text3:#6b6b80;--success:#4ade80;--error:#f87171;--radius:12px;--radius-sm:8px;--radius-lg:16px;--shadow:0 4px 24px rgba(0,0,0,0.3);--transition:all 0.3s cubic-bezier(0.4,0,0.2,1)}
html{font-size:16px}
body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;overflow-x:hidden}
#root{min-height:100vh}
::-webkit-scrollbar{width:6px}
::-webkit-scrollbar-track{background:var(--surface)}
::-webkit-scrollbar-thumb{background:var(--violet);border-radius:3px}
@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@keyframes bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes unlock{0%{transform:scale(0.8);opacity:0}50%{transform:scale(1.1)}100%{transform:scale(1);opacity:1}}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-10px)}75%{transform:translateX(10px)}}
@keyframes modalIn{from{opacity:0;transform:scale(0.9) translateY(20px)}to{opacity:1;transform:scale(1) translateY(0)}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
@keyframes spinIn{0%{opacity:0;transform:rotate(-180deg) scale(0.5)}100%{opacity:1;transform:rotate(0deg) scale(1)}}
@keyframes fadeOut{0%{opacity:1}100%{opacity:0}}
.animate-in{animation:fadeIn 0.4s ease-out}
.unlock-anim{animation:unlock 0.5s ease-out}
.shake-anim{animation:shake 0.5s ease-out}
.modal-in{animation:modalIn 0.3s ease-out}
.pulse-btn{animation:pulse 2s infinite}
.back-btn{display:inline-flex;align-items:center;gap:8px;padding:10px 18px;background:var(--surface2);border:1px solid var(--surface3);border-radius:var(--radius-sm);color:var(--text2);cursor:pointer;font-size:14px;font-weight:600;transition:var(--transition);margin-bottom:16px;font-family:'Inter',sans-serif}
.back-btn:hover{background:var(--surface3);color:var(--text);border-color:var(--violet)}
.back-btn .arrow{font-size:18px;transition:transform 0.2s}
.back-btn:hover .arrow{transform:translateX(-3px)}
.close-sidebar-btn{position:absolute;top:16px;right:16px;background:transparent;border:1px solid var(--surface3);color:var(--text2);width:36px;height:36px;border-radius:50%;cursor:pointer;font-size:20px;display:flex;align-items:center;justify-content:center;transition:var(--transition);font-family:'Inter',sans-serif}
.close-sidebar-btn:hover{background:var(--surface2);color:var(--text);border-color:var(--violet)}
.sidebar-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:99;backdrop-filter:blur(4px);animation:fadeIn 0.2s ease-out}
.lang-btn{width:100%;padding:12px 16px;margin:4px 0;background:var(--surface2);border:1px solid var(--surface3);border-radius:var(--radius-sm);color:var(--text);cursor:pointer;font-size:13px;text-align:left;transition:var(--transition);display:flex;align-items:center;gap:10px}
.lang-btn:hover{background:var(--surface3);border-color:var(--violet)}
.lang-btn.active{background:var(--violet);border-color:var(--orange);color:white}
.lang-btn .flag{font-size:18px}
.lang-btn .code{font-weight:700;min-width:40px}
.lang-btn .name{flex:1;font-size:12px;opacity:0.8}

/* Splash Screen */
.splash-screen{position:fixed;inset:0;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:10000}
.splash-logo{width:200px;height:200px;animation:spinIn 1.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards}
.splash-logo.spinning{animation:spin 2s linear infinite}
.splash-text{margin-top:32px;font-size:32px;font-weight:800;color:#a78bfa;letter-spacing:4px;animation:fadeIn 1s ease-out 0.5s both}
.splash-subtitle{margin-top:12px;font-size:14px;color:var(--text3);animation:fadeIn 1s ease-out 1s both}
.splash-exit{animation:fadeOut 0.5s ease-out forwards}

/* Layout responsive */
.app-container{display:flex;min-height:100vh}
.sidebar{width:280px;height:100vh;background:var(--surface);border-right:1px solid var(--surface3);position:fixed;left:0;top:0;z-index:100;display:flex;flex-direction:column;transition:transform 0.3s cubic-bezier(0.4,0,0.2,1);overflow-y:auto}
.main-content{flex:1;min-height:100vh;transition:margin-left 0.3s cubic-bezier(0.4,0,0.2,1)}

/* Desktop: sidebar visible by default */
@media(min-width:1024px){
.sidebar{transform:translateX(0)}
.sidebar.hidden{transform:translateX(-100%)}
.main-content{margin-left:280px}
.main-content.expanded{margin-left:0}
.desktop-only{display:flex!important}
.mobile-only{display:none!important}
}

/* Mobile: sidebar hidden by default */
@media(max-width:1023px){
.sidebar{transform:translateX(-100%)}
.sidebar.visible{transform:translateX(0);box-shadow:var(--shadow)}
.main-content{margin-left:0!important}
.desktop-only{display:none!important}
.mobile-only{display:flex!important}
}

@media(max-width:600px){
.main-content{padding:16px!important}
.main-header{padding:10px 16px!important}
.splash-logo{width:150px;height:150px}
.splash-text{font-size:24px}
}
</style>
</head>
