function HelpPage({onBack}) {
return (<GenericPage title="Ayuda" onBack={onBack}>
<div style={{display:'flex',flexDirection:'column',gap:16}}>
{[{q:'Cuantas lenguas hay?',a:'4 lenguas independientes: LSM (Mexico), LSF (Francia), ASL (EE.UU.), LSC (Colombia). Cada una con su propia gramatica.'},{q:'Como cambio de lengua?',a:'Usa los botones en el panel lateral izquierdo. Cada lengua tiene su propio progreso.'},{q:'Las gramaticas son iguales?',a:'NO. Cada lengua tiene gramatica propia. LSM usa OSV, LSF usa topico-comentario, ASL usa topic-comment, LSC usa SOV.'},{q:'Que pasa si repruebo?',a:'Vuelves a la clase completa. Debes releer antes de reintentar.'},{q:'Como se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9) y aprueba el examen (80%).'}].map((item,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{item.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{item.a}</p></div>))}
