function AuthPage({onAuth}) {
const [mode,setMode] = useState('register');
const [name,setName] = useState('');
const [email,setEmail] = useState('');
const [password,setPassword] = useState('');
const [showPass,setShowPass] = useState(false);
const [errors,setErrors] = useState({});
const [success,setSuccess] = useState('');
const [loading,setLoading] = useState(false);

const validate = () => {
const e = {};
if(!name.trim()) e.name = 'El nombre es requerido';
if(!email.trim()) e.email = 'El correo es requerido';
else if(!validateEmail(email)) e.email = 'Formato inválido';
if(!password) e.password = 'La contraseña es requerida';
else if(password.length < 8) e.password = 'Mínimo 8 caracteres';
else if(!/[A-Z]/.test(password)) e.password = 'Debe incluir mayúscula';
else if(!/[0-9]/.test(password)) e.password = 'Debe incluir número';
setErrors(e);
return Object.keys(e).length === 0;
};

const handleRegister = () => {
if(!validate()) return;
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
if(users[email]) {setErrors({email:'Correo ya registrado'});setLoading(false);return}
users[email] = {name,email,passwordHash:hashPassword(password),createdAt:new Date().toISOString()};
setStorage('users',users);
setSuccess('¡Cuenta creada!');
setTimeout(()=>onAuth({name,email}),500);
setLoading(false);
},500);
};

const handleLogin = () => {
if(!email.trim()||!validateEmail(email)){setErrors({email:'Correo inválido'});return}
if(!password){setErrors({password:'Contraseña requerida'});return}
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
