return {stages: stages.map((stage, si) => ({id: si + 1,name: stage.name,blocks: (stage.blocks || []).map((block, bi) => ({id: lang+'-s'+(si+1)+'-b'+(bi+1),name: block.name,lessons: (block.lessons || []).map((lessonName, li) => {const lessonData = getLessonData(lessonName, lang);return {id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),title: lessonName,handSign: handSignMap[lessonName] || null,content: {teaching: lessonData,questions: getHardQuestions(lessonName, lessonData, lang)}};})}))}))};
};

