{id:'first_block',name:'Primer Bloque',desc:'Aprueba tu primer examen',icon:'🏆',condition:(p)=>Object.values(p.blockProgress||{}).some(v=>v.passed)},
{id:'streak_3',name:'Racha de 3',desc:'Practica 3 días seguidos',icon:'🔥',condition:(p)=>(p.streak||0)>=3},
{id:'perfect_lesson',name:'Lección Perfecta',desc:'Obtén 9/9',icon:'💯',condition:(p)=>Object.values(p.lessonProgress||{}).some(v=>v.completed && v.correct===9)},
{id:'polyglot',name:'Políglota',desc:'Estudia 2 lenguas',icon:'🌍',condition:(p)=>Object.keys(p.courseProgress||{}).filter(k=>(p.courseProgress[k]||0)>0).length>=2}
];

const getStorage = (key, def) => {try{return JSON.parse(localStorage.getItem('lsmexa_'+key))||def}catch(e){return def}};
const setStorage = (key, val) => {try{localStorage.setItem('lsmexa_'+key,JSON.stringify(val))}catch(e){}};
const hashPassword = (p) => {let h=0;for(let i=0;i<p.length;i++){h=((h<<5)-h)+p.charCodeAt(i);h|=0}return'h_'+Math.abs(h).toString(36)+'_'+p.length};
const validateEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

