<DigiMascot expression="welcoming" size={600} animated={true} waving={true}/>
</div>
<div className="auth-welcome-text">
<h2>¡Bienvenido a LSMexa!</h2>
<p>Tu aventura en lenguas de señas<br/>comienza aquí</p>
</div>
</div>
</div>
);
}

