const getStorage = (key, def) => {try{return JSON.parse(localStorage.getItem('lsmexa_'+key))||def}catch(e){return def}};
const setStorage = (key, val) => {try{localStorage.setItem('lsmexa_'+key,JSON.stringify(val))}catch(e){}};
const hashPassword = (p) => {let h=0;for(let i=0;i<p.length;i++){h=((h<<5)-h)+p.charCodeAt(i);h|=0}return'h_'+Math.abs(h).toString(36)+'_'+p.length};
const validateEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

