function GenericPage({title, subtitle, children, onBack}) {
return (<div className="animate-in"><BackButton onClick={onBack} label="Inicio"/><h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>{title}</h1>{subtitle && <p style={{color:'var(--text2)',marginBottom:24}}>{subtitle}</p>}{children}</div>);
}

function AchievementsPage({progress, onBack}) {
const unlocked = progress.achievements || [];
const unlockedCount = unlocked.length;
const totalCount = ACHIEVEMENT_DEFS.length;
const progressPct = Math.round((unlockedCount/totalCount)*100);

return (
<GenericPage title="Logros" subtitle={`${unlockedCount} de ${totalCount} desbloqueados (${progressPct}%)`} onBack={onBack}>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,marginBottom:24,border:'1px solid var(--violet)'}}>
<div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}>
<span style={{fontSize:13,color:'var(--text2)',fontWeight:600}}>Progreso de logros</span>
<span style={{fontSize:13,color:'var(--yellow)',fontWeight:700}}>{progressPct}%</span>
</div>
<div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}>
<div style={{height:'100%',background:'linear-gradient(90deg,var(--violet),var(--yellow))',borderRadius:5,width:progressPct+'%',transition:'width 0.5s'}}/>
</div>
</div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))',gap:16}}>
{ACHIEVEMENT_DEFS.map(a=>{
const isUnlocked = unlocked.includes(a.id);
return (
<div key={a.id} className={'achievement-card ' + (isUnlocked ? 'unlocked' : 'locked')}>
<div style={{display:'flex',alignItems:'flex-start',justifyContent:'space-between',marginBottom:8}}>
