// Mapeo de tipos a configs
const configMap = {
'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D', 'E': 'E', 'F': 'F',
'HELLO': 'HELLO', 'THANKS': 'THANKS', 'MOM': 'MOM', 'DAD': 'DAD',
'YES': 'YES', 'NO': 'NO', 'NUM1': 'NUM1', 'NUM2': 'NUM2', 'NUM3': 'NUM3', 'NUM5': 'NUM5'
};

const HandSVG = ({type, size=220}) => {
const configKey = configMap[type] || 'A';
const config = handConfigs[configKey];
if (!config) return null;

return (
<div className="hand-3d-display">
<svg width={size} height={size} viewBox="0 0 200 220" xmlns="http://www.w3.org/2000/svg">
<defs>
{/* Gradiente de piel 3D */}
<radialGradient id="skin3d" cx="40%" cy="30%" r="70%">
<stop offset="0%" stopColor="#fde4d0"/>
<stop offset="40%" stopColor="#f5c9a8"/>
<stop offset="80%" stopColor="#e8a878"/>
<stop offset="100%" stopColor="#c4855a"/>
</radialGradient>
<radialGradient id="skinShadow" cx="70%" cy="80%" r="60%">
<stop offset="0%" stopColor="#8b5a3a" stopOpacity="0"/>
<stop offset="100%" stopColor="#8b5a3a" stopOpacity="0.5"/>
</radialGradient>
<radialGradient id="skinHighlight" cx="30%" cy="20%" r="50%">
<stop offset="0%" stopColor="#fff5e8" stopOpacity="0.6"/>
<stop offset="100%" stopColor="#fff5e8" stopOpacity="0"/>
</radialGradient>
<radialGradient id="skinDark3d" cx="50%" cy="50%" r="60%">
<stop offset="0%" stopColor="#e8a878"/>
<stop offset="100%" stopColor="#a06840"/>
</radialGradient>
<filter id="handShadow" x="-20%" y="-20%" width="140%" height="140%">
<feDropShadow dx="0" dy="6" stdDeviation="5" floodColor="#000" floodOpacity="0.4"/>
</filter>
<filter id="handGlow" x="-10%" y="-10%" width="120%" height="120%">
<feGaussianBlur stdDeviation="1" result="blur"/>
<feComposite in="SourceGraphic" in2="blur" operator="over"/>
</filter>
</defs>

{/* Sombra proyectada */}
<ellipse cx="100" cy="200" rx="50" ry="8" fill="#000" opacity="0.2"/>

{/* Mano 3D */}
<g filter="url(#handShadow)">
{config.render()}
</g>

{/* Etiqueta */}
<text x="100" y="215" textAnchor="middle" fontSize="11" fontWeight="700" fill="#a78bfa">{config.title}</text>
</svg>
</div>
);
};

