// ============ DEMOSTRACIÓN REALISTA DE SEÑA ============
// Figura humana realista mostrando la seña con las manos
const SignDemonstration = ({type, title, description}) => {
// Colores de piel realistas
const skinBase = '#d4a574';
const skinShadow = '#a67c52';
const skinHighlight = '#e8b896';
const skinDark = '#8b6f47';
const nailColor = '#f5d5c0';
const nailShadow = '#d4a574';

// Función para dibujar una mano realista con dedos individuales
const drawHand = (x, y, rotation, config) => {
const {
fingersExtended = [true, true, true, true, true], // [pulgar, indice, medio, anular, menique]
fingerSpread = 0, // separación entre dedos
palmOpen = true,
thumbPosition = 'side', // 'side', 'crossed', 'extended'
movement = null // 'forward', 'lateral', 'up-down', 'circle'
} = config;

return (
<g transform={`translate(${x}, ${y}) rotate(${rotation})`}>
{/* Muñeca */}
<rect x="-12" y="20" width="24" height="30" rx="8" fill={skinBase}/>
<rect x="-12" y="20" width="24" height="30" rx="8" fill="url(#skinGradHand)" opacity="0.5"/>

{/* Palma */}
<ellipse cx="0" cy="10" rx="22" ry="18" fill={skinBase}/>
<ellipse cx="0" cy="10" rx="22" ry="18" fill="url(#skinGradHand)" opacity="0.4"/>
<ellipse cx="-5" cy="8" rx="18" ry="14" fill={skinHighlight} opacity="0.3"/>

{/* Pliegues de la palma */}
<path d="M -15 5 Q 0 8 15 5" stroke={skinDark} strokeWidth="0.8" fill="none" opacity="0.5"/>
<path d="M -12 12 Q 0 15 12 12" stroke={skinDark} strokeWidth="0.8" fill="none" opacity="0.4"/>

{/* Pulgar */}
{thumbPosition === 'crossed' ? (
<g>
<ellipse cx="-15" cy="5" rx="6" ry="12" fill={skinBase} transform="rotate(-40 -15 5)"/>
<ellipse cx="-15" cy="5" rx="6" ry="12" fill="url(#skinGradHand)" opacity="0.4" transform="rotate(-40 -15 5)"/>
<ellipse cx="-17" cy="-2" rx="3" ry="4" fill={nailColor} transform="rotate(-40 -17 -2)"/>
</g>
) : thumbPosition === 'extended' ? (
<g>
<ellipse cx="-22" cy="-5" rx="6" ry="15" fill={skinBase} transform="rotate(-60 -22 -5)"/>
<ellipse cx="-22" cy="-5" rx="6" ry="15" fill="url(#skinGradHand)" opacity="0.4" transform="rotate(-60 -22 -5)"/>
<ellipse cx="-25" cy="-15" rx="3" ry="4" fill={nailColor} transform="rotate(-60 -25 -15)"/>
</g>
) : (
<g>
<ellipse cx="-20" cy="0" rx="6" ry="14" fill={skinBase} transform="rotate(-30 -20 0)"/>
<ellipse cx="-20" cy="0" rx="6" ry="14" fill="url(#skinGradHand)" opacity="0.4" transform="rotate(-30 -20 0)"/>
<ellipse cx="-23" cy="-10" rx="3" ry="4" fill={nailColor} transform="rotate(-30 -23 -10)"/>
</g>
)}

{/* Dedos */}
{fingersExtended.map((extended, i) => {
const fingerX = -10 + i * 6;
const fingerLength = extended ? 35 : 8;
const fingerWidth = 5;
const angles = [-15, -5, 0, 5, 15];
const angle = angles[i] + (fingerSpread * (i - 2));

return extended ? (
<g key={i}>
<rect 
x={fingerX - fingerWidth/2} 
y={-fingerLength} 
width={fingerWidth} 
height={fingerLength} 
rx={fingerWidth/2} 
fill={skinBase}
transform={`rotate(${angle} ${fingerX} 0)`}
/>
<rect 
x={fingerX - fingerWidth/2} 
y={-fingerLength} 
