"¡La práctica hace al maestro!",
"¡Estás haciendo un gran trabajo!",
"¡Recuerda: la constancia es clave!",
"¡Cada lección te acerca más a tu meta!",
"¡No olvides tomar descansos! Tu cerebro lo necesita",
"¡Estoy aquí para acompañarte en este viaje!",
"¡La comunidad sorda te espera con los brazos abiertos!",
"¡Cada seña que aprendes es un puente hacia la comunicación!",
"¡Recuerda practicar frente al espejo!"
];

function DigiAssistant() {
const [showComment, setShowComment] = useState(false);
const [currentComment, setCurrentComment] = useState('');
const [digiExpression, setDigiExpression] = useState('happy');

useEffect(() => {
const showRandomComment = () => {
const randomComment = DIGI_COMMENTS[Math.floor(Math.random() * DIGI_COMMENTS.length)];
const expressions = ['happy', 'excited', 'encouraging', 'teaching'];
const randomExpression = expressions[Math.floor(Math.random() * expressions.length)];
setCurrentComment(randomComment);
setDigiExpression(randomExpression);
setShowComment(true);
setTimeout(() => setShowComment(false), 5000);
};

const initialTimer = setTimeout(showRandomComment, 10000);
const interval = setInterval(() => {
const delay = Math.random() * 30000 + 30000;
setTimeout(showRandomComment, delay);
}, 60000);

return () => {
clearTimeout(initialTimer);
clearInterval(interval);
};
}, []);

return (
<div className="digi-assistant">
{showComment && (
<div className="digi-speech-bubble">
<p>{currentComment}</p>
</div>
)}
<div className="digi-character" onClick={() => setShowComment(!showComment)}>
<DigiMascot expression={digiExpression} size={140} animated={true}/>
</div>
</div>
);
}

// ============ SPLASH SCREEN ============
function SplashScreen({onComplete}) {
const [phase, setPhase] = useState('enter');
useEffect(() => {
const timer1 = setTimeout(() => setPhase('spinning'), 1800);
const timer2 = setTimeout(() => setPhase('exit'), 4000);
const timer3 = setTimeout(() => onComplete(), 4600);
return () => { clearTimeout(timer1); clearTimeout(timer2); clearTimeout(timer3); };
}, [onComplete]);
return (
<div className={`splash-screen ${phase === 'exit' ? 'splash-exit' : ''}`}>
<div className={`splash-logo ${phase === 'spinning' ? 'spinning' : ''}`}>
<LSMexaLogoSVG size={280}/>
</div>
<div className="splash-text">LSMEXA</div>
</div>
);
}

