setSidebarOpen(false);
}
};
window.addEventListener('resize', handleResize);
handleResize();
return () => window.removeEventListener('resize', handleResize);
}, []);

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

useEffect(() => {
if (currentScreen && currentScreen !== 'home' && currentScreen !== 'lesson' && currentScreen !== 'exam') {
const newProgress = {...progress};
const visited = newProgress.visitedSections || [];
if (!visited.includes(currentScreen)) {
visited.push(currentScreen);
newProgress.visitedSections = visited;
setProgress(newProgress);
}
}
}, [currentScreen]);

useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
let changed = false;
ACHIEVEMENT_DEFS.forEach(a=>{
if(!newAchievements.includes(a.id) && a.condition(progress)){
newAchievements.push(a.id);
changed = true;
setNewAchievement(a);
setTimeout(()=>setNewAchievement(null),4000);
}
});
if(changed) setProgress(p=>({...p,achievements:newAchievements}));
},[progress]);

const handleAuth = (userData) => {setUser(userData);setStorage('currentUser',userData);setCurrentScreen('home');};
const handleLogout = () => {setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};
const handleLangChange = (lang) => {setCurrentLang(lang);setActiveLesson(null);setActiveExam(null);setCurrentScreen('home');if(window.innerWidth < 1024) {setSidebarOpen(false);}setRenderError(null);};
const handleNavigate = (screen, params) => {setRenderError(null);if(screen==='lesson' && params){setPreviousScreen(currentScreen);setActiveLesson(params);setCurrentScreen('lesson');window.scrollTo(0,0);} else if(screen==='exam' && params){setPreviousScreen(currentScreen);setActiveExam(params);setCurrentScreen('exam');window.scrollTo(0,0);} else {setPreviousScreen(currentScreen);setActiveLesson(null);setActiveExam(null);setCurrentScreen(screen);window.scrollTo(0,0);}if(window.innerWidth < 1024) {setSidebarOpen(false);}};
const handleGoBack = () => {setRenderError(null);if(currentScreen === 'lesson' || currentScreen === 'exam'){handleNavigate(previousScreen || 'home');} else if(currentScreen !== 'home'){handleNavigate('home');}};
const handleProgressUpdate = (newProgress) => {setProgress(newProgress);};
const handleCuriousOpen = () => {
const newProgress = {...progress};
newProgress.curiousOpened = (progress.curiousOpened||0) + 1;
setProgress(newProgress);
};

