if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
try {
if(currentScreen==='lesson' && activeLesson) return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack} onCuriousOpen={handleCuriousOpen}/>;
if(currentScreen==='exam' && activeExam) return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate} onBack={handleGoBack}/>;
case 'review': return <GenericPage title="Repaso" subtitle={'Centro de repaso - ' + (LANGS[currentLang]?.code || 'LSM')} onBack={handleGoBack}><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></GenericPage>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'achievements': return <AchievementsPage progress={progress} onBack={handleGoBack}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser} onBack={handleGoBack}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings} onBack={handleGoBack}/>;
case 'help': return <HelpPage onBack={handleGoBack}/>;
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
}
} catch(e) {console.error('Error:', e);setRenderError(e.message);return (<div style={{padding:40,textAlign:'center',maxWidth:600,margin:'0 auto'}}><h2 style={{color:'var(--error)',marginBottom:16}}>Error al cargar</h2><p style={{color:'var(--text2)',marginBottom:20}}>{e.message}</p><button onClick={()=>{setRenderError(null);setCurrentScreen('home');setActiveLesson(null);setActiveExam(null);}} style={{padding:'12px 24px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Ir al inicio</button></div>);}
};

return (
<div className="app-container">
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)} currentLang={currentLang} onLangChange={handleLangChange}/>
<div className={'main-content' + (sidebarOpen ? '' : ' expanded')} style={{flex:1,minHeight:'100vh',transition:'margin-left 0.3s cubic-bezier(0.4,0,0.2,1)'}}>
<header className="main-header" style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<button className="toggle-sidebar-btn" onClick={()=>setSidebarOpen(!sidebarOpen)} aria-label={sidebarOpen ? 'Ocultar menú' : 'Mostrar menú'}>
{sidebarOpen ? '✕' : '☰'}
</button>
<div className="desktop-only" style={{display:'flex',alignItems:'center',gap:8,marginLeft:8}}><LSMexaLogo size={28}/><span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span><span style={{fontSize:11,color:'var(--text3)',marginLeft:8}}>{LANGS[currentLang]?.code}</span></div>
</div>
</header>
<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>{renderScreen()}</main>
<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}><p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v24.0 - Manos basadas en imagen real de LSM</p></footer>
</div>
<DigiAssistant/>
{newAchievement && (<div style={{position:'fixed',bottom:20,right:180,zIndex:1000,background:'linear-gradient(135deg,var(--yellow),var(--orange))',borderRadius:'var(--radius)',padding:20,boxShadow:'0 10px 40px rgba(0,0,0,0.5)',animation:'unlock 0.5s ease-out',maxWidth:320,color:'var(--black)'}}><div style={{display:'flex',alignItems:'center',gap:12}}><div style={{fontSize:40}}>{newAchievement.icon}</div><div><div style={{fontSize:12,fontWeight:700,opacity:0.8}}>¡LOGRO!</div><div style={{fontSize:16,fontWeight:800}}>{newAchievement.name}</div><div style={{fontSize:12,marginTop:4}}>{newAchievement.desc}</div></div></div></div>)}
{renderError && (<div style={{position:'fixed',bottom:20,left:20,zIndex:1000,background:'var(--error)',borderRadius:'var(--radius)',padding:16,maxWidth:400,color:'white',boxShadow:'0 10px 40px rgba(0,0,0,0.5)'}}><div style={{fontWeight:700,marginBottom:8}}>Error</div><div style={{fontSize:13,opacity:0.9}}>{renderError}</div><button onClick={()=>setRenderError(null)} style={{marginTop:12,padding:'6px 12px',background:'white',color:'var(--error)',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:12,fontWeight:600}}>Cerrar</button></div>)}
</div>
);
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>
</body>
</html>
