// ============ DIGI ASSISTANT ============
const DIGI_COMMENTS = ["¡Tú puedes! Cada paso cuenta","¡Excelente progreso! Sigue así","¡No te rindas! El aprendizaje es un viaje","¡Increíble dedicación! Estoy orgulloso de ti","¡Cada error es una oportunidad de aprender!","¡Vas muy bien! Continúa con esa energía","¡La práctica hace al maestro!","¡Estás haciendo un gran trabajo!","¡Recuerda: la constancia es clave!","¡Cada lección te acerca más a tu meta!","¡No olvides tomar descansos!","¡Estoy aquí para acompañarte!","¡La comunidad sorda te espera!","¡Cada seña es un puente de comunicación!","¡Practica frente al espejo!"];
function DigiAssistant() {
const [showComment, setShowComment] = useState(false);
const [currentComment, setCurrentComment] = useState('');
const [digiExpression, setDigiExpression] = useState('happy');
useEffect(() => {
const showRandomComment = () => {
setCurrentComment(DIGI_COMMENTS[Math.floor(Math.random() * DIGI_COMMENTS.length)]);
setDigiExpression(['happy','excited','encouraging','teaching'][Math.floor(Math.random()*4)]);
setShowComment(true);
setTimeout(() => setShowComment(false), 5000);
};
const t1 = setTimeout(showRandomComment, 10000);
const iv = setInterval(() => setTimeout(showRandomComment, Math.random()*30000+30000), 60000);
return () => { clearTimeout(t1); clearInterval(iv); };
}, []);
return (
<div className="digi-assistant">
{showComment && (<div className="digi-speech-bubble"><p>{currentComment}</p></div>)}
<div className="digi-character" onClick={() => setShowComment(!showComment)}><DigiMascot expression={digiExpression} size={140} animated={true}/></div>
</div>
);
}

// ============ SPLASH ============
function SplashScreen({onComplete}) {
const [phase, setPhase] = useState('enter');
useEffect(() => {
const t1 = setTimeout(() => setPhase('spinning'), 1800);
const t2 = setTimeout(() => setPhase('exit'), 4000);
const t3 = setTimeout(() => onComplete(), 4600);
return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
}, [onComplete]);
return (<div className={`splash-screen ${phase==='exit'?'splash-exit':''}`}><div className={`splash-logo ${phase==='spinning'?'spinning':''}`}><LSMexaLogoSVG size={280}/></div><div className="splash-text">LSMEXA</div></div>);
}

