function AuthPage({onAuth}) {
const [mode,setMode]=useState('register');const [name,setName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [showPass,setShowPass]=useState(false);const [errors,setErrors]=useState({});const [success,setSuccess]=useState('');const [loading,setLoading]=useState(false);
const validate=()=>{const e={};if(!name.trim())e.name='El nombre es requerido';if(!email.trim())e.email='El correo es requerido';else if(!validateEmail(email))e.email='Formato inválido';if(!password)e.password='La contraseña es requerida';else if(password.length<8)e.password='Mínimo 8 caracteres';else if(!/[A-Z]/.test(password))e.password='Debe incluir mayúscula';else if(!/[0-9]/.test(password))e.password='Debe incluir número';setErrors(e);return Object.keys(e).length===0;};
const handleRegister=()=>{if(!validate())return;setLoading(true);setTimeout(()=>{const u=getStorage('users',{});if(u[email]){setErrors({email:'Correo ya registrado'});setLoading(false);return}u[email]={name,email,passwordHash:hashPassword(password),createdAt:new Date().toISOString()};setStorage('users',u);setSuccess('¡Cuenta creada!');setTimeout(()=>onAuth({name,email}),500);setLoading(false);},500);};
const handleLogin=()=>{if(!email.trim()||!validateEmail(email)){setErrors({email:'Correo inválido'});return}if(!password){setErrors({password:'Contraseña requerida'});return}setLoading(true);setTimeout(()=>{const u=getStorage('users',{});const us=u[email];if(!us||us.passwordHash!==hashPassword(password)){setErrors({password:'Credenciales incorrectas'});setLoading(false);return}setStorage('currentUser',{name:us.name,email:us.email});onAuth({name:us.name,email:us.email});setLoading(false);},500);};
return (<div className="auth-container">
<div className="auth-form-section"><div style={{width:'100%',maxWidth:440,animation:'fadeIn 0.5s ease-out'}}>
<div style={{textAlign:'center',marginBottom:32}}><LSMexaLogoFull/></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius-lg)',padding:32,boxShadow:'var(--shadow)',border:'1px solid var(--surface3)'}}>
