{success&&<div style={{background:'#064e3b',color:'#4ade80',padding:12,borderRadius:'var(--radius-sm)',marginBottom:16,fontSize:14,textAlign:'center'}}>{success}</div>}
<div style={{display:'flex',gap:8,marginBottom:24}}><button onClick={()=>{setMode('register');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='register'?'var(--violet)':'var(--surface2)',color:mode==='register'?'white':'var(--text2)'}}>Registro</button><button onClick={()=>{setMode('login');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='login'?'var(--violet)':'var(--surface2)',color:mode==='login'?'white':'var(--text2)'}}>Iniciar Sesión</button></div>
{mode==='register'&&(<div style={{marginBottom:16}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.name?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.name&&<p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.name}</p>}</div>)}
<div style={{marginBottom:16}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="tu@correo.com" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.email?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.email&&<p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.email}</p>}</div>
<div style={{marginBottom:24}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Contraseña</label><input value={password} onChange={e=>setPassword(e.target.value)} type={showPass?'text':'password'} placeholder="Mínimo 8 caracteres" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.password?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.password&&<p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.password}</p>}</div>
<button onClick={mode==='register'?handleRegister:handleLogin} disabled={loading} style={{width:'100%',padding:'14px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',fontSize:16,fontWeight:700,cursor:'pointer',opacity:loading?0.7:1}}>{loading?'Procesando...':mode==='register'?'Crear Cuenta':'Iniciar Sesión'}</button>
</div></div></div>
<div className="auth-digi-section">
<div className="auth-greeting-bubble"><p>¡Hola! 👋<br/>¡Qué gusto verte!<br/>Soy Digi, tu guía</p></div>
<div className="auth-digi-character"><DigiMascot expression="welcoming" size={600} animated={true} waving={true}/></div>
</div></div>);
}

