function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content=CONTENT_DATA[currentLang];if(!content||!content.stages)return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;
const [currentQ,setCurrentQ]=useState(0);const [answers,setAnswers]=useState([]);const [selected,setSelected]=useState(null);const [showResult,setShowResult]=useState(false);const [examComplete,setExamComplete]=useState(false);
let block=null,stageIdx=-1;for(let si=0;si<content.stages.length;si++){const bks=content.stages[si].blocks||[];for(let bi=0;bi<bks.length;bi++){if(bks[bi].id===blockId){block=bks[bi];stageIdx=si;break;}}if(block)break;}
if(!block)return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;
const questions=[];(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>questions.push(q));});
const eq=questions.slice(0,10);const q=eq[currentQ];const passThreshold=80;
const score=answers.filter((a,i)=>a===eq[i]?.correct).length;const scorePct=eq.length>0?Math.round((score/eq.length)*100):0;const passed=scorePct>=passThreshold;
const handleAnswer=(idx)=>{if(showResult)return;setSelected(idx);setShowResult(true);};
const nextQuestion=()=>{const na=[...answers,selected];setAnswers(na);if(currentQ<eq.length-1){setCurrentQ(currentQ+1);setSelected(null);setShowResult(false);}else{setExamComplete(true);const np={...progress};const bp={...(np.blockProgress||{})};bp[blockId]={passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};np.blockProgress=bp;if(scorePct>=passThreshold){const sp={...(np.stageProgress||{})};sp[currentLang]={...(sp[currentLang]||{})};sp[currentLang][stageIdx+1]=100;np.stageProgress=sp;}onComplete(np);}};
if(examComplete){return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div><h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2><p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'¡APROBADO!':'Necesitas repasar'}</p></div><button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button></div>);}
return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Salir"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:13,color:'var(--text2)'}}>Examen</div><div style={{fontSize:18,fontWeight:700}}>{block.name}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div><div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{eq.length}</div></div></div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}><div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/eq.length)*100+'%'}}/></div>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-lg)',padding:16,marginBottom:16,border:'2px solid var(--violet)',display:'flex',alignItems:'center',gap:16}}><DigiMascot expression="thinking" size={80} animated={true}/><div style={{flex:1}}><p style={{fontSize:15,lineHeight:1.6,color:'var(--text)'}}>Examen difícil. Lee con atención, ¡Digi te acompaña!</p></div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginBottom:16,border:'1px solid var(--surface3)'}}><h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>{q.options.map((opt,i)=>{let bg='var(--surface2)',bc='var(--surface3)',cl='var(--text)';if(showResult){if(i===q.correct){bg='#064e3b';bc='var(--success)';cl='var(--success)';}else if(i===selected&&i!==q.correct){bg='#7f1d1d';bc='var(--error)';cl='var(--error)';}}else if(selected===i){bg='var(--violet)';bc='var(--violet)';cl='white';}return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{padding:'14px 18px',background:bg,border:'2px solid '+bc,borderRadius:'var(--radius-sm)',color:cl,cursor:showResult?'default':'pointer',fontSize:14,textAlign:'left',lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);})}</div>
{showResult&&<div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p></div>}</div>
{showResult&&<div style={{display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQ<eq.length-1?'Siguiente →':'Ver resultados'}</button></div>}</div>);
}

function GenericPage({title,subtitle,children,onBack}){return (<div className="animate-in"><BackButton onClick={onBack} label="Inicio"/><h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>{title}</h1>{subtitle&&<p style={{color:'var(--text2)',marginBottom:24}}>{subtitle}</p>}{children}</div>);}
function AchievementsPage({progress,onBack}){const un=progress.achievements||[];const pct=Math.round((un.length/ACHIEVEMENT_DEFS.length)*100);
return (<GenericPage title="Logros" subtitle={un.length+' de '+ACHIEVEMENT_DEFS.length+' desbloqueados ('+pct+'%)'} onBack={onBack}>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,marginBottom:24,border:'1px solid var(--violet)'}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{fontSize:13,color:'var(--text2)',fontWeight:600}}>Progreso de logros</span><span style={{fontSize:13,color:'var(--yellow)',fontWeight:700}}>{pct}%</span></div><div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}><div style={{height:'100%',background:'linear-gradient(90deg,var(--violet),var(--yellow))',borderRadius:5,width:pct+'%',transition:'width 0.5s'}}/></div></div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))',gap:16}}>{ACHIEVEMENT_DEFS.map(a=>{const u=un.includes(a.id);return (<div key={a.id} className={'achievement-card '+(u?'unlocked':'locked')}><div style={{display:'flex',alignItems:'flex-start',justifyContent:'space-between',marginBottom:8}}><span className="achievement-icon">{a.icon}</span><span className={'achievement-status '+(u?'unlocked':'locked')}>{u?'✓ DESBLOQUEADO':'🔒 BLOQUEADO'}</span></div><div className="achievement-name">{a.name}</div><div className="achievement-desc">{a.desc}</div></div>);})}</div></GenericPage>);}
function ProgressDashboard({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const tl=stages.reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);const cl=Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;const cp=tl>0?Math.round((cl/tl)*100):0;
return (<GenericPage title="Progreso" subtitle={lang.flag+' '+lang.name+' - '+lang.supportLang} onBack={onBack}><div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:16,marginBottom:20,border:'1px solid var(--violet)'}}><div style={{fontSize:13,color:'var(--text2)'}}><strong>Gramática de {lang.code}:</strong> {lang.grammar}</div></div><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{cp}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{cl}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div></div></GenericPage>);}
function HistoryPage({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const er=Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));const lp2=Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));const glt=(id)=>{for(const st of stages){for(const b of (st.blocks||[])){const l=(b.lessons||[]).find(x=>x.id===id);if(l)return l.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag+' '+lang.code} onBack={onBack}><h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Exámenes ({er.length})</h2>{er.length===0?<p style={{color:'var(--text2)',marginBottom:24}}>Sin exámenes.</p>:(<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{er.map(([bid,r])=>(<div key={bid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{bid}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(r.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:r.passed?'var(--success)':'var(--error)'}}>{r.score}%</div><div style={{fontSize:12,color:r.passed?'var(--success)':'var(--error)'}}>{r.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lp2.filter(([_,v])=>v.completed).length})</h2>{lp2.length===0?<p style={{color:'var(--text2)'}}>Sin lecciones.</p>:(<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lp2.map(([lid,lp])=>(<div key={lid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{glt(lid)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}</GenericPage>);}
function ProfilePage({user,progress,onUpdate,onBack}){const [name,setName]=useState(user?.name||'');const [saved,setSaved]=useState(false);const hs=()=>{const u=getStorage('users',{});if(u[user.email]){u[user.email].name=name;setStorage('users',u);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}><div style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}><div style={{width:64,height:64,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:28,fontWeight:700,color:'white'}}>{(name||'U')[0].toUpperCase()}</div><div><div style={{fontSize:20,fontWeight:700}}>{name}</div><div style={{fontSize:14,color:'var(--text2)'}}>{user?.email}</div></div></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={user?.email||''} disabled style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text3)',fontSize:15}}/></div><button onClick={hs} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button></div></GenericPage>);}
function SettingsPage({settings,onUpdate,onBack}){const [dg,setDg]=useState(settings.dailyGoal||3);const [saved,setSaved]=useState(false);const hs=()=>{onUpdate({...settings,dailyGoal:dg});setSaved(true);setTimeout(()=>setSaved(false),2000);};
return (<GenericPage title="Configuración" onBack={onBack}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}><h3 style={{fontSize:18,fontWeight:700,marginBottom:16}}>Preferencias</h3><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Objetivo diario</label><input type="number" min="1" max="20" value={dg} onChange={e=>setDg(parseInt(e.target.value)||1)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div><button onClick={hs} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button></div></GenericPage>);}
function HelpPage({onBack}){return (<GenericPage title="Ayuda" onBack={onBack}><div style={{display:'flex',flexDirection:'column',gap:16}}>{[{q:'¿Cuántas lenguas hay?',a:'4 lenguas independientes: LSM, LSF, ASL, LSC. Cada una con su propia gramática.'},{q:'¿Cómo cambio de lengua?',a:'Usa los botones en el panel lateral izquierdo.'},{q:'¿Las gramáticas son iguales?',a:'NO. Cada lengua tiene gramática propia.'},{q:'¿Qué pasa si repruebo?',a:'Vuelves a la clase completa.'},{q:'¿Cómo se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9) y aprueba el examen (80%).'}].map((it,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{it.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{it.a}</p></div>))}</div></GenericPage>);}

function App() {
const [showSplash,setShowSplash]=useState(true);
const [user,setUser]=useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang]=useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen]=useState('home');
const [sidebarOpen,setSidebarOpen]=useState(window.innerWidth>=1024);
const [progress,setProgress]=useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0,visitedSections:[],curiousOpened:0}));
const [settings,setSettings]=useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson]=useState(null);
const [activeExam,setActiveExam]=useState(null);
const [newAchievement,setNewAchievement]=useState(null);
const [previousScreen,setPreviousScreen]=useState('home');
const [renderError,setRenderError]=useState(null);
useEffect(()=>{const hr=()=>{setSidebarOpen(window.innerWidth>=1024);};window.addEventListener('resize',hr);hr();return ()=>window.removeEventListener('resize',hr);},[]);
useEffect(()=>{setStorage('currentLang',currentLang);},[currentLang]);
useEffect(()=>{setStorage('progress',progress);},[progress]);
useEffect(()=>{setStorage('settings',settings);},[settings]);
useEffect(()=>{if(currentScreen&&currentScreen!=='home'&&currentScreen!=='lesson'&&currentScreen!=='exam'){const np={...progress};const v=np.visitedSections||[];if(!v.includes(currentScreen)){v.push(currentScreen);np.visitedSections=v;setProgress(np);}}},[currentScreen]);
useEffect(()=>{const na=[...(progress.achievements||[])];let ch=false;ACHIEVEMENT_DEFS.forEach(a=>{if(!na.includes(a.id)&&a.condition(progress)){na.push(a.id);ch=true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});if(ch)setProgress(p=>({...p,achievements:na}));},[progress]);
const handleAuth=(ud)=>{setUser(ud);setStorage('currentUser',ud);setCurrentScreen('home');};
const handleLogout=()=>{setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};
const handleLangChange=(l)=>{setCurrentLang(l);setActiveLesson(null);setActiveExam(null);setCurrentScreen('home');if(window.innerWidth<1024)setSidebarOpen(false);setRenderError(null);};
const handleNavigate=(s,p)=>{setRenderError(null);if(s==='lesson'&&p){setPreviousScreen(currentScreen);setActiveLesson(p);setCurrentScreen('lesson');window.scrollTo(0,0);}else if(s==='exam'&&p){setPreviousScreen(currentScreen);setActiveExam(p);setCurrentScreen('exam');window.scrollTo(0,0);}else{setPreviousScreen(currentScreen);setActiveLesson(null);setActiveExam(null);setCurrentScreen(s);window.scrollTo(0,0);}if(window.innerWidth<1024)setSidebarOpen(false);};
const handleGoBack=()=>{setRenderError(null);if(currentScreen==='lesson'||currentScreen==='exam'){handleNavigate(previousScreen||'home');}else if(currentScreen!=='home'){handleNavigate('home');}};
const handleProgressUpdate=(np)=>setProgress(np);
const handleCuriousOpen=()=>{const np={...progress};np.curiousOpened=(progress.curiousOpened||0)+1;setProgress(np);};
if(showSplash)return <SplashScreen onComplete={()=>setShowSplash(false)}/>;
if(!user)return <AuthPage onAuth={handleAuth}/>;
const renderScreen=()=>{try{
if(currentScreen==='lesson'&&activeLesson)return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack} onCuriousOpen={handleCuriousOpen}/>;
if(currentScreen==='exam'&&activeExam)return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
switch(currentScreen){
case 'home':return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
case 'path':return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate} onBack={handleGoBack}/>;
case 'review':return <GenericPage title="Repaso" subtitle={'Centro de repaso - '+(LANGS[currentLang]?.code||'LSM')} onBack={handleGoBack}><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></GenericPage>;
case 'progress':return <ProgressDashboard currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'achievements':return <AchievementsPage progress={progress} onBack={handleGoBack}/>;
case 'history':return <HistoryPage currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'profile':return <ProfilePage user={user} progress={progress} onUpdate={setUser} onBack={handleGoBack}/>;
case 'settings':return <SettingsPage settings={settings} onUpdate={setSettings} onBack={handleGoBack}/>;
case 'help':return <HelpPage onBack={handleGoBack}/>;
default:return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
}}catch(e){console.error('Error:',e);setRenderError(e.message);return (<div style={{padding:40,textAlign:'center',maxWidth:600,margin:'0 auto'}}><h2 style={{color:'var(--error)',marginBottom:16}}>Error al cargar</h2><p style={{color:'var(--text2)',marginBottom:20}}>{e.message}</p><button onClick={()=>{setRenderError(null);setCurrentScreen('home');setActiveLesson(null);setActiveExam(null);}} style={{padding:'12px 24px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Ir al inicio</button></div>);}};
return (<div className="app-container">
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)} currentLang={currentLang} onLangChange={handleLangChange}/>
<div className={'main-content'+(sidebarOpen?'':' expanded')} style={{flex:1,minHeight:'100vh',transition:'margin-left 0.3s cubic-bezier(0.4,0,0.2,1)'}}>
<header className="main-header" style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}><div style={{display:'flex',alignItems:'center',gap:12}}><button className="toggle-sidebar-btn" onClick={()=>setSidebarOpen(!sidebarOpen)} aria-label={sidebarOpen?'Ocultar menú':'Mostrar menú'}>{sidebarOpen?'✕':'☰'}</button><div className="desktop-only" style={{display:'flex',alignItems:'center',gap:8,marginLeft:8}}><LSMexaLogo size={28}/><span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span><span style={{fontSize:11,color:'var(--text3)',marginLeft:8}}>{LANGS[currentLang]?.code}</span></div></div></header>
<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>{renderScreen()}</main>
<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}><p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v25.0 - Alfabeto LSM estilo póster</p></footer>
</div>
<DigiAssistant/>
{newAchievement&&(<div style={{position:'fixed',bottom:20,right:180,zIndex:1000,background:'linear-gradient(135deg,var(--yellow),var(--orange))',borderRadius:'var(--radius)',padding:20,boxShadow:'0 10px 40px rgba(0,0,0,0.5)',animation:'unlock 0.5s ease-out',maxWidth:320,color:'var(--black)'}}><div style={{display:'flex',alignItems:'center',gap:12}}><div style={{fontSize:40}}>{newAchievement.icon}</div><div><div style={{fontSize:12,fontWeight:700,opacity:0.8}}>¡LOGRO!</div><div style={{fontSize:16,fontWeight:800}}>{newAchievement.name}</div><div style={{fontSize:12,marginTop:4}}>{newAchievement.desc}</div></div></div></div>)}
{renderError&&(<div style={{position:'fixed',bottom:20,left:20,zIndex:1000,background:'var(--error)',borderRadius:'var(--radius)',padding:16,maxWidth:400,color:'white',boxShadow:'0 10px 40px rgba(0,0,0,0.5)'}}><div style={{fontWeight:700,marginBottom:8}}>Error</div><div style={{fontSize:13,opacity:0.9}}>{renderError}</div><button onClick={()=>setRenderError(null)} style={{marginTop:12,padding:'6px 12px',background:'white',color:'var(--error)',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:12,fontWeight:600}}>Cerrar</button></div>)}
</div>);
}

