const isLessonUnlocked=(si,bi,li)=>{if(si===0&&bi===0&&li===0)return true;if(!stages[si])return false;const st=stages[si];if(!st.blocks||!st.blocks[bi])return false;const bl=st.blocks[bi];if(!bl.lessons||li<0||li>=bl.lessons.length)return false;let psi=si,pbi=bi,pli=li-1;if(pli<0){pbi=bi-1;if(pbi<0){psi=si-1;if(psi<0||!stages[psi])return false;pbi=stages[psi].blocks.length-1;}if(!stages[psi]||!stages[psi].blocks[pbi])return false;pli=stages[psi].blocks[pbi].lessons.length-1;}if(!stages[psi]||!stages[psi].blocks[pbi])return false;const pl=stages[psi].blocks[pbi].lessons[pli];if(!pl)return false;return progress.lessonProgress?.[pl.id]?.completed||false;};
