<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:8}}>{bls.map((lesson,li)=>{const lun=isLessonUnlocked(si,bi,li);const lcomp=progress.lessonProgress?.[lesson.id]?.completed||false;const lscore=progress.lessonProgress?.[lesson.id]?.correct||0;
