function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content=CONTENT_DATA[currentLang];if(!content||!content.stages)return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;
const [currentQ,setCurrentQ]=useState(0);const [answers,setAnswers]=useState([]);const [selected,setSelected]=useState(null);const [showResult,setShowResult]=useState(false);const [examComplete,setExamComplete]=useState(false);
let block=null,stageIdx=-1;for(let si=0;si<content.stages.length;si++){const bks=content.stages[si].blocks||[];for(let bi=0;bi<bks.length;bi++){if(bks[bi].id===blockId){block=bks[bi];stageIdx=si;break;}}if(block)break;}
if(!block)return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;
const questions=[];(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>questions.push(q));});
const eq=questions.slice(0,10);const q=eq[currentQ];const passThreshold=80;
const score=answers.filter((a,i)=>a===eq[i]?.correct).length;const scorePct=eq.length>0?Math.round((score/eq.length)*100):0;const passed=scorePct>=passThreshold;
const handleAnswer=(idx)=>{if(showResult)return;setSelected(idx);setShowResult(true);};
const nextQuestion=()=>{const na=[...answers,selected];setAnswers(na);if(currentQ<eq.length-1){setCurrentQ(currentQ+1);setSelected(null);setShowResult(false);}else{setExamComplete(true);const np={...progress};const bp={...(np.blockProgress||{})};bp[blockId]={passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};np.blockProgress=bp;if(scorePct>=passThreshold){const sp={...(np.stageProgress||{})};sp[currentLang]={...(sp[currentLang]||{})};sp[currentLang][stageIdx+1]=100;np.stageProgress=sp;}onComplete(np);}};
if(examComplete){return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div><h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2><p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'¡APROBADO!':'Necesitas repasar'}</p></div><button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button></div>);}
return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Salir"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:13,color:'var(--text2)'}}>Examen</div><div style={{fontSize:18,fontWeight:700}}>{block.name}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div><div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{eq.length}</div></div></div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}><div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/eq.length)*100+'%'}}/></div>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-lg)',padding:16,marginBottom:16,border:'2px solid var(--violet)',display:'flex',alignItems:'center',gap:16}}><DigiMascot expression="thinking" size={80} animated={true}/><div style={{flex:1}}><p style={{fontSize:15,lineHeight:1.6,color:'var(--text)'}}>Examen difícil. Lee con atención, ¡Digi te acompaña!</p></div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginBottom:16,border:'1px solid var(--surface3)'}}><h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>{q.options.map((opt,i)=>{let bg='var(--surface2)',bc='var(--surface3)',cl='var(--text)';if(showResult){if(i===q.correct){bg='#064e3b';bc='var(--success)';cl='var(--success)';}else if(i===selected&&i!==q.correct){bg='#7f1d1d';bc='var(--error)';cl='var(--error)';}}else if(selected===i){bg='var(--violet)';bc='var(--violet)';cl='white';}return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{padding:'14px 18px',background:bg,border:'2px solid '+bc,borderRadius:'var(--radius-sm)',color:cl,cursor:showResult?'default':'pointer',fontSize:14,textAlign:'left',lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);})}</div>
{showResult&&<div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p></div>}</div>
{showResult&&<div style={{display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQ<eq.length-1?'Siguiente →':'Ver resultados'}</button></div>}</div>);
}

