const SignDemonstration = ({type, title, description}) => {
const imgUrl = HAND_IMAGES[type];
const art = HAND_ART[type] || HAND_ART['A'];
const label = art.label || '';
const fontSize = label.length > 2 ? 28 : 44;
return (
<div className="sign-poster-card">
{imgUrl ? (<img src={imgUrl} alt={'Seña '+label} style={{width:'240px',height:'264px',objectFit:'contain',borderRadius:'12px',background:'#f8f9fa'}}/>) : (
<svg width="240" height="264" viewBox="0 0 200 220" xmlns="http://www.w3.org/2000/svg" style={{overflow:'visible'}}>
{art.draw()}
<text x="192" y="214" textAnchor="end" fontSize={fontSize} fontWeight="800" fill="#111" fontFamily="'Comic Sans MS','Segoe Print',cursive" transform="rotate(-4 192 214)">{label}</text>
</svg>)}
<div className="sign-poster-title">{title || label}</div>
<div className="sign-poster-sub">{description || art.desc}</div>
</div>);
};

const DigiMascot = ({expression='happy', size=140, animated=true, waving=false}) => {
const exps = {happy:{mouth:'M 45 72 Q 50 78 55 72',eyes:'open',eyebrows:'normal',cheeks:true},excited:{mouth:'M 42 70 Q 50 82 58 70',eyes:'sparkle',eyebrows:'raised',cheeks:true},thinking:{mouth:'M 46 73 Q 50 74 54 73',eyes:'side',eyebrows:'raised',cheeks:false},encouraging:{mouth:'M 44 71 Q 50 77 56 71',eyes:'open',eyebrows:'normal',cheeks:true},sad:{mouth:'M 44 75 Q 50 70 56 75',eyes:'open',eyebrows:'sad',cheeks:false},celebrating:{mouth:'M 40 68 Q 50 82 60 68',eyes:'sparkle',eyebrows:'raised',cheeks:true},teaching:{mouth:'M 44 71 Q 50 76 56 71',eyes:'open',eyebrows:'normal',cheeks:true},welcoming:{mouth:'M 42 70 Q 50 80 58 70',eyes:'sparkle',eyebrows:'raised',cheeks:true}};
