<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,border:'1px solid var(--surface3)'}}><div style={{fontSize:13,color:'var(--text2)'}}>Progreso</div><div style={{fontSize:32,fontWeight:800,color:'var(--orange)'}}>{langProgress}%</div><div style={{fontSize:11,color:'var(--text3)'}}>{completedLessons}/{totalLessons}</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,border:'1px solid var(--surface3)'}}><div style={{fontSize:13,color:'var(--text2)'}}>Bloques</div><div style={{fontSize:32,fontWeight:800,color:'var(--success)'}}>{Object.values(progress.blockProgress||{}).filter(v=>v.passed).length}</div></div>
