<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,border:'1px solid var(--surface3)'}}><div style={{fontSize:13,color:'var(--text2)'}}>Logros</div><div style={{fontSize:32,fontWeight:800,color:'var(--violet)'}}>{(progress.achievements||[]).length}</div></div>
</div></div>);
