function LearningPath({currentLang,progress,onNavigate,onBack}) {
const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];
const isLessonUnlocked=(si,bi,li)=>{if(si===0&&bi===0&&li===0)return true;if(!stages[si])return false;const st=stages[si];if(!st.blocks||!st.blocks[bi])return false;const bl=st.blocks[bi];if(!bl.lessons||li<0||li>=bl.lessons.length)return false;let psi=si,pbi=bi,pli=li-1;if(pli<0){pbi=bi-1;if(pbi<0){psi=si-1;if(psi<0||!stages[psi])return false;pbi=stages[psi].blocks.length-1;}if(!stages[psi]||!stages[psi].blocks[pbi])return false;pli=stages[psi].blocks[pbi].lessons.length-1;}if(!stages[psi]||!stages[psi].blocks[pbi])return false;const pl=stages[psi].blocks[pbi].lessons[pli];if(!pl)return false;return progress.lessonProgress?.[pl.id]?.completed||false;};
const isBlockUnlocked=(si,bi)=>{if(si===0&&bi===0)return true;if(!stages[si])return false;let psi=si,pbi=bi-1;if(pbi<0){psi=si-1;if(psi<0||!stages[psi])return false;pbi=stages[psi].blocks.length-1;}if(!stages[psi]||!stages[psi].blocks[pbi])return false;return progress.blockProgress?.[stages[psi].blocks[pbi].id]?.passed||false;};
return (<div className="animate-in"><BackButton onClick={onBack} label="Inicio"/><h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>Ruta de Aprendizaje</h1><p style={{color:'var(--text2)',marginBottom:8}}>{lang.flag} {lang.name}</p><p style={{color:'var(--text3)',fontSize:12,marginBottom:24}}>Idioma: {lang.supportLang} | Gramática: {lang.grammar} | Cada bloque cierra con examen de nivelación (80%)</p>
{stages.map((stage,si)=>{const sc=STAGE_COLORS[si]||'#666';const sb=stage.blocks||[];const sl=sb.reduce((s,b)=>s+(b.lessons||[]).length,0);const scomp=sb.reduce((s,b)=>s+(b.lessons||[]).filter(l=>progress.lessonProgress?.[l.id]?.completed).length,0);const sp=sl>0?Math.round((scomp/sl)*100):0;const sun=si===0||progress.stageProgress?.[currentLang]?.[si]>=100;
return (<div key={stage.id} style={{marginBottom:32,opacity:sun?1:0.5}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:16,flexWrap:'wrap'}}><div style={{width:44,height:44,borderRadius:'50%',background:sc,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,fontWeight:800,color:'white'}}>{si+1}</div><div style={{flex:1}}><div style={{fontSize:20,fontWeight:700}}>{stage.name}</div><div style={{fontSize:13,color:'var(--text2)'}}>{scomp}/{sl} ({sp}%)</div></div><div style={{width:200,height:10,background:'var(--surface3)',borderRadius:5}}><div style={{height:'100%',background:sc,borderRadius:5,width:sp+'%'}}/></div></div>
{sb.map((block,bi)=>{const bun=isBlockUnlocked(si,bi);const bpass=progress.blockProgress?.[block.id]?.passed||false;const bls=block.lessons||[];const bcomp=bls.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
return (<div key={block.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:16,border:'1px solid '+(bpass?'var(--success)':bun?'var(--violet)':'var(--surface3)'),opacity:bun?1:0.6}}>
<div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:12,flexWrap:'wrap',gap:8}}><div style={{display:'flex',alignItems:'center',gap:10}}><div style={{width:32,height:32,borderRadius:'50%',background:bpass?'var(--success)':bun?'var(--violet)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>{bpass?'✓':bi+1}</div><div><div style={{fontSize:16,fontWeight:700}}>{block.name}</div><div style={{fontSize:12,color:'var(--text2)'}}>{bcomp}/{bls.length} lecciones</div></div></div>{bpass&&<span style={{fontSize:12,color:'var(--success)',fontWeight:600}}>NIVELADO</span>}{!bun&&<span style={{fontSize:12,color:'var(--text3)'}}>BLOQUEADO</span>}</div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:8}}>{bls.map((lesson,li)=>{const lun=isLessonUnlocked(si,bi,li);const lcomp=progress.lessonProgress?.[lesson.id]?.completed||false;const lscore=progress.lessonProgress?.[lesson.id]?.correct||0;
return (<div key={lesson.id} onClick={()=>lun&&onNavigate('lesson',{blockId:block.id,lessonId:lesson.id})} style={{padding:'10px 12px',background:lcomp?'#064e3b':lun?'var(--violet)':'var(--surface2)',border:'1px solid '+(lcomp?'var(--success)':lun?'var(--orange)':'var(--surface3)'),borderRadius:'var(--radius-sm)',cursor:lun?'pointer':'default',opacity:lun?1:0.5,display:'flex',alignItems:'center',gap:8}}>
<div style={{width:24,height:24,borderRadius:'50%',background:lcomp?'var(--success)':lun?'var(--orange)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:'white'}}>{lcomp?'✓':li+1}</div>
<div style={{flex:1,minWidth:0}}><div style={{fontSize:12,fontWeight:600,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{lesson.title}</div><div style={{fontSize:10,color:'var(--text3)'}}>{lcomp?lscore+'/9':'Lección '+(li+1)}</div></div>{!lun&&<span style={{fontSize:10}}>🔒</span>}</div>);})}</div>
{bun&&bcomp===bls.length&&!bpass&&(<div style={{marginTop:12,padding:12,background:'var(--orange)',borderRadius:'var(--radius-sm)',textAlign:'center',cursor:'pointer',fontWeight:700,color:'white'}} onClick={()=>onNavigate('exam',{blockId:block.id})}>EXAMEN DE NIVELACIÓN →</div>)}
</div>);})}</div>);})}</div>);
}

function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack,onCuriousOpen,onNavigate}) {
const content=CONTENT_DATA[currentLang];
if(!content||!content.stages) return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;
const [phase,setPhase]=useState('teaching');const [teachingStep,setTeachingStep]=useState(0);const [currentQIdx,setCurrentQIdx]=useState(0);const [selectedAnswer,setSelectedAnswer]=useState(null);const [showFeedback,setShowFeedback]=useState(false);const [isCorrect,setIsCorrect]=useState(null);const [lessonComplete,setLessonComplete]=useState(false);const [lessonFailed,setLessonFailed]=useState(false);const [correctCount,setCorrectCount]=useState(0);const [answers,setAnswers]=useState([]);const [funFact,setFunFact]=useState(null);
