const keyPoints = useMemo(()=>{
if(!teaching) return [];
return [
'Configuración: '+(teaching.anatomy?.handshape||'—'),
'Ubicación: '+(teaching.anatomy?.location||'—')+' | Movimiento: '+(teaching.anatomy?.movement||'—'),
'Expresión facial: '+(teaching.anatomy?.facialExpression||'—'),
'Error a evitar: '+((teaching.mistakes&&teaching.mistakes[0])||'—'),
