const restartLesson=()=>{setPhase('teaching');setTeachingStep(0);setCurrentQIdx(0);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);setLessonFailed(false);setLessonComplete(false);setCorrectCount(0);setAnswers([]);};
const handleCuriousClick=()=>{setFunFact(getRealFunFact(currentLang));if(onCuriousOpen)onCuriousOpen();};
if(lessonFailed){return (<div className="animate-in shake-anim" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'2px solid var(--error)',textAlign:'center'}}><div style={{fontSize:64,marginBottom:12}}>😔</div><h2 style={{fontSize:28,fontWeight:800,color:'var(--error)'}}>No Aprobada</h2><p style={{color:'var(--text2)',fontSize:16}}>{lesson.title}</p><div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:20,marginTop:16}}><div style={{fontSize:48,fontWeight:800,color:'var(--error)'}}>{correctCount}/{totalQuestions}</div><div style={{fontSize:14,color:'var(--text2)',marginTop:8}}>Necesitas {MIN_CORRECT}/{totalQuestions}</div></div></div><div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}><button onClick={restartLesson} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}>Reiniciar lección</button><button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button></div></div>);}
