return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:48,marginBottom:12}}>🎉</div><h2 style={{fontSize:24,fontWeight:700,marginBottom:8}}>¡Aprobada!</h2><p style={{color:'var(--text2)'}}>{lesson.title}</p><div style={{background:'#064e3b',borderRadius:'var(--radius-sm)',padding:20,marginTop:16,border:'1px solid var(--success)'}}><div style={{fontSize:48,fontWeight:800,color:'var(--success)'}}>{correctCount}/{totalQuestions}</div><div style={{fontSize:14,color:'var(--text)',marginTop:8}}>Superaste el mínimo</div></div></div>

