};

const LSMexaLogoSVG = ({size=200}) => (
<svg width={size} height={size} viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg">
<defs>
<linearGradient id="greenTop" x1="180" y1="40" x2="280" y2="180" gradientUnits="userSpaceOnUse"><stop offset="0%" stopColor="#90EE90"/><stop offset="30%" stopColor="#2ECC40"/><stop offset="70%" stopColor="#1A8A2E"/><stop offset="100%" stopColor="#0D5C1A"/></linearGradient>
<linearGradient id="greenSide" x1="180" y1="40" x2="200" y2="100" gradientUnits="userSpaceOnUse"><stop offset="0%" stopColor="#B8F0B8"/><stop offset="100%" stopColor="#2ECC40"/></linearGradient>
<radialGradient id="greenGlow" cx="230" cy="100" r="80"><stop offset="0%" stopColor="#5AE87A" stopOpacity="0.6"/><stop offset="100%" stopColor="#1A8A2E" stopOpacity="0"/></radialGradient>
<linearGradient id="blueLeft" x1="100" y1="140" x2="200" y2="280" gradientUnits="userSpaceOnUse"><stop offset="0%" stopColor="#1A1A6E"/><stop offset="30%" stopColor="#3A3AA0"/><stop offset="60%" stopColor="#6A6AD0"/><stop offset="100%" stopColor="#A0A0E8"/></linearGradient>
<linearGradient id="blueSide" x1="100" y1="140" x2="130" y2="200" gradientUnits="userSpaceOnUse"><stop offset="0%" stopColor="#0A0A4E"/><stop offset="100%" stopColor="#3A3AA0"/></linearGradient>
<radialGradient id="blueGlow" cx="150" cy="220" r="80"><stop offset="0%" stopColor="#7A7AE8" stopOpacity="0.5"/><stop offset="100%" stopColor="#1A1A6E" stopOpacity="0"/></radialGradient>
