<circle cx="230" cy="100" r="90" fill="url(#greenGlow)"/><circle cx="150" cy="220" r="90" fill="url(#blueGlow)"/><circle cx="270" cy="240" r="90" fill="url(#orangeGlow)"/>
<g filter="url(#shadow3d)"><path d="M 200 60 C 230 55, 270 65, 290 90 C 295 100, 290 115, 275 125 C 250 140, 215 145, 190 140 C 175 137, 165 130, 160 120 C 170 90, 185 70, 200 60 Z" fill="url(#greenSide)" opacity="0.7"/><path d="M 195 55 C 225 50, 265 60, 285 85 C 290 95, 285 110, 270 120 C 245 135, 210 140, 185 135 C 170 132, 160 125, 155 115 C 165 85, 180 65, 195 55 Z" fill="url(#greenTop)"/><path d="M 200 58 C 220 55, 250 62, 270 80 C 260 70, 230 62, 205 62 C 200 62, 200 58, 200 58 Z" fill="#B8F0B8" opacity="0.6"/></g>
<g filter="url(#shadow3d)"><path d="M 170 150 C 155 160, 130 195, 120 230 C 115 250, 120 270, 135 285 C 155 300, 180 295, 195 280 C 200 270, 198 255, 190 245 C 175 220, 165 190, 170 150 Z" fill="url(#blueSide)" opacity="0.7"/><path d="M 165 145 C 150 155, 125 190, 115 225 C 110 245, 115 265, 130 280 C 150 295, 175 290, 190 275 C 195 265, 193 250, 185 240 C 170 215, 160 185, 165 145 Z" fill="url(#blueLeft)"/><path d="M 160 150 C 148 160, 130 185, 122 210 C 125 195, 140 170, 155 158 C 158 155, 160 150, 160 150 Z" fill="#8888E8" opacity="0.5"/></g>
