</svg>);
const LSMexaLogoFull = () => (<div style={{display:'flex',flexDirection:'column',alignItems:'center',gap:8}}><LSMexaLogoSVG size={100}/><span style={{fontSize:28,fontWeight:900,color:'#a8a8ff',letterSpacing:4}}>LSMEXA</span></div>);

const LS = {stroke:'#111', strokeWidth:6, fill:'none', strokeLinecap:'round', strokeLinejoin:'round'};
const Finger = ({x,y,w,h,rot=0}) => (<rect x={x} y={y} width={w} height={h} rx={Math.min(w,h)/2} {...LS} transform={rot?`rotate(${rot} ${x+w/2} ${y+h})`:undefined}/>);
