const HAND_ART = {
A:{label:'A',desc:'Puño cerrado, pulgar al lado',draw:()=>(<g><Palm y={95} h={65}/><Knuckles y={98}/><Finger x={130} y={68} w={20} h={54} rot={38}/><Wrist/></g>)},
