const SignDemonstration = ({type, title, description}) => {
const imgUrl = HAND_IMAGES[type];
const art = HAND_ART[type] || HAND_ART['A'];
const label = art.label || '';
const fontSize = label.length > 2 ? 28 : 44;
return (
<div className="sign-poster-card">
{imgUrl ? (<img src={imgUrl} alt={'Seña '+label} style={{width:'240px',height:'264px',objectFit:'contain',borderRadius:'12px',background:'#f8f9fa'}}/>) : (
<svg width="240" height="264" viewBox="0 0 200 220" xmlns="http://www.w3.org/2000/svg" style={{overflow:'visible'}}>
{art.draw()}
<text x="192" y="214" textAnchor="end" fontSize={fontSize} fontWeight="800" fill="#111" fontFamily="'Comic Sans MS','Segoe Print',cursive" transform="rotate(-4 192 214)">{label}</text>
</svg>)}
<div className="sign-poster-title">{title || label}</div>
<div className="sign-poster-sub">{description || art.desc}</div>
</div>);
};

