const norm = (e) => ({intro:e.in, anatomy:{handshape:e.hs,thumb:e.th,palm:e.pa,orientation:e.or,location:e.lo,movement:e.mv,facialExpression:e.fa,repetition:e.re}, steps:e.st, mistakes:e.mi, context:e.cx, cultural:e.cu, visual:e.vi});

const hashStr = (s) => {let h=0;for(let i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;}return Math.abs(h);};
const seededShuffle = (arr, seed) => {const a=[...arr];let s=(seed||1)+1;const rnd=()=>{s=(s*9301+49297)%233280;return s/233280;};for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));const t=a[i];a[i]=a[j];a[j]=t;}return a;};
const PADS = {
handshape:['Garra tensa con dedos separados','Mano en cuenco rígido','Dedos en abanico tembloroso'],
location:['En la rodilla dominante','Detrás de la espalda','Sobre el hombro contrario'],
movement:['Vibración rápida de muñeca','Salto vertical de la mano','Giros completos de codo'],
palm:['Hacia el techo siempre','Hacia el suelo siempre','Hacia tu propio ombligo'],
orientation:['Diagonal al piso','Paralela a la pared','Perpendicular al techo'],
facialExpression:['Mirada fija sin parpadear','Boca abierta sorprendida','Ceño fruncido permanente'],
repetition:['Cinco veces exactas','Media repetición','Siete veces seguidas'],
steps0:['Cerrar los ojos y contar tres','Gritar la palabra en voz alta','Saltar antes de comenzar a señar'],
mistakes0:['Usar la gramática de otra lengua de señas','Mirar fijamente el suelo al señar','Mover todo el torso en cada signo'],
context:['Únicamente en ceremonias formales','Solo durante llamadas telefónicas','Jamás se usa en la vida diaria']
};
function buildQuestions(conceptId, data, pool, lang){
const fields = [
{q:'Según la clase, ¿cuál es la configuración de la mano?', correct:data.anatomy.handshape, key:'handshape'},
{q:'¿Dónde se ubica exactamente esta seña?', correct:data.anatomy.location, key:'location'},
{q:'¿Qué movimiento describe la lección?', correct:data.anatomy.movement, key:'movement'},
{q:'¿Cómo se orienta la palma al ejecutarla?', correct:data.anatomy.palm, key:'palm'},
{q:'¿Qué orientación general enseña la clase?', correct:data.anatomy.orientation, key:'orientation'},
{q:'¿Qué expresión facial debe acompañarla?', correct:data.anatomy.facialExpression, key:'facialExpression'},
{q:'¿Cuántas repeticiones indica la lección?', correct:data.anatomy.repetition, key:'repetition'},
{q:'¿Cuál es el primer paso explicado en clase?', correct:data.steps[0], key:'steps0'},
{q:'¿Cuál de estos es un error común mencionado?', correct:data.mistakes[0], key:'mistakes0'}
];
const seedBase = hashStr(lang + conceptId);
return fields.map((f, idx) => {
const others = pool.filter(p => p.id !== conceptId && p.data).map(p => p.data);
let distractors = [];
if(f.key === 'steps0'){ distractors = seededShuffle(others.map(o => o.steps && o.steps[0]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
else if(f.key === 'mistakes0'){ distractors = seededShuffle(others.map(o => o.mistakes && o.mistakes[1]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
else { const k = f.key; distractors = seededShuffle(others.map(o => o.anatomy && o.anatomy[k]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
let pi = 0;
while(distractors.length < 3 && pi < 6){ const pad = (PADS[f.key]||PADS.context)[pi % 3]; if(pad !== f.correct && !distractors.includes(pad)){ distractors.push(pad); } pi++; }
const options = seededShuffle([f.correct].concat(distractors.slice(0,3)), seedBase + idx * 7 + 13);
return {question:f.q, options:options, correct:options.indexOf(f.correct), explanation:'La clase lo indica: ' + f.correct};
});
}

