const handleAnswer=(idx)=>{if(showFeedback)return;if(!currentQ)return;setSelectedAnswer(idx);const ok=currentQ.correct===idx;setIsCorrect(ok);setShowFeedback(true);setAnswers([...answers,idx]);if(ok)setCorrectCount(correctCount+1);const np={...progress};const lp={...(np.lessonProgress||{})};const prev=lp[lessonId]||{completed:false,correct:0,total:0,attempts:0};lp[lessonId]={...prev,correct:ok?prev.correct+1:prev.correct,total:prev.total+1,attempts:prev.attempts+1};np.lessonProgress=lp;onComplete(np);};
