<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginBottom:16,border:'1px solid var(--surface3)'}}><div style={{display:'flex',alignItems:'center',gap:12,marginBottom:20}}><span style={{fontSize:32}}>{ctp.icon}</span><h2 style={{fontSize:22,fontWeight:700,color:'var(--orange)'}}>{ctp.title}</h2></div><div style={{fontSize:15,lineHeight:1.8,color:'var(--text)',whiteSpace:'pre-line'}}>{ctp.content}</div></div>
<div style={{display:'flex',justifyContent:'space-between',gap:12}}>{teachingStep>0&&<button onClick={()=>setTeachingStep(teachingStep-1)} style={{padding:'12px 24px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600}}>← Anterior</button>}<div style={{flex:1}}/><button onClick={()=>{if(teachingStep<teachingPhases.length-1){setTeachingStep(teachingStep+1);}else{startQuiz();}}} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{teachingStep<teachingPhases.length-1?'Siguiente fase →':'Comenzar evaluación →'}</button></div></div>);}
const qp=totalQuestions>0?(currentQIdx/totalQuestions)*100:0;
