<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:12,marginBottom:16,border:'1px solid '+(correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)')}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6,flexWrap:'wrap',gap:8}}><span style={{fontSize:13,fontWeight:600}}>Progreso</span><span style={{fontSize:13,fontWeight:600,color:correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)'}}>{correctCount} correctas | Mínimo: {MIN_CORRECT}/{totalQuestions}</span></div><div style={{height:8,background:'var(--surface3)',borderRadius:4}}><div style={{height:'100%',background:'var(--violet)',borderRadius:4,width:qp+'%'}}/></div></div>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-lg)',padding:16,marginBottom:16,border:'2px solid var(--violet)',display:'flex',alignItems:'center',gap:16}}><DigiMascot expression={correctCount>=MIN_CORRECT?'excited':'thinking'} size={80} animated={true}/><div style={{flex:1}}><p style={{fontSize:15,lineHeight:1.6,color:'var(--text)'}}>{currentQIdx===0?'¡Preguntas basadas en la clase! Lee cada inciso con atención.':correctCount>=MIN_CORRECT?'¡Vas bien con '+correctCount+'! Sigue así.':'Llevas '+correctCount+'. Analiza bien cada opción.'}</p></div></div>
{currentQ&&(<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginBottom:16,border:'1px solid var(--surface3)'}}><h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{currentQ.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>{currentQ.options.map((opt,i)=>{let bg='var(--surface2)',bc='var(--surface3)',cl='var(--text)';if(showFeedback){if(i===currentQ.correct){bg='#064e3b';bc='var(--success)';cl='var(--success)';}else if(i===selectedAnswer&&i!==currentQ.correct){bg='#7f1d1d';bc='var(--error)';cl='var(--error)';}}else if(selectedAnswer===i){bg='var(--violet)';bc='var(--violet)';cl='white';}return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showFeedback} style={{padding:'14px 18px',background:bg,border:'2px solid '+bc,borderRadius:'var(--radius-sm)',color:cl,cursor:showFeedback?'default':'pointer',fontSize:14,textAlign:'left',fontWeight:selectedAnswer===i?600:400,lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);})}</div>
{showFeedback&&(<div style={{marginTop:20,padding:16,borderRadius:'var(--radius-sm)',background:isCorrect?'#064e3b':'#7f1d1d',border:'1px solid '+(isCorrect?'var(--success)':'var(--error)')}}><div style={{fontSize:16,fontWeight:700,color:isCorrect?'var(--success)':'var(--error)',marginBottom:6}}>{isCorrect?'¡Correcto!':'Incorrecto'}</div><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{currentQ.explanation}</p></div>)}</div>)}
