}

function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content=CONTENT_DATA[currentLang];if(!content||!content.stages)return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;
const [currentQ,setCurrentQ]=useState(0);const [answers,setAnswers]=useState([]);const [selected,setSelected]=useState(null);const [showResult,setShowResult]=useState(false);const [examComplete,setExamComplete]=useState(false);
let block=null,stageIdx=-1;for(let si=0;si<content.stages.length;si++){const bks=content.stages[si].blocks||[];for(let bi=0;bi<bks.length;bi++){if(bks[bi].id===blockId){block=bks[bi];stageIdx=si;break;}}if(block)break;}
if(!block)return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;
const questions=[];(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>questions.push(q));});
const eq=seededShuffle(questions, hashStr(blockId)).slice(0,10);
const q=eq[currentQ];const passThreshold=80;
const score=answers.filter((a,i)=>a===eq[i]?.correct).length;const scorePct=eq.length>0?Math.round((score/eq.length)*100):0;const passed=scorePct>=passThreshold;
const handleAnswer=(idx)=>{if(showResult)return;setSelected(idx);setShowResult(true);};
const nextQuestion=()=>{const na=[...answers,selected];setAnswers(na);if(currentQ<eq.length-1){setCurrentQ(currentQ+1);setSelected(null);setShowResult(false);}else{setExamComplete(true);const np={...progress};const bp={...(np.blockProgress||{})};bp[blockId]={passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};np.blockProgress=bp;if(scorePct>=passThreshold){const sp={...(np.stageProgress||{})};sp[currentLang]={...(sp[currentLang]||{})};sp[currentLang][stageIdx+1]=100;np.stageProgress=sp;}onComplete(np);}};
if(examComplete){return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div><h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2><p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'¡NIVELADO!':'Necesitas repasar el bloque'}</p></div><button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button></div>);}
return (<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Salir"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:13,color:'var(--text2)'}}>Examen de nivelación</div><div style={{fontSize:18,fontWeight:700}}>{block.name}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div><div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{eq.length}</div></div></div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}><div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:eq.length>0?((currentQ)/eq.length)*100:0+'%'}}/></div>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-lg)',padding:16,marginBottom:16,border:'2px solid var(--violet)',display:'flex',alignItems:'center',gap:16}}><DigiMascot expression="thinking" size={80} animated={true}/><div style={{flex:1}}><p style={{fontSize:15,lineHeight:1.6,color:'var(--text)'}}>Examen de nivelación: necesitas 80%. Lee con atención, ¡Digi te acompaña!</p></div></div>
{q&&(<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginBottom:16,border:'1px solid var(--surface3)'}}><h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>{q.options.map((opt,i)=>{let bg='var(--surface2)',bc='var(--surface3)',cl='var(--text)';if(showResult){if(i===q.correct){bg='#064e3b';bc='var(--success)';cl='var(--success)';}else if(i===selected&&i!==q.correct){bg='#7f1d1d';bc='var(--error)';cl='var(--error)';}}else if(selected===i){bg='var(--violet)';bc='var(--violet)';cl='white';}return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{padding:'14px 18px',background:bg,border:'2px solid '+bc,borderRadius:'var(--radius-sm)',color:cl,cursor:showResult?'default':'pointer',fontSize:14,textAlign:'left',lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);})}</div>
{showResult&&<div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p></div>}</div>)}
{showResult&&<div style={{display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQ<eq.length-1?'Siguiente →':'Ver resultados'}</button></div>}</div>);
}

function GenericPage({title,subtitle,children,onBack}){return (<div className="animate-in"><BackButton onClick={onBack} label="Inicio"/><h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>{title}</h1>{subtitle&&<p style={{color:'var(--text2)',marginBottom:24}}>{subtitle}</p>}{children}</div>);}
function AchievementsPage({progress,onBack}){const un=progress.achievements||[];const pct=Math.round((un.length/ACHIEVEMENT_DEFS.length)*100);
return (<GenericPage title="Logros" subtitle={un.length+' de '+ACHIEVEMENT_DEFS.length+' desbloqueados ('+pct+'%)'} onBack={onBack}>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,marginBottom:24,border:'1px solid var(--violet)'}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{fontSize:13,color:'var(--text2)',fontWeight:600}}>Progreso de logros</span><span style={{fontSize:13,color:'var(--yellow)',fontWeight:700}}>{pct}%</span></div><div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}><div style={{height:'100%',background:'linear-gradient(90deg,var(--violet),var(--yellow))',borderRadius:5,width:pct+'%',transition:'width 0.5s'}}/></div></div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))',gap:16}}>{ACHIEVEMENT_DEFS.map(a=>{const u=un.includes(a.id);return (<div key={a.id} className={'achievement-card '+(u?'unlocked':'locked')}><div style={{display:'flex',alignItems:'flex-start',justifyContent:'space-between',marginBottom:8}}><span className="achievement-icon">{a.icon}</span><span className={'achievement-status '+(u?'unlocked':'locked')}>{u?'✓ DESBLOQUEADO':'🔒 BLOQUEADO'}</span></div><div className="achievement-name">{a.name}</div><div className="achievement-desc">{a.desc}</div></div>);})}</div></GenericPage>);}
function ProgressDashboard({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const tl=stages.reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);const cl=Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;const cp=tl>0?Math.round((cl/tl)*100):0;
return (<GenericPage title="Progreso" subtitle={lang.flag+' '+lang.name+' - '+lang.supportLang} onBack={onBack}><div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:16,marginBottom:20,border:'1px solid var(--violet)'}}><div style={{fontSize:13,color:'var(--text2)'}}><strong>Gramática de {lang.code}:</strong> {lang.grammar}</div></div><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{cp}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{cl}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div></div></GenericPage>);}
function HistoryPage({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const er=Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));const lp2=Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));const glt=(id)=>{for(const st of stages){for(const b of (st.blocks||[])){const l=(b.lessons||[]).find(x=>x.id===id);if(l)return l.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag+' '+lang.code} onBack={onBack}><h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Exámenes de nivelación ({er.length})</h2>{er.length===0?<p style={{color:'var(--text2)',marginBottom:24}}>Sin exámenes.</p>:(<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{er.map(([bid,r])=>(<div key={bid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{bid}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(r.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:r.passed?'var(--success)':'var(--error)'}}>{r.score}%</div><div style={{fontSize:12,color:r.passed?'var(--success)':'var(--error)'}}>{r.passed?'NIVELADO':'NO NIVELADO'}</div></div></div>))}</div>)}<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lp2.filter(([_,v])=>v.completed).length})</h2>{lp2.length===0?<p style={{color:'var(--text2)'}}>Sin lecciones.</p>:(<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lp2.map(([lid,lp])=>(<div key={lid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{glt(lid)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}</GenericPage>);}
function ProfilePage({user,progress,onUpdate,onBack}){const [name,setName]=useState(user?.name||'');const [saved,setSaved]=useState(false);const hs=()=>{const u=getStorage('users',{});if(u[user.email]){u[user.email].name=name;setStorage('users',u);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}><div style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}><div style={{width:64,height:64,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:28,fontWeight:700,color:'white'}}>{(name||'U')[0].toUpperCase()}</div><div><div style={{fontSize:20,fontWeight:700}}>{name}</div><div style={{fontSize:14,color:'var(--text2)'}}>{user?.email}</div></div></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={user?.email||''} disabled style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text3)',fontSize:15}}/></div><button onClick={hs} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button></div></GenericPage>);}
function SettingsPage({settings,onUpdate,onBack}){const [dg,setDg]=useState(settings.dailyGoal||3);const [saved,setSaved]=useState(false);const hs=()=>{onUpdate({...settings,dailyGoal:dg});setSaved(true);setTimeout(()=>setSaved(false),2000);};
