const getRealFunFact=(lang)=>{const f=FUN_FACTS_BY_LANG[lang]||FUN_FACTS_BY_LANG.lsm;return f[Math.floor(Math.random()*f.length)];};
const E=(s)=>{const p=s.split('§');return{in:p[0],hs:p[1],th:p[2],pa:p[3],or:p[4],lo:p[5],mv:p[6],fa:p[7],re:p[8],st:(p[9]||'').split('|'),mi:(p[10]||'').split('|'),cx:p[11]||'',cu:p[12]||'',vi:p[13]||''};};
const DB={
lsm:{
g1:E("HOLA abre el canal visual: la B parte de la frente y viaja recta hacia la persona; contacto visual y sonrisa son gramática, no adorno. Practica frente al espejo sin doblar la muñeca.§B mano plana, dedos juntos§Cruzado sobre palma§Al frente al salir§Perpendicular a la frente§Frente, lado dominante§Lineal hacia la persona§Sonrisa y contacto visual§1 vez§Contacto visual primero|Forma la B|Toca la frente|Desplaza recto|Termina extendido§Muñeca doblada al final|Iniciar sin contacto visual|Usar puño A§Saludo universal: calle, escuela, trabajo.§En México se combina con cejas levantadas.§Imagina un saludo militar que se entrega."),
g2:E("BUENOS DÍAS evoca el sol que nace: la B con palma hacia arriba traza un arco ascendente desde el hombro; el arco debe ser amplio y lento, y la mirada lo acompaña.§B con palma hacia arriba§Cruzado§Hacia el cielo§Arco ascendente§Altura del hombro§Arco de abajo hacia arriba§Sonrisa tranquila§1 vez§B al hombro|Palma arriba|Arco ascendente|Mirada sigue el arco§Arco descendente|Palma hacia abajo|Arco pegado al cuerpo§Del amanecer al mediodía.§Se antepone a HOLA en cortesía matutina.§Dibuja el sol levantándose."),
g3:E("ADIÓS oscila la B lateralmente a la altura del hombro con palma al interlocutor; es una despedida visual personal y cálida. En grupo, despide a cada persona con contacto visual.§B con palma al frente§Cruzado§Hacia el interlocutor§Vertical§Lateral al cuerpo§Oscilación lateral§Sonrisa suave y asentimiento§2-3 oscilaciones§B al hombro|Palma a la persona|Oscila lateral|Cierra con asentimiento§Confundirlo con HOLA|Oscilación única cortante|Bajar la mirada§Cierre de encuentros y videollamadas.§En grupo se despide uno por uno.§Un te sigo viendo que se mece."),
g4:E("GRACIAS: la B toca la barbilla y viaja adelante-abajo como un beso de gratitud; el rostro agradece junto con la mano. Sin expresión facial el gracias queda vacío.§B que parte de la barbilla§Cruzado§Hacia tu rostro al inicio§Sale del plano medio§Barbilla§Adelante y ligeramente abajo§Gratitud visible§1 vez (2 = profunda)§Toca barbilla|Mira directo|Rostro agradecido|Desplaza adelante-abajo§Omitir la barbilla|Rostro neutro|Trayectoria hacia arriba§Favores, regalos y ayuda.§Agradecer visual es cortesía sorda.§Beso de gratitud que viaja."),
g5:E("PRESENTARSE es un ritual: HOLA para abrir el canal, YO al pecho con índice, y tu nombre deletreado con ritmo constante; luego cedes el turno señalando al otro. Pregunta siempre por el nombre en señas.§B, índice y letras§Variable por fase§Al pecho y al frente§Secuencia estructurada§Pecho a espacio frontal§Saludo, yo, deletreo§Sonrisa y atención sostenida§1 secuencia completa§Saluda con HOLA|Señala tu pecho|Deletrea tu nombre|Señala al otro§Deletreo demasiado rápido|Omitir el YO|Romper contacto visual§Primer encuentro con personas sordas.§El nombre en señas lo da la comunidad.§Un puente entre dos personas."),
a1:E("Alfabeto A-E: base del deletreo manual de una mano; lo esencial es la transición fluida entre letras con muñeca estable a la altura del hombro.§Varía por letra (ver póster)§Según configuración§Al frente o lateral§Muñeca estable§Altura del hombro§Transiciones fluidas§Neutra con mirada al receptor§1 vez por letra§Observa el póster|Cadena lenta A-E|Deletrea tu nombre|Acelera gradual§Letras a media configuración|Muñeca rígida|Mano pegada al cuerpo§Nombres, lugares y términos sin seña.§El deletreo apoya, no sustituye.§El póster es tu espejo de bolsillo."),
a2:E("Alfabeto F-J: aparecen orientaciones circulares y horizontales; F forma círculo, G y H apuntan horizontal, I aísla el meñique y J añade un trazo curvo final.§Circular y horizontal§Activo en F y J§Múltiple orientación§Horizontal en G y H§Altura del hombro§Trazo curvo en J§Neutra atenta§1 vez por letra§Círculo de F|G-H horizontales|Aísla I|Traza J completa§J sin gancho final|G con palma abajo|Confundir I con J§Apellidos y marcas.§Pocas letras llevan movimiento.§Firma tu J en el aire."),
a3:E("Alfabeto K-O: M y N pliegan tres y dos dedos sobre el pulgar; la Ñ oscila lateralmente y es identidad latina; O cierra el anillo. Verifica el conteo de pliegues.§Plegados y escuadra§Base de M, N y Ñ§Hacia el señante en M/N§Vertical general§Altura del hombro§Oscilación lateral en Ñ§Neutra§1 vez por letra§K y L limpias|M tres dedos|N dos dedos|Ñ oscila y O cierra§M con dos dedos|Ñ sin oscilación|L con pulgar caído§Palabras con ñ incluyen cultura.§La Ñ no existe en ASL.§Cuenta tus pliegues en el espejo."),
a4:E("Alfabeto P-T: P y Q invierten la orientación de K y G; R cruza índice y medio; S cierra el puño con pulgar al frente; T esconde el pulgar entre dedos.§Invertidas, cruce y puño§Frontal en S, interno en T§Abajo en P y Q§Invertida en P/Q§Altura del hombro§Estático con ajuste fino§Neutra§1 vez por letra§Invierte K y G|Cruza R|S pulgar al frente|T pulgar interno§Confundir S con A|R sin cruce real|P orientada arriba§Siglas y acrónimos.§Comparar P con K aclara la regla.§Grábate y compara."),
a5:E("Alfabeto U-Z: U junta índice y medio, V los separa, W extiende tres, X engancha, Y abre pulgar y meñique, Z traza una zeta en el aire.§Pares, tridente y gancho§Abierto en Y§Al frente§Vertical§Altura del hombro§Trazo en Z§Neutra§1 vez por letra§U juntos|V separados|W tridente|X gancho y Z trazo§U con dedos separados|X con índice recto|Z sin trazo completo§Nombres y palabras técnicas.§Deletrea mirando al receptor.§Unidos vs separados."),
n1:E("Números 1-5: conteo progresivo de dedos con palma al receptor; el 3 activa el pulgar y eso lo distingue de W. Practica contando objetos reales.§Conteo progresivo de dedos§Activo desde el 3§Al receptor§Vertical§Espacio neutro§Estático sin trayectoria§Neutra o enumerativa§1 vez por número§Índice 1|Suma medio 2|Suma pulgar 3|Mano completa 5§3 sin pulgar parece W|Palma hacia ti|Dedos a medio extender§Edades, cantidades y precios básicos.§La mirada enumera contigo.§Cuenta tus dedos en el espejo."),
n2:E("Números 6-10: el pulgar visita los dedos de afuera hacia adentro (6 meñique, 7 anular, 8 medio, 9 índice); el 10 compone índice y círculo.§Contacto pulgar-dedo§Punto de contacto móvil§Al receptor§Vertical§Espacio neutro§Cambio de contacto§Neutra§1 vez por número§6 meñique|7 anular|8 medio|9 índice y 10 compuesto§6 con pulgar en índice|10 en un solo gesto|Reconfigurar toda la mano§Horas, precios y conteos medios.§El 10 abre la puerta a decenas.§El pulgar es un ascensor."),
n3:E("Números 11-19: composición decimal en dos pulsos rítmicos, primero 10 y luego la unidad; el ritmo visual sustituye al y hablado.§Secuencia 10 más unidad§Según la unidad§Al receptor§Vertical§Espacio neutro§Dos pulsos rítmicos§Cejas marcan cada pulso§2 configuraciones por número§10 nítido|Pausa mínima|Unidad clara|Encadena 11 a 19§Un solo pulso|Unidad con configuración errónea|Velocidad sin ritmo§Edades adolescentes y fechas.§El ritmo es gramática visible.§Dos latidos: diez y unidad."),
n4:E("Decenas 20-90: se forma el dígito base nítido y se agrega un giro de muñeca que marca la decena; luego combina, por ejemplo 45 = 40 + 5.§Dígito más marcador de decena§Según dígito§Al receptor§Giro final de muñeca§Espacio neutro§Estático más giro decenal§Neutra§2 pulsos por decena§Dígito base|Giro de decena|Practica 20 a 40|Combina 45§Giro antes del dígito|Decena sin dígito claro|Confundir 70 con 7§Precios, años y cantidades grandes.§Orden mayor a menor siempre.§El giro es la coma del aire."),
n5:E("El 100 y combinaciones: 100 = índice seguido de dos ceros; cualquier número hasta 999 se construye con pulsos separados de centena, decena y unidad.§1 más 00 y cadena decimal§Variable§Al receptor§Vertical§Espacio neutro§Pulsos encadenados mayor a menor§Cejas marcan cada pulso§1 pulso por componente§100 claro|200 y 300|Combina 125|Reto tu año§Componentes fundidos en uno|Orden menor a mayor|Ceros sin forma O§Años, precios altos y estadística.§Contar dinero es habilidad comunitaria.§Cada pulso es una cifra."),
s1:E("Oraciones en LSM: orden típico OSV (Objeto-Sujeto-Verbo) con tópico marcable por cejas; los verbos direccionales viajan entre puntos del espacio que representan personas.§Secuencia de signos léxicos§No aplica§No aplica§Tópico puede adelantarse§Espacio gramatical frontal§OSV con verbos direccionales§Cejas y torso marcan roles§1 oración por práctica§Elige frase|Identifica objeto y sujeto|Señala objeto primero|Sujeto y verbo§Calco palabra por palabra|Tópico sin marcador facial|Verbo sin puntos espaciales§Narrar eventos cotidianos.§La LSM no es español señado.§Bloques OBJETO-SUJETO-VERBO."),
s2:E("Preguntas sí/no: cejas levantadas, cabeza ligeramente inclinada y sostenimiento del signo final; no existe un signo de interrogación: el rostro pregunta.§Signos léxicos más marcador facial§No aplica§No aplica§No aplica§Rostro como zona gramatical§Sostenimiento final del signo§Cejas ARRIBA y cabeza inclinada§1 por pregunta§Relaja el rostro|Sube cejas|Inclina la cabeza|Sostén el signo final§Cejas neutras|Cejas fruncidas|Terminar sin sostenimiento§Confirmar información diaria.§El rostro es el signo de interrogación.§Tu cara escribe los signos."),
s3:E("Preguntas WH (qué, dónde, quién): cejas FRUNCIDAS sostenidas y signo interrogativo al final de la oración, con ligera inclinación del torso.§Signo WH final más cejas fruncidas§No aplica§No aplica§No aplica§Rostro y torso§WH al cierre con inclinación§Cejas FRUNCIDAS sostenidas§1 por pregunta§Frunce antes de iniciar|Señala la proposición|Cierra con WH|Mirada expectante§WH al inicio|Cejas levantadas en WH|Frunce que cae a mitad§Solicitar información abierta.§WH final es marca de lenguas de señas.§Cejas fruncidas son una lupa."),
s4:E("Negación y tiempo: NO se acompaña de sacudida lateral de cabeza simultánea; el tiempo vive en el espacio, pasado detrás, presente al centro y futuro adelante.§NO más línea de tiempo espacial§No aplica§No aplica§Pasado atrás, futuro adelante§Eje sagital del cuerpo§Sacudida en NO y toques de tiempo§Cabeza niega y cejas según tipo§1 por cláusula§Ubica tu línea|AYER atrás|HOY al centro|NO con sacudida§Negar solo con la mano|Tiempo verbal al final|Pasado señalado al frente§Narrar rutinas y planes.§El espacio-tiempo es gramática visible.§Tu cuerpo es flecha del tiempo."),
