function HelpPage({onBack}){return(<GenericPage title="Ayuda" onBack={onBack}><div style={{display:'flex',flexDirection:'column',gap:16}}>{[{q:'¿Cuántas lenguas hay?',a:'4 lenguas independientes: LSM, LSF, ASL, LSC.'},{q:'¿Cómo cambio de lengua?',a:'Con los botones del panel lateral.'},{q:'¿Cómo se nivela un bloque?',a:'Completa todas sus lecciones (5/9) y aprueba el EXAMEN DE NIVELACIÓN con 80%.'},{q:'¿Las preguntas del quiz?',a:'Se basan en lo enseñado en clase y sus incisos aparecen en orden aleatorio.'}].map((it,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{it.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{it.a}</p></div>))}</div></GenericPage>);}
