.nav-item .icon{font-size:18px;width:22px;display:flex;align-items:center;justify-content:center}
.nav-item .icon svg{width:18px;height:18px}
.nav-group{margin-bottom:4px}.nav-group-label{font-size:10px;color:var(--text3);font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:8px 16px 4px}
.logout-btn{width:100%;padding:10px;background:transparent;border:1px solid var(--error);border-radius:var(--radius-sm);color:var(--error);cursor:pointer;font-size:13px;font-weight:600;transition:var(--transition);font-family:'Inter',sans-serif;display:flex;align-items:center;justify-content:center;gap:6px}
.logout-btn:hover{background:var(--error);color:white}
.toggle-sidebar-btn{background:var(--violet);border:2px solid var(--orange);color:white;cursor:pointer;font-size:20px;padding:10px 14px;border-radius:var(--radius-sm);transition:all 0.3s ease;font-family:'Inter',sans-serif;font-weight:700;box-shadow:0 4px 12px rgba(102,87,200,0.4);display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px}
.toggle-sidebar-btn:hover{background:#7c6fd4;transform:scale(1.05)}.toggle-sidebar-btn:active{transform:scale(0.95)}
.digi-assistant{position:fixed;bottom:20px;right:20px;z-index:100;display:flex;flex-direction:column;align-items:flex-end;gap:12px}
.digi-speech-bubble{background:var(--surface);border:2px solid var(--violet);border-radius:var(--radius-lg);padding:16px 20px;max-width:300px;box-shadow:0 8px 32px rgba(102,87,200,0.3);animation:speechBubble 0.4s ease-out;position:relative}
.digi-speech-bubble::before{content:'';position:absolute;bottom:-10px;right:30px;width:0;height:0;border-left:10px solid transparent;border-right:10px solid transparent;border-top:10px solid var(--violet)}
.digi-speech-bubble p{font-size:14px;line-height:1.5;color:var(--text);margin:0}
.digi-character{cursor:pointer;transition:transform 0.3s ease;filter:drop-shadow(0 4px 12px rgba(102,87,200,0.4))}
.digi-character:hover{transform:scale(1.1)}.digi-character svg{width:140px;height:140px}
.splash-screen{position:fixed;inset:0;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:10000}
.splash-logo{width:280px;height:280px;animation:spinIn 1.8s cubic-bezier(0.34,1.56,0.64,1) forwards}
.splash-logo.spinning{animation:spin 2.5s linear infinite}
.splash-text{margin-top:40px;font-size:48px;font-weight:900;color:#a8a8ff;letter-spacing:4px;animation:textReveal 1s ease-out 0.8s both;font-family:'Inter',sans-serif}
.splash-exit{animation:fadeOut 0.6s ease-out forwards}
.auth-container{min-height:100vh;display:flex;background:linear-gradient(135deg,#0f0f1a 0%,#1a1a2e 50%,#0f0f1a 100%);overflow:hidden}
.auth-form-section{flex:1;display:flex;align-items:center;justify-content:center;padding:40px;max-width:500px}
.auth-digi-section{flex:1.2;display:flex;align-items:center;justify-content:center;position:relative;padding:40px}
.auth-digi-character{animation:digiFloat 3s ease-in-out infinite}
.auth-digi-character svg{width:100%;max-width:600px;height:auto;filter:drop-shadow(0 12px 32px rgba(102,87,200,0.5))}
.auth-greeting-bubble{position:absolute;top:60px;right:80px;background:var(--surface);border:3px solid var(--yellow);border-radius:20px;padding:20px 28px;max-width:280px;box-shadow:0 8px 32px rgba(255,212,71,0.3);animation:speechBubble 0.5s ease-out 1s both}
.auth-greeting-bubble::before{content:'';position:absolute;bottom:-12px;left:40px;width:0;height:0;border-left:12px solid transparent;border-right:12px solid transparent;border-top:12px solid var(--yellow)}
.auth-greeting-bubble p{font-size:18px;line-height:1.5;color:var(--text);margin:0;font-weight:600}
.app-container{display:flex;min-height:100vh}
.sidebar{width:280px;height:100vh;background:var(--surface);border-right:1px solid var(--surface3);position:fixed;left:0;top:0;z-index:100;display:flex;flex-direction:column;transition:transform 0.3s cubic-bezier(0.4,0,0.2,1);overflow-y:auto}
.main-content{flex:1;min-height:100vh;transition:margin-left 0.3s cubic-bezier(0.4,0,0.2,1)}
@media(min-width:1024px){.sidebar{transform:translateX(0)}.sidebar.hidden{transform:translateX(-100%)}.main-content{margin-left:280px}.main-content.expanded{margin-left:0}.desktop-only{display:flex!important}.mobile-only{display:none!important}}
@media(max-width:1023px){.sidebar{transform:translateX(-100%)}.sidebar.visible{transform:translateX(0);box-shadow:var(--shadow)}.main-content{margin-left:0!important}.desktop-only{display:none!important}.mobile-only{display:flex!important}.auth-container{flex-direction:column}.auth-form-section{max-width:100%;padding:20px}.auth-digi-section{padding:20px;min-height:400px}.auth-digi-character svg{max-width:400px}.auth-greeting-bubble{top:30px;right:40px;max-width:220px;padding:16px 20px}.auth-greeting-bubble p{font-size:15px}.digi-character svg{width:100px;height:100px}.digi-speech-bubble{max-width:250px;padding:12px 16px}}
@media(max-width:600px){.main-content{padding:16px!important}.main-header{padding:10px 16px!important}.splash-logo{width:200px;height:200px}.splash-text{font-size:32px}.back-btn{top:70px;left:10px;padding:8px 12px;font-size:12px}.auth-digi-character svg{max-width:300px}.auth-greeting-bubble{top:20px;right:20px;max-width:180px;padding:12px 16px}.auth-greeting-bubble p{font-size:13px}}
.achievement-card{background:var(--surface);border-radius:var(--radius);padding:24px;border:2px solid var(--surface3);transition:var(--transition);position:relative;overflow:hidden}
.achievement-card.unlocked{border-color:var(--yellow);box-shadow:0 0 20px rgba(255,212,71,0.2)}
.achievement-card.locked{opacity:0.5}
.achievement-icon{font-size:48px;margin-bottom:12px;display:block}
.achievement-name{font-size:16px;font-weight:700;margin-bottom:4px}
.achievement-desc{font-size:13px;color:var(--text2);margin-bottom:12px;line-height:1.4}
.achievement-status{font-size:11px;font-weight:700;padding:4px 10px;border-radius:10px;display:inline-block}
.achievement-status.unlocked{background:#3d3520;color:var(--yellow)}
.achievement-status.locked{background:var(--surface3);color:var(--text3)}
.sign-poster-card{background:#F5B800;border-radius:var(--radius-lg);padding:20px;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.4);margin-bottom:20px;border:3px solid #111}
.sign-poster-card svg{max-width:100%;height:auto;overflow:visible}
.sign-poster-title{margin-top:10px;font-size:22px;font-weight:900;color:#111;letter-spacing:2px}
.sign-poster-sub{font-size:13px;color:#333;margin-top:4px;font-weight:600}
.key-point{background:var(--surface2);border-left:4px solid var(--yellow);padding:10px 14px;border-radius:0 var(--radius-sm) var(--radius-sm) 0;margin-bottom:8px;font-size:14px;line-height:1.6;color:var(--text)}
