const DigiMascot=({expression='happy',size=140,animated=true,waving=false})=>{const exps={happy:{mouth:'M 45 72 Q 50 78 55 72',eyes:'open',eyebrows:'normal',cheeks:true},excited:{mouth:'M 42 70 Q 50 82 58 70',eyes:'sparkle',eyebrows:'raised',cheeks:true},thinking:{mouth:'M 46 73 Q 50 74 54 73',eyes:'side',eyebrows:'raised',cheeks:false},encouraging:{mouth:'M 44 71 Q 50 77 56 71',eyes:'open',eyebrows:'normal',cheeks:true},sad:{mouth:'M 44 75 Q 50 70 56 75',eyes:'open',eyebrows:'sad',cheeks:false},celebrating:{mouth:'M 40 68 Q 50 82 60 68',eyes:'sparkle',eyebrows:'raised',cheeks:true},teaching:{mouth:'M 44 71 Q 50 76 56 71',eyes:'open',eyebrows:'normal',cheeks:true},welcoming:{mouth:'M 42 70 Q 50 80 58 70',eyes:'sparkle',eyebrows:'raised',cheeks:true}};const e=exps[expression]||exps.happy;
