const allQ=[];(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>allQ.push(q));});
const eq=seededShuffle(allQ,hashStr(blockId)).slice(0,10);
const q=eq[currentQ];const passThreshold=80;const score=answers.filter((a,i)=>a===eq[i]?.correct).length;const scorePct=eq.length>0?Math.round((score/eq.length)*100):0;const passed=scorePct>=passThreshold;
