{sb.map((block,bi)=>{const bun=isBlockUnlocked(si,bi);const bpass=progress.blockProgress?.[block.id]?.passed||false;const bls=block.lessons||[];const bcomp=bls.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
