function AchievementsPage({progress,onBack}){const un=progress.achievements||[];const pct=ACHIEVEMENT_DEFS.length>0?Math.round((un.length/ACHIEVEMENT_DEFS.length)*100):0;return(<GenericPage title="Logros" subtitle={un.length+' de '+ACHIEVEMENT_DEFS.length+' desbloqueados ('+pct+'%)'} onBack={onBack}><div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,marginBottom:24,border:'1px solid var(--violet)'}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{fontSize:13,color:'var(--text2)',fontWeight:600}}>Progreso de logros</span><span style={{fontSize:13,color:'var(--yellow)',fontWeight:700}}>{pct}%</span></div><div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}><div style={{height:'100%',background:'linear-gradient(90deg,var(--violet),var(--yellow))',borderRadius:5,width:pct+'%'}}/></div></div><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))',gap:16}}>{ACHIEVEMENT_DEFS.map(a=>{const u=un.includes(a.id);return(<div key={a.id} className={'achievement-card '+(u?'unlocked':'locked')}><div style={{display:'flex',alignItems:'flex-start',justifyContent:'space-between',marginBottom:8}}><span className="achievement-icon">{a.icon}</span><span className={'achievement-status '+(u?'unlocked':'locked')}>{u?'✓ DESBLOQUEADO':'🔒 BLOQUEADO'}</span></div><div className="achievement-name">{a.name}</div><div className="achievement-desc">{a.desc}</div></div>);})}</div></GenericPage>);}
