function HistoryPage({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const er=Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));const lp2=Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));const glt=(id)=>{for(const st of stages){for(const b of(st.blocks||[])){const l=(b.lessons||[]).find(x=>x.id===id);if(l)return l.title;}}return id;};return(<GenericPage title="Historial" subtitle={lang.flag+' '+lang.code} onBack={onBack}><h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Exámenes de nivelación ({er.length})</h2>{er.length===0?<p style={{color:'var(--text2)',marginBottom:24}}>Sin exámenes.</p>:(<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{er.map(([bid,r])=>(<div key={bid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{bid}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(r.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:r.passed?'var(--success)':'var(--error)'}}>{r.score}%</div><div style={{fontSize:12,color:r.passed?'var(--success)':'var(--error)'}}>{r.passed?'NIVELADO':'NO NIVELADO'}</div></div></div>))}</div>)}<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lp2.filter(([_,v])=>v.completed).length})</h2>{lp2.length===0?<p style={{color:'var(--text2)'}}>Sin lecciones.</p>:(<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lp2.map(([lid,lp])=>(<div key={lid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'fle