useEffect(()=>{const na=[...(progress.achievements||[])];let ch=false;ACHIEVEMENT_DEFS.forEach(a=>{if(!na.includes(a.id)&&a.condition(progress)){na.push(a.id);ch=true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});if(ch)setProgress(p=>({...p,achievements:na}));},[progress]);
