if(currentScreen==='lesson'&&activeLesson)return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack} onCuriousOpen={handleCuriousOpen} onNavigate={handleNavigate}/>;
if(currentScreen==='exam'&&activeExam)return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
