function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
const lang = LANGUAGES[currentLang];
const [currentStepIdx,setCurrentStepIdx] = useState(0);
const [selectedAnswer,setSelectedAnswer] = useState(null);
const [showFeedback,setShowFeedback] = useState(false);
const [isCorrect,setIsCorrect] = useState(null);
const [lessonComplete,setLessonComplete] = useState(false);

let block=null, lesson=null;
for(const stage of content.stages){
for(const b of stage.blocks){
if(b.id===blockId){block=b;break}
}
if(block) break;
}
if(block) lesson = block.lessons.find(l=>l.id===lessonId);
if(!lesson) return <div style={{padding:40,textAlign:'center'}}>Lección no encontrada.</div>;

const steps = lesson.steps;
const step = steps[currentStepIdx];
const totalSteps = steps.length;
const progress_pct = ((currentStepIdx)/totalSteps)*100;

const digiExpressions = {intro:'happy',concept:'thinking',demo:'encouraging',practice:'encouraging',quiz:'happy'};
const digiMessages = {
intro:'¡Vamos a aprender algo nuevo!',
concept:'Este concepto es importante. Presta atención.',
demo:'Observa cuidadosamente la demostración.',
practice:'¡Es tu turno! Piensa bien la respuesta.',
quiz:'Demuestra lo que has aprendido.'
};

const handleAnswer = (idx) => {
if(showFeedback) return;
setSelectedAnswer(idx);
const correct = step.correct === idx;
setIsCorrect(correct);
setShowFeedback(true);
if(correct){
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
lp[lessonId] = {completed:true,correct:(lp[lessonId]?.correct||0)+1,total:(lp[lessonId]?.total||0)+1};
newProgress.lessonProgress = lp;
const cp = {...(newProgress.courseProgress||{})};
cp[currentLang] = Math.min(100,(cp[currentLang]||0)+2);
newProgress.courseProgress = cp;
const tl = (newProgress.todayLessons||0)+1;
newProgress.todayLessons = tl;
if(tl >= (newProgress.dailyGoal||3)) newProgress.streak = (newProgress.streak||0)+1;
onComplete(newProgress);
} else {
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
lp[lessonId] = {completed:lp[lessonId]?.completed||false,correct:lp[lessonId]?.correct||0,total:(lp[lessonId]?.total||0)+1};
newProgress.lessonProgress = lp;
const ri = [...(newProgress.reviewItems?.[currentLang]||[])];
if(!ri.includes(lessonId)) ri.push(lessonId);
const rItems = {...(newProgress.reviewItems||{})};
rItems[currentLang] = ri;
newProgress.reviewItems = rItems;
onComplete(newProgress);
}
};

const nextStep = () => {
if(currentStepIdx < totalSteps-1){
setCurrentStepIdx(currentStepIdx+1);
setSelectedAnswer(null);
setShowFeedback(false);
setIsCorrect(null);
} else {
setLessonComplete(true);
}
};

if(lessonComplete){
return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide message={`¡Excelente! Has completado la lección "${lesson.title}". ${isCorrect?'¡Muy bien hecho!':'Sigue practicando para mejorar.'}`} expression="celebrating" action={onBack} actionLabel="Volver a la ruta"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:48,marginBottom:12}}>🎉</div>
<h2 style={{fontSize:24,fontWeight:700,marginBottom:8}}>¡Lección Completada!</h2>
<p style={{color:'var(--text2)'}}>{lesson.title} — {lang.code}</p>
</div>
</div>
);
}

return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}} onMouseOver={e=>e.target.style.background='var(--surface3)'} onMouseOut={e=>e.target.style.background='var(--surface2)'}>← Volver</button>

<div style={{marginBottom:20}}>
<div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}>
<span style={{fontSize:13,color:'var(--text2)'}}>Paso {currentStepIdx+1} de {totalSteps}</span>
<span style={{fontSize:13,color:'var(--text2)'}}>{Math.round(progress_pct)}%</span>
</div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3}}>
<div style={{height:'100%',background:'var(--violet)',borderRadius:3,width:progress_pct+'%',transition:'width 0.3s'}}/>
</div>
</div>

<h2 style={{fontSize:22,fontWeight:700,marginBottom:16}}>{lesson.title}</h2>

<DigiGuide message={digiMessages[step.type]||''} expression={digiExpressions[step.type]||'happy'}/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
{step.type==='intro' && (
<div>
<p style={{fontSize:16,lineHeight:1.8,color:'var(--text)'}}>{step.text}</p>
</div>
)}

{step.type==='concept' && (
<div>
<h3 style={{fontSize:18,fontWeight:700,color:'var(--orange)',marginBottom:12}}>{step.title}</h3>
<p style={{fontSize:15,lineHeight:1.7,color:'var(--text)'}}>{step.text}</p>
</div>
)}

{step.type==='demo' && (
<div>
<h3 style={{fontSize:18,fontWeight:700,color:'var(--orange)',marginBottom:12}}>{step.title}</h3>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:32,textAlign:'center',marginBottom:16,minHeight:200,display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',border:'2px dashed var(--surface3)'}}>
<div style={{fontSize:64,marginBottom:12}}>🤟</div>
<p style={{fontSize:14,color:'var(--text2)',fontStyle:'italic'}}>
⚠️ Contenido pendiente de validación — Se requiere video demostrativo de la comunidad sorda
</p>
<p style={{fontSize:13,color:'var(--text3)',marginTop:8}}>Recurso visual provisional</p>
</div>
<p style={{fontSize:15,lineHeight:1.7,color:'var(--text)',marginBottom:12}}>{step.text}</p>
{step.signDetail && (
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:16,borderLeft:'3px solid var(--violet)'}}>
<div style={{fontSize:13,fontWeight:700,color:'var(--violet)',marginBottom:6}}>📋 Detalles de la seña:</div>
<p style={{fontSize:14,color:'var(--text2)',lineHeight:1.6}}>{step.signDetail}</p>
</div>
)}
</div>
)}

{(step.type==='practice'||step.type==='quiz') && (
<div>
<h3 style={{fontSize:17,fontWeight:700,marginBottom:16}}>{step.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{step.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showFeedback){
if(i===step.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}
else if(i===selectedAnswer&&i!==step.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}
} else if(selectedAnswer===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (
<button key={i} onClick={()=>handleAnswer(i)} disabled={showFeedback} style={{
padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',
color:color,cursor:showFeedback?'default':'pointer',fontSize:15,textAlign:'left',
transition:'var(--transition)',fontWeight:selectedAnswer===i?600:400
}}
onMouseOver={e=>!showFeedback&&(e.target.style.borderColor='var(--violet)')}
onMouseOut={e=>!showFeedback&&(e.target.style.borderColor=selectedAnswer===i?'var(--violet)':'var(--surface3)')}
>
<span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}
</button>
);
})}
</div>

{showFeedback && (
<div style={{marginTop:20,padding:16,borderRadius:'var(--radius-sm)',background:isCorrect?'#064e3b':'#7f1d1d',border:'1px solid '+(isCorrect?'var(--success)':'var(--error)')}}>
<div style={{fontSize:16,fontWeight:700,color:isCorrect?'var(--success)':'var(--error)',marginBottom:6}}>
{isCorrect?'✓ ¡Correcto!':'✗ Incorrecto'}
</div>
<p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{step.explanation}</p>
</div>
)}
</div>
)}
</div>

<div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}>
{showFeedback ? (
<button onClick={nextStep} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600,transition:'var(--transition)'}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
{currentStepIdx<totalSteps-1?'Siguiente →':'Finalizar lección'}
</button>
) : (step.type!=='practice'&&step.type!=='quiz' ? (
<button onClick={nextStep} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600,transition:'var(--transition)'}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
Continuar →
</button>
) : null)}
</div>
</div>
);
}

function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
const lang = LANGUAGES[currentLang];
const [currentQ,setCurrentQ] = useState(0);
const [answers,setAnswers] = useState([]);
const [selected,setSelected] = useState(null);
const [showResult,setShowResult] = useState(false);
const [examComplete,setExamComplete] = useState(false);

let block=null;
for(const stage of content.stages){for(const b of stage.blocks){if(b.id===blockId){block=b;break}}if(block)break}
if(!block) return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;

// Collect all quiz/practice questions from lessons
const questions = [];
block.lessons.forEach(l=>{
l.steps.forEach(s=>{
if(s.type==='quiz'||s.type==='practice'){
questions.push({question:s.question,options:s.options,correct:s.correct,explanation:s.explanation,lessonId:l.id});
}
});
});

// If not enough questions, add some generated ones
while(questions.length<5){
questions.push({question:`Pregunta de repaso ${questions.length+1} de ${block.name}`,options:['Opción A','Opción B','Opción C','Opción D'],correct:0,explanation:'Contenido pendiente de validación.',lessonId:block.lessons[0]?.id});
}

const q = questions[currentQ];
const passThreshold = 80;
const score = answers.filter((a,i)=>a===questions[i].correct).length;
const scorePct = Math.round((score/questions.length)*100);
const passed = scorePct >= passThreshold;

const handleAnswer = (idx) => {
if(showResult) return;
setSelected(idx);
setShowResult(true);
};

const nextQuestion = () => {
const newAnswers = [...answers, selected];
setAnswers(newAnswers);
if(currentQ < questions.length-1){
setCurrentQ(currentQ+1);
setSelected(null);
setShowResult(false);
} else {
setExamComplete(true);
const newProgress = {...progress};
const bp = {...(newProgress.blockProgress||{})};
bp[blockId] = {passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};
newProgress.blockProgress = bp;
const er = {...(newProgress.examResults||{})};
er[blockId] = {score:scorePct,passed:scorePct>=passThreshold,date:new Date().toISOString(),attempts:(er[blockId]?.attempts||0)+1};
newProgress.examResults = er;
if(scorePct>=passThreshold){
const cp = {...(newProgress.courseProgress||{})};
cp[currentLang] = Math.min(100,(cp[currentLang]||0)+10);
newProgress.courseProgress = cp;
const sp = {...(newProgress.stageProgress||{})};
sp[currentLang] = {...(sp[currentLang]||{})};
const currentStageNum = content.stages.findIndex(s=>s.blocks.some(b=>b.id===blockId))+1;
sp[currentLang][currentStageNum] = Math.min(100,(sp[currentLang][currentStageNum]||0)+20);
newProgress.stageProgress = sp;
}
onComplete(newProgress);
}
};

if(examComplete){
return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide
message={passed?`¡Felicidades! Aprobaste el examen de "${block.name}" con ${scorePct}%. ¡Excelente trabajo!`:`Obtuviste ${scorePct}% en el examen de "${block.name}". Necesitas ${passThreshold}% para aprobar. ¡No te desanimes, puedes repasar y volver a intentarlo!`}
expression={passed?'celebrating':'encouraging'}
action={onBack}
actionLabel={passed?'Continuar':'Repasar lecciones'}
/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div>
<h2 style={{fontSize:28,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2>
<p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>
{passed?'¡Examen Aprobado!':'Necesitas repasar'}
</p>
<p style={{color:'var(--text3)',fontSize:14,marginTop:4}}>{score} de {questions.length} respuestas correctas</p>
<div style={{marginTop:20,display:'flex',gap:12,justifyContent:'center',flexWrap:'wrap'}}>
{questions.map((q,i)=>(
<div key={i} style={{width:36,height:36,borderRadius:'50%',background:answers[i]===q.correct?'var(--success)':'var(--error)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>{i+1}</div>
))}
</div>
</div>
</div>
);
}

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}} onMouseOver={e=>e.target.style.background='var(--surface3)'} onMouseOut={e=>e.target.style.background='var(--surface2)'}>← Salir del examen</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div>
<div style={{fontSize:13,color:'var(--text2)'}}>Examen de bloque</div>
<div style={{fontSize:18,fontWeight:700}}>{block.name}</div>
</div>
<div style={{textAlign:'right'}}>
<div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div>
<div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{questions.length}</div>
</div>
</div>

<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}>
<div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/questions.length*100)+'%',transition:'width 0.3s'}}/>
</div>

<DigiGuide message="Responde cuidadosamente. Necesitas 80% para aprobar este bloque." expression="thinking"/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<h3 style={{fontSize:18,fontWeight:700,marginBottom:20}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{q.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showResult){
if(i===q.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}
else if(i===selected&&i!==q.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}
} else if(selected===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (
<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{
padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',
color:color,cursor:showResult?'default':'pointer',fontSize:15,textAlign:'left',transition:'var(--transition)'
}}
onMouseOver={e=>!showResult&&(e.target.style.borderColor='var(--violet)')}
onMouseOut={e=>!showResult&&(e.target.style.borderColor=selected===i?'var(--violet)':'var(--surface3)')}
>
<span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}
</button>
);
})}
</div>
{showResult && (
<div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}>
<p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p>
</div>
)}
</div>

{showResult && (
<div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}>
<button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
{currentQ<questions.length-1?'Siguiente pregunta →':'Ver resultados'}
</button>
</div>
)}
</div>
);
}

function ReviewCenter({currentLang,progress,onStartReview}) {
const lang = LANGUAGES[currentLang];
const reviewItems = progress.reviewItems?.[currentLang] || [];
const content = CONTENT_DATA[currentLang];

const getLessonInfo = (lessonId) => {
for(const stage of content.stages){
for(const block of stage.blocks){
const lesson = block.lessons.find(l=>l.id===lessonId);
