function AccessibilitySettings({settings,onUpdate}) {
const [textSize,setTextSize] = useState(settings.textSize||'normal');
const [highContrast,setHighContrast] = useState(settings.highContrast||false);
const [reduceMotion,setReduceMotion] = useState(settings.reduceMotion||false);

useEffect(()=>{
document.body.classList.toggle('large-text',textSize==='large');
document.body.classList.toggle('xlarge-text',textSize==='xlarge');
document.body.classList.toggle('high-contrast',highContrast);
document.body.classList.toggle('reduce-motion',reduceMotion);
},[textSize,highContrast,reduceMotion]);

const handleSave = () => {
onUpdate({...settings,textSize,highContrast,reduceMotion});
};

return (
<div className="animate-in">
