padding:'10px 20px',background:textSize===s?'var(--violet)':'var(--surface2)',
border:'1px solid '+(textSize===s?'var(--violet)':'var(--surface3)'),
borderRadius:'var(--radius-sm)',color:'var(--text)',cursor:'pointer',fontSize:14,fontWeight:600
}}>{s==='normal'?'Normal':s==='large'?'Grande':'Muy grande'}</button>
))}
</div>
</div>

<div style={{marginBottom:24}}>
<label style={{display:'flex',alignItems:'center',gap:12,cursor:'pointer'}}>
<input type="checkbox" checked={highContrast} onChange={e=>setHighContrast(e.target.checked)} style={{width:20,height:20,accentColor:'var(--violet)'}}/>
