</label>
</div>

<div style={{marginBottom:24}}>
<label style={{display:'flex',alignItems:'center',gap:12,cursor:'pointer'}}>
<input type="checkbox" checked={reduceMotion} onChange={e=>setReduceMotion(e.target.checked)} style={{width:20,height:20,accentColor:'var(--violet)'}}/>
<div>
<div style={{fontSize:14,fontWeight:600}}>Reducir animaciones</div>
<div style={{fontSize:12,color:'var(--text2)'}}>Minimiza movimientos y transiciones</div>
</div>
</label>
</div>

<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
Aplicar cambios
</button>
</div>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',maxWidth:600}}>
<h3 style={{fontSize:16,fontWeight:700,marginBottom:12}}>Información de accesibilidad</h3>
