// ============ MAIN APP ============
function App() {
const [user,setUser] = useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang] = useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen] = useState('home');
const [sidebarOpen,setSidebarOpen] = useState(false);
const [progress,setProgress] = useState(()=>getStorage('progress',{
courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},
examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3
}));
const [settings,setSettings] = useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson] = useState(null);
const [activeExam,setActiveExam] = useState(null);
const [mobileMenuOpen,setMobileMenuOpen] = useState(false);

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

// Check achievements
useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
ACHIEVEMENT_DEFS.forEach(a=>{
if(!newAchievements.includes(a.id) && a.condition(progress)){
newAchievements.push(a.id);
}
});
if(newAchievements.length !== (progress.achievements||[]).length){
setProgress(p=>({...p,achievements:newAchievements}));
}
},[progress]);

const handleAuth = (userData) => {
setUser(userData);
setStorage('currentUser',userData);
setCurrentScreen('home');
};

const handleLogout = () => {
setUser(null);
localStorage.removeItem('lsmexa_currentUser');
setCurrentScreen('home');
};

const handleLangChange = (lang) => {
if(activeLesson || activeExam){
if(!confirm('Cambiar de lengua interrumpirá tu actividad actual. ¿Continuar?')) return;
}
setCurrentLang(lang);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen('home');
};

const handleNavigate = (screen, params) => {
if(screen==='lesson' && params){
setActiveLesson(params);
setCurrentScreen('lesson');
} else if(screen==='exam' && params){
setActiveExam(params);
setCurrentScreen('exam');
} else {
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen(screen);
}
};

const handleProgressUpdate = (newProgress) => {
setProgress(newProgress);
};

const handleStartReview = (lessonId) => {
// Find the block for this lesson
for(const lang of Object.keys(CONTENT_DATA)){
for(const stage of CONTENT_DATA[lang].stages){
for(const block of stage.blocks){
const lesson = block.lessons.find(l=>l.id===lessonId);
if(lesson){
setActiveLesson({blockId:block.id,lessonId:lessonId});
setCurrentScreen('lesson');
return;
}
}
}
}
};

if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
if(currentScreen==='lesson' && activeLesson){
return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={()=>handleNavigate('path')}/>;
}
if(currentScreen==='exam' && activeExam){
return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={()=>handleNavigate('path')}/>;
}
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate}/>;
case 'review': return <ReviewCenter currentLang={currentLang} progress={progress} onStartReview={handleStartReview}/>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress}/>;
case 'achievements': return <AchievementsPage progress={progress}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings}/>;
case 'accessibility': return <AccessibilitySettings settings={settings} onUpdate={setSettings}/>;
case 'terms': return <TermsPage/>;
case 'privacy': return <PrivacyPage/>;
case 'help': return <HelpPage/>;
case 'blocks': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate}/>;
case 'exams': return (
<div className="animate-in">
<h1 style={{fontSize:28,fontWeight:800,marginBottom:24}}>Exámenes</h1>
<p style={{color:'var(--text2)',marginBottom:24}}>Los exámenes se desbloquean al completar todas las lecciones de un bloque. Ve a la Ruta de Aprendizaje para avanzar.</p>
<button onClick={()=>handleNavigate('path')} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>Ir a la Ruta de Aprendizaje</button>
</div>
);
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress}/>;
}
};

return (
<div style={{display:'flex',minHeight:'100vh'}}>
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} currentLang={currentLang} onLangChange={handleLangChange} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)}/>

<div style={{flex:1,marginLeft:0,transition:'var(--transition)',minHeight:'100vh'}}>
{/* Top bar */}
<header style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between',backdropFilter:'blur(10px)'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<button onClick={()=>setSidebarOpen(!sidebarOpen)} style={{background:'none',border:'none',color:'var(--text)',cursor:'pointer',fontSize:24,padding:8}} aria-label="Menú">☰</button>
<div className="desktop-only" style={{display:'flex',alignItems:'center',gap:8}}>
<LSMexaLogo size={28}/>
<span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span>
</div>
</div>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<LanguageSelector currentLang={currentLang} onSelect={handleLangChange} compact/>
</div>
</header>

<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>
{renderScreen()}
</main>

<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}>
<p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v1.0 MVP — Aplicación educativa en desarrollo</p>
<p style={{fontSize:11,color:'var(--text3)',marginTop:4}}>Los contenidos de demostración visual requieren validación con la comunidad sorda.</p>
</footer>
</div>
</div>
);
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>

<style>
@media(min-width:1024px){
.sidebar-desktop{transform:translateX(0)!important}
#root>div>div:last-child{margin-left:260px}
.sidebar-overlay{display:none!important}
.desktop-only{display:flex!important}
}
@media(max-width:1023px){
.sidebar-desktop{box-shadow:var(--shadow)}
.desktop-only{display:none!important}
}
@media(max-width:600px){
main{padding:16px!important}
header{padding:10px 16px!important}
}
</style>
</body>
</html>
```

