<path d="M32 28 L28 10 L42 22Z" fill="#6657C8"/>
<path d="M33 26 L30 14 L40 23Z" fill="#F28C28" opacity="0.7"/>
<path d="M68 28 L72 10 L58 22Z" fill="#6657C8"/>
<path d="M67 26 L70 14 L60 23Z" fill="#F28C28" opacity="0.7"/>
<circle cx="50" cy="45" r="16" fill="#F28C28" opacity="0.25"/>
{exp.eyes === 'open' && <>
<ellipse cx="42" cy="40" rx="5" ry="6" fill="white"/>
<ellipse cx="58" cy="40" rx="5" ry="6" fill="white"/>
<circle cx="43" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="59" cy="40" r="3" fill="#1e3a5f"/>
<circle cx="44" cy="38" r="1.5" fill="white"/>
<circle cx="60" cy="38" r="1.5" fill="white"/>
</>}
{exp.eyes === 'sparkle' && <>
<ellipse cx="42" cy="40" rx="5.5" ry="6.5" fill="white"/>
<ellipse cx="58" cy="40" rx="5.5" ry="6.5" fill="white"/>
<circle cx="43" cy="40" r="3.5" fill="#1e3a5f"/>
<circle cx="59" cy="40" r="3.5" fill="#1e3a5f"/>
<circle cx="44" cy="38" r="2" fill="white"/>
<circle cx="60" cy="38" r="2" fill="white"/>
