return (
<div key={a.id} style={{
background:'var(--surface)',borderRadius:'var(--radius)',padding:24,
border:'1px solid '+(isUnlocked?'var(--yellow)':'var(--surface3)'),
opacity:isUnlocked?1:0.5,transition:'var(--transition)'
}}>
<div style={{fontSize:40,marginBottom:12}}>{a.icon}</div>
