// Build full content structure
const buildContent = (lang) => {
const stages = STAGE_DATA[lang];
return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: stage.blocks.map((block, bi) => ({
id: `${lang}-s${si+1}-b${bi+1}`,
name: block.name,
lessons: block.lessons.map((lessonName, li) => ({
id: `${lang}-s${si+1}-b${bi+1}-l${li+1}`,
title: lessonName,
steps: buildLessonSteps(lang, si, bi, li, lessonName)
}))
}))
}))
};
};

const buildLessonSteps = (lang, stageIdx, blockIdx, lessonIdx, lessonName) => {
const handConfigs = ['A','B','C','D','E','F','5'];
const config = handConfigs[(stageIdx * 3 + blockIdx + lessonIdx) % handConfigs.length];
const isQuiz = lessonIdx === 14; // last lesson of block is review/quiz
const isIntro = lessonIdx === 0;

const steps = [];

// Step 1: Introduction
steps.push({
type:'intro',
text: isIntro 
? `Bienvenido a esta lección sobre "${lessonName}". ${LANGS[lang].supportLang === 'Español' ? 'Aprenderás los fundamentos de esta seña en ' + LANGS[lang].code + '.' : 'You will learn the fundamentals of this sign in ' + LANGS[lang].code + '.'}`
: `En esta lección aprenderás sobre "${lessonName}" en ${LANGS[lang].code}.`,
digi:'happy'
});

// Step 2: Concept explanation
steps.push({
type:'concept',
title:`Concepto: ${lessonName}`,
text:`${lessonName} es un elemento fundamental en ${LANGS[lang].code}. Cada seña tiene parámetros específicos: configuración manual, ubicación, movimiento y expresión facial.`,
digi:'thinking'
});

// Step 3: Visual demonstration
steps.push({
type:'demo',
title:`Demostración: ${lessonName}`,
text:`Observa la configuración manual y los detalles de la seña "${lessonName}". Presta atención a la forma de la mano, la ubicación y el movimiento.`,
digi:'encouraging',
signDetail:`Configuración: ${config}. Ubicación: frente al cuerpo. Movimiento: según el contexto. Expresión facial: neutra o según el significado.`,
handSign: config
});

// Step 4: Guided observation
steps.push({
type:'concept',
title:'Observa los detalles',
text:`Identifica: ¿Cuántos dedos están extendidos? ¿Hacia dónde apunta la palma? ¿La mano se mueve o está estática? Estas preguntas te ayudarán a dominar la seña.`,
digi:'encouraging'
});

// Step 5: Additional demonstration with different angle
steps.push({
type:'demo',
title:`Vista complementaria`,
text:`Observa nuevamente la configuración desde otra perspectiva. Nota cómo los dedos se relacionan entre sí y cómo el pulgar complementa la forma.`,
digi:'encouraging',
signDetail:`Detalle adicional: La tensión de los dedos debe ser natural, ni muy rígida ni muy relajada. La muñeca debe mantenerse alineada con el antebrazo.`,
handSign: handConfigs[(parseInt(config) + 1) % handConfigs.length] || 'B'
});

// Step 6: Practice question
steps.push({
type:'practice',
question:`¿Cuál configuración manual se utiliza principalmente en "${lessonName}"?`,
options:['Configuración A (puño cerrado)','Configuración B (mano abierta)','Configuración C (forma de C)','Configuración D (índice extendido)'],
correct: [0,1,2,3][lessonIdx % 4],
explanation:`La configuración correcta depende del contexto específico de "${lessonName}" en ${LANGS[lang].code}.`,
digi:'encouraging'
});

// Step 7: Contextual application
steps.push({
type:'concept',
title:'Uso en contexto',
text:`"${lessonName}" se utiliza en situaciones cotidianas de comunicación en ${LANGS[lang].code}. Practica usarla en diferentes contextos para dominarla completamente.`,
digi:'happy'
});

// Step 8: Recognition quiz
steps.push({
type:'quiz',
question:`En ${LANGS[lang].code}, "${lessonName}" se caracteriza principalmente por:`,
options:['Su configuración manual específica','Su ubicación en el cuerpo','Su movimiento particular','Todas las anteriores'],
correct: 3,
explanation:`Una seña en ${LANGS[lang].code} se define por la combinación de configuración, ubicación, movimiento y elementos no manuales.`,
digi:'happy'
});

// Step 9: Closing
steps.push({
type:'intro',
text:`¡Has completado la lección sobre "${lessonName}"! ${isQuiz ? 'Este es el repaso final del bloque. ¡Excelente trabajo!' : 'Continúa con la siguiente lección para avanzar en tu aprendizaje.'}`,
digi: isQuiz ? 'celebrating' : 'happy'
});

return steps;
};

