function LearningPath({currentLang,progress,onNavigate}) {
const lang = LANGS[currentLang];
const content = CONTENT_DATA[currentLang];

// Check if a lesson is unlocked
const isLessonUnlocked = (stageIdx, blockIdx, lessonIdx) => {
if(stageIdx === 0 && blockIdx === 0 && lessonIdx === 0) return true;
// Find previous lesson
const stages = content.stages;
let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx;
let prevLessonIdx = lessonIdx - 1;

if(prevLessonIdx < 0){
prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
prevLessonIdx = stages[prevStageIdx].blocks[prevBlockIdx].lessons.length - 1;
}

const prevLessonId = stages[prevStageIdx].blocks[prevBlockIdx].lessons[prevLessonIdx].id;
return progress.lessonProgress?.[prevLessonId]?.completed || false;
};

const isBlockUnlocked = (stageIdx, blockIdx) => {
if(stageIdx === 0 && blockIdx === 0) return true;
// Block is unlocked if all lessons of previous block are completed OR previous block exam is passed
const stages = content.stages;
let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
const prevBlockId = stages[prevStageIdx].blocks[prevBlockIdx].id;
return progress.blockProgress?.[prevBlockId]?.passed || false;
};

return (
<div className="animate-in">
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>Ruta de Aprendizaje</h1>
<p style={{color:'var(--text2)',marginBottom:24}}>{lang.flag} {lang.name} — {lang.supportLang} | Sistema de desbloqueo progresivo</p>

<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:16,marginBottom:24,border:'1px solid var(--violet)'}}>
<div style={{display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<span style={{fontSize:20}}>🔓</span>
<div style={{flex:1}}>
<div style={{fontSize:14,fontWeight:700,color:'var(--yellow)'}}>Sistema de desbloqueo progresivo</div>
<div style={{fontSize:13,color:'var(--text2)',marginTop:4}}>
• Completa una lección para desbloquear la siguiente<br/>
• Aprueba el examen de un bloque (80%) para desbloquear el siguiente bloque<br/>
• Tu progreso se refleja automáticamente en los logros
</div>
</div>
</div>
</div>

{content.stages.map((stage,si)=>{
const stageColor = STAGE_COLORS[si];
const stageLessons = stage.blocks.reduce((s,b)=>s+b.lessons.length,0);
const stageCompleted = stage.blocks.reduce((s,b)=>s+b.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length,0);
const stageProgress = stageLessons > 0 ? Math.round((stageCompleted/stageLessons)*100) : 0;
const stageUnlocked = si === 0 || progress.stageProgress?.[currentLang]?.[si] >= 100;

return (
<div key={stage.id} style={{marginBottom:32,opacity:stageUnlocked?1:0.5}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:16,flexWrap:'wrap'}}>
<div style={{width:44,height:44,borderRadius:'50%',background:stageColor,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,fontWeight:800,color:'white',flexShrink:0}}>{si+1}</div>
<div style={{flex:1,minWidth:200}}>
<div style={{fontSize:20,fontWeight:700}}>{stage.name}</div>
<div style={{fontSize:13,color:'var(--text2)'}}>Etapa {si+1} de {content.stages.length} • {stageCompleted}/{stageLessons} lecciones ({stageProgress}%)</div>
</div>
<div style={{width:200,height:10,background:'var(--surface3)',borderRadius:5}}>
<div style={{height:'100%',background:stageColor,borderRadius:5,width:stageProgress+'%',transition:'width 0.5s'}}/>
</div>
</div>

{stage.blocks.map((block,bi)=>{
const blockUnlocked = isBlockUnlocked(si, bi);
const blockPassed = progress.blockProgress?.[block.id]?.passed || false;
const blockLessonsCompleted = block.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
const blockProgress = Math.round((blockLessonsCompleted/block.lessons.length)*100);

return (
<div key={block.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:16,border:'1px solid '+(blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)'),opacity:blockUnlocked?1:0.6,transition:'var(--transition)'}}>
<div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:12,flexWrap:'wrap',gap:8}}>
<div style={{display:'flex',alignItems:'center',gap:10}}>
<div style={{width:32,height:32,borderRadius:'50%',background:blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>
{blockPassed?'✓':bi+1}
</div>
<div>
<div style={{fontSize:16,fontWeight:700}}>{block.name}</div>
<div style={{fontSize:12,color:'var(--text2)'}}>Bloque {bi+1} • {blockLessonsCompleted}/{block.lessons.length} lecciones • {blockProgress}%</div>
</div>
</div>
{blockPassed && <span style={{fontSize:12,color:'var(--success)',fontWeight:600,padding:'4px 12px',background:'#064e3b',borderRadius:12}}>✓ APROBADO</span>}
{!blockUnlocked && <span style={{fontSize:12,color:'var(--text3)',padding:'4px 12px',background:'var(--surface3)',borderRadius:12}}> BLOQUEADO</span>}
</div>

<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:16}}>
<div style={{height:'100%',background:blockPassed?'var(--success)':'var(--violet)',borderRadius:3,width:blockProgress+'%',transition:'width 0.5s'}}/>
</div>

<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:8}}>
{block.lessons.map((lesson,li)=>{
const lessonUnlocked = isLessonUnlocked(si, bi, li);
const lessonCompleted = progress.lessonProgress?.[lesson.id]?.completed || false;
const isNext = lessonUnlocked && !lessonCompleted;

return (
<div key={lesson.id} onClick={()=>lessonUnlocked&&onNavigate('lesson',{blockId:block.id,lessonId:lesson.id})} style={{
padding:'10px 12px',background:lessonCompleted?'#064e3b':isNext?'var(--violet)':'var(--surface2)',
border:'1px solid '+(lessonCompleted?'var(--success)':isNext?'var(--orange)':'var(--surface3)'),
borderRadius:'var(--radius-sm)',cursor:lessonUnlocked?'pointer':'default',
transition:'var(--transition)',opacity:lessonUnlocked?1:0.5,
display:'flex',alignItems:'center',gap:8
}}
onMouseOver={e=>lessonUnlocked&&!lessonCompleted&&(e.target.style.borderColor='var(--orange)')}
onMouseOut={e=>lessonUnlocked&&!lessonCompleted&&(e.target.style.borderColor=lessonCompleted?'var(--success)':'var(--violet)')}
>
<div style={{width:24,height:24,borderRadius:'50%',background:lessonCompleted?'var(--success)':lessonUnlocked?'var(--orange)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:'white',flexShrink:0}}>
{lessonCompleted?'✓':li+1}
</div>
<div style={{flex:1,minWidth:0}}>
<div style={{fontSize:12,fontWeight:600,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{lesson.title}</div>
