function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
const lang = LANGS[currentLang];
const [currentStepIdx,setCurrentStepIdx] = useState(0);
const [selectedAnswer,setSelectedAnswer] = useState(null);
const [showFeedback,setShowFeedback] = useState(false);
const [isCorrect,setIsCorrect] = useState(null);
const [lessonComplete,setLessonComplete] = useState(false);
const [showUnlock,setShowUnlock] = useState(false);

let block=null, lesson=null, lessonIdx=-1, blockIdx=-1, stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<content.stages[si].blocks.length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];
blockIdx=bi;stageIdx=si;
lesson=block.lessons.find(l=>l.id===lessonId);
lessonIdx=block.lessons.findIndex(l=>l.id===lessonId);
break;
}
}
if(block) break;
}
if(!lesson) return <div style={{padding:40,textAlign:'center'}}>Lección no encontrada.</div>;

const steps = lesson.steps;
const step = steps[currentStepIdx];
const totalSteps = steps.length;
const progress_pct = ((currentStepIdx)/totalSteps)*100;

const digiExpressions = {intro:'happy',concept:'thinking',demo:'encouraging',practice:'encouraging',quiz:'happy'};
const digiMessages = {
intro:'¡Vamos a aprender algo nuevo!',
concept:'Este concepto es importante. Presta atención.',
demo:'Observa cuidadosamente la demostración visual.',
practice:'¡Es tu turno! Piensa bien la respuesta.',
quiz:'Demuestra lo que has aprendido.'
};

const handleAnswer = (idx) => {
if(showFeedback) return;
setSelectedAnswer(idx);
const correct = step.correct === idx;
setIsCorrect(correct);
setShowFeedback(true);

const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
const prev = lp[lessonId] || {completed:false,correct:0,total:0};

if(correct){
lp[lessonId] = {completed:prev.completed,correct:prev.correct+1,total:prev.total+1};
} else {
lp[lessonId] = {completed:prev.completed,correct:prev.correct,total:prev.total+1};
const ri = [...(newProgress.reviewItems?.[currentLang]||[])];
if(!ri.includes(lessonId)) ri.push(lessonId);
newProgress.reviewItems = {...(newProgress.reviewItems||{}),[currentLang]:ri};
}
newProgress.lessonProgress = lp;
onComplete(newProgress);
};

const nextStep = () => {
if(currentStepIdx < totalSteps-1){
setCurrentStepIdx(currentStepIdx+1);
setSelectedAnswer(null);
setShowFeedback(false);
setIsCorrect(null);
} else {
// Complete lesson
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
const prev = lp[lessonId] || {completed:false,correct:0,total:0};
lp[lessonId] = {...prev, completed:true};
newProgress.lessonProgress = lp;

// Update course progress
const totalLessons = content.stages.reduce((s,st)=>s+st.blocks.reduce((bs,b)=>bs+b.lessons.length,0),0);
const completedLessons = Object.values(lp).filter(v=>v.completed).length;
const cp = {...(newProgress.courseProgress||{})};
cp[currentLang] = Math.round((completedLessons/totalLessons)*100);
newProgress.courseProgress = cp;

// Update today lessons and streak
const today = new Date().toDateString();
if(newProgress.lastActiveDate !== today){
newProgress.todayLessons = 1;
newProgress.lastActiveDate = today;
const yesterday = new Date(Date.now()-86400000).toDateString();
if(newProgress.lastActiveDateBefore === yesterday || !newProgress.lastActiveDateBefore){
newProgress.streak = (newProgress.streak||0) + 1;
} else {
newProgress.streak = 1;
}
newProgress.lastActiveDateBefore = today;
newProgress.activeDays = (newProgress.activeDays||0) + 1;
} else {
newProgress.todayLessons = (newProgress.todayLessons||0) + 1;
}

// Early bird / night owl
const hour = new Date().getHours();
if(hour < 8) newProgress.earlyLessons = (newProgress.earlyLessons||0) + 1;
if(hour >= 22) newProgress.nightLessons = (newProgress.nightLessons||0) + 1;

// Update stage progress
const stage = content.stages[stageIdx];
const stageLessons = stage.blocks.reduce((s,b)=>s+b.lessons.length,0);
const stageCompleted = stage.blocks.reduce((s,b)=>s+b.lessons.filter(l=>lp[l.id]?.completed).length,0);
const sp = {...(newProgress.stageProgress||{})};
sp[currentLang] = {...(sp[currentLang]||{})};
sp[currentLang][stageIdx+1] = Math.round((stageCompleted/stageLessons)*100);
newProgress.stageProgress = sp;

onComplete(newProgress);
setLessonComplete(true);

// Check if next lesson exists and show unlock animation
let nextLessonExists = false;
if(lessonIdx < block.lessons.length - 1){
nextLessonExists = true;
} else if(blockIdx < content.stages[stageIdx].blocks.length - 1){
nextLessonExists = true;
}
if(nextLessonExists){
setShowUnlock(true);
setTimeout(()=>setShowUnlock(false),3000);
}
}
};

if(lessonComplete){
const nextLessonId = lessonIdx < block.lessons.length - 1 
? block.lessons[lessonIdx + 1].id 
: (blockIdx < content.stages[stageIdx].blocks.length - 1 
? content.stages[stageIdx].blocks[blockIdx + 1].lessons[0].id 
: null);

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<DigiGuide message={`¡Excelente! Has completado "${lesson.title}". ${nextLessonId?'La siguiente lección ha sido desbloqueada.':'¡Has completado todas las lecciones de este bloque!'}`} expression="celebrating"/>

{showUnlock && nextLessonId && (
<div className="unlock-anim" style={{background:'linear-gradient(135deg,var(--orange),var(--yellow))',borderRadius:'var(--radius)',padding:20,marginTop:20,textAlign:'center',color:'var(--black)'}}>
<div style={{fontSize:40,marginBottom:8}}>🔓</div>
<div style={{fontSize:20,fontWeight:800}}>¡NUEVA LECCIÓN DESBLOQUEADA!</div>
<div style={{fontSize:14,marginTop:8}}>Continúa tu progreso en {lang.code}</div>
</div>
)}

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:48,marginBottom:12}}>🎉</div>
<h2 style={{fontSize:24,fontWeight:700,marginBottom:8}}>¡Lección Completada!</h2>
<p style={{color:'var(--text2)'}}>{lesson.title} — {lang.code}</p>
<p style={{color:'var(--text3)',fontSize:13,marginTop:8}}>Lección {lessonIdx+1} de {block.lessons.length} en este bloque</p>
</div>

<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
{nextLessonId && (
<button onClick={()=>{onBack();setTimeout(()=>onNavigate('lesson',{blockId:blockId,lessonId:nextLessonId}),100)}} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}
onMouseOver={e=>e.target.style.background='#e07b1a'} onMouseOut={e=>e.target.style.background='var(--orange)'}>
▶ Siguiente lección
</button>
)}
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>
Volver a la ruta
</button>
</div>
</div>
);
}

const HandSignComponent = step.handSign ? (() => <HandSVG type={step.handSign} size={200}/>)() : null;

return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<button onClick={onBack} style={{background:'var(--surface2)',border:'1px solid var(--surface3)',color:'var(--text2)',padding:'8px 16px',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,marginBottom:20}}>← Volver</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:16,marginBottom:16,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<div style={{width:36,height:36,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>
{lessonIdx+1}
</div>
<div style={{flex:1,minWidth:200}}>
<div style={{fontSize:12,color:'var(--text2)'}}>{block.name}</div>
<div style={{fontSize:16,fontWeight:700}}>{lesson.title}</div>
</div>
<div style={{fontSize:12,color:'var(--text3)'}}>Paso {currentStepIdx+1}/{totalSteps}</div>
</div>

<div style={{marginBottom:20}}>
<div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}>
<span style={{fontSize:13,color:'var(--text2)'}}>Progreso de lección</span>
<span style={{fontSize:13,color:'var(--text2)'}}>{Math.round(progress_pct)}%</span>
</div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3}}>
<div style={{height:'100%',background:'var(--violet)',borderRadius:3,width:progress_pct+'%',transition:'width 0.3s'}}/>
</div>
</div>

<DigiGuide message={digiMessages[step.type]||''} expression={digiExpressions[step.type]||'happy'}/>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
{step.type==='intro' && <p style={{fontSize:16,lineHeight:1.8,color:'var(--text)'}}>{step.text}</p>}

{step.type==='concept' && (
<div>
<h3 style={{fontSize:18,fontWeight:700,color:'var(--orange)',marginBottom:12}}>{step.title}</h3>
<p style={{fontSize:15,lineHeight:1.7,color:'var(--text)'}}>{step.text}</p>
</div>
)}

{step.type==='demo' && (
<div>
<h3 style={{fontSize:18,fontWeight:700,color:'var(--orange)',marginBottom:12}}>{step.title}</h3>
{HandSignComponent && (
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:24,textAlign:'center',marginBottom:16,border:'2px solid var(--surface3)'}}>
{HandSignComponent}
<p style={{fontSize:12,color:'var(--text3)',marginTop:12,fontStyle:'italic'}}>
Ilustración anatómica detallada — Recurso educativo original de LSMexa
</p>
</div>
)}
<p style={{fontSize:15,lineHeight:1.7,color:'var(--text)',marginBottom:12}}>{step.text}</p>
{step.signDetail && (
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:16,borderLeft:'3px solid var(--violet)'}}>
<div style={{fontSize:13,fontWeight:700,color:'var(--violet)',marginBottom:6}}>📋 Detalles de la seña:</div>
<p style={{fontSize:14,color:'var(--text2)',lineHeight:1.6}}>{step.signDetail}</p>
</div>
)}
</div>
)}

{(step.type==='practice'||step.type==='quiz') && (
<div>
<h3 style={{fontSize:17,fontWeight:700,marginBottom:16}}>{step.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{step.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showFeedback){
if(i===step.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}
else if(i===selectedAnswer&&i!==step.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}
} else if(selectedAnswer===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (
<button key={i} onClick={()=>handleAnswer(i)} disabled={showFeedback} style={{
padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',
color:color,cursor:showFeedback?'default':'pointer',fontSize:15,textAlign:'left',transition:'var(--transition)',fontWeight:selectedAnswer===i?600:400
}}
onMouseOver={e=>!showFeedback&&(e.target.style.borderColor='var(--violet)')}
onMouseOut={e=>!showFeedback&&(e.target.style.borderColor=selectedAnswer===i?'var(--violet)':'var(--surface3)')}
>
<span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}
</button>
);
})}
</div>

{showFeedback && (
<div style={{marginTop:20,padding:16,borderRadius:'var(--radius-sm)',background:isCorrect?'#064e3b':'#7f1d1d',border:'1px solid '+(isCorrect?'var(--success)':'var(--error)')}}>
<div style={{fontSize:16,fontWeight:700,color:isCorrect?'var(--success)':'var(--error)',marginBottom:6}}>
{isCorrect?'✓ ¡Correcto!':'✗ Incorrecto'}
</div>
<p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{step.explanation}</p>
</div>
)}
</div>
)}
</div>

<div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}>
{showFeedback ? (
<button onClick={nextStep} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
{currentStepIdx<totalSteps-1?'Siguiente →':'Finalizar lección'}
</button>
) : (step.type!=='practice'&&step.type!=='quiz' ? (
<button onClick={nextStep} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}
onMouseOver={e=>e.target.style.background='#7c6fd4'} onMouseOut={e=>e.target.style.background='var(--violet)'}>
Continuar →
</button>
) : null)}
</div>
</div>
);
