function ProgressDashboard({currentLang,progress}) {
const lang = LANGS[currentLang];
const content = CONTENT_DATA[currentLang];
const totalLessons = content.stages.reduce((s,st)=>s+st.blocks.reduce((bs,b)=>bs+b.lessons.length,0),0);
const completedLessons = Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;
const courseProgress = totalLessons > 0 ? Math.round((completedLessons/totalLessons)*100) : 0;
const blocksPassed = Object.values(progress.blockProgress||{}).filter(v=>v.passed).length;

return (
<div className="animate-in">
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>Progreso</h1>
<p style={{color:'var(--text2)',marginBottom:24}}>{lang.flag} {lang.name}</p>

<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{courseProgress}%</div>
<div style={{fontSize:14,color:'var(--text2)',marginTop:4}}>Progreso general</div>
<div style={{fontSize:12,color:'var(--text3)'}}>{completedLessons}/{totalLessons} lecciones</div>
</div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{completedLessons}</div>
<div style={{fontSize:14,color:'var(--text2)',marginTop:4}}>Lecciones completadas</div>
</div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:40,fontWeight:800,color:'var(--violet)'}}>{blocksPassed}</div>
<div style={{fontSize:14,color:'var(--text2)',marginTop:4}}>Bloques aprobados</div>
</div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div>
<div style={{fontSize:14,color:'var(--text2)',marginTop:4}}>Días de racha</div>
</div>
</div>

<div>
<h2 style={{fontSize:20,fontWeight:700,marginBottom:16}}>Desglose por etapa</h2>
{content.stages.map((stage,si)=>{
const stageLessons = stage.blocks.reduce((s,b)=>s+b.lessons.length,0);
const stageCompleted = stage.blocks.reduce((s,b)=>s+b.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length,0);
const sp = stageLessons > 0 ? Math.round((stageCompleted/stageLessons)*100) : 0;
return (
<div key={stage.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:12,border:'1px solid var(--surface3)'}}>
<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8,flexWrap:'wrap',gap:8}}>
<span style={{fontSize:16,fontWeight:600}}>Etapa {si+1}: {stage.name}</span>
<span style={{fontSize:14,color:'var(--text2)'}}>{stageCompleted}/{stageLessons} ({sp}%)</span>
</div>
<div style={{height:8,background:'var(--surface3)',borderRadius:4}}>
<div style={{height:'100%',background:STAGE_COLORS[si],borderRadius:4,width:sp+'%',transition:'width 0.5s'}}/>
</div>
<div style={{marginTop:8,display:'flex',flexWrap:'wrap',gap:4}}>
{stage.blocks.map((block,bi)=>{
const bl = block.lessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
const bp = Math.round((bl/block.lessons.length)*100);
const passed = progress.blockProgress?.[block.id]?.passed;
return (
<div key={block.id} style={{flex:'1 1 200px',padding:'8px 12px',background:'var(--surface2)',borderRadius:'var(--radius-sm)',border:'1px solid '+(passed?'var(--success)':'var(--surface3)')}}>
<div style={{display:'flex',justifyContent:'space-between',fontSize:12,marginBottom:4}}>
<span style={{fontWeight:600}}>{block.name}</span>
<span style={{color:passed?'var(--success)':'var(--text2)'}}>{bp}%{passed?' ✓':''}</span>
</div>
<div style={{height:4,background:'var(--surface3)',borderRadius:2}}>
<div style={{height:'100%',background:passed?'var(--success)':'var(--violet)',borderRadius:2,width:bp+'%'}}/>
</div>
</div>
);
})}
</div>
</div>
);
})}
</div>
</div>
);
}

