// ============ BUILD CONTENT WITH 9 QUESTIONS PER LESSON ============
const buildContent = (lang) => {
const stages = STAGE_DATA[lang];
return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: stage.blocks.map((block, bi) => ({
id: `${lang}-s${si+1}-b${bi+1}`,
name: block.name,
lessons: block.lessons.map((lessonName, li) => ({
id: `${lang}-s${si+1}-b${bi+1}-l${li+1}`,
title: lessonName,
questions: buildLessonQuestions(lang, si, bi, li, lessonName)
}))
}))
}))
};
};

const buildLessonQuestions = (lang, stageIdx, blockIdx, lessonIdx, lessonName) => {
const handConfigs = ['A','B','C','D','E','F','5'];
const config = handConfigs[(stageIdx * 3 + blockIdx + lessonIdx) % handConfigs.length];

// Generate exactly 9 questions per lesson
const questions = [];
const questionTemplates = [
{
q: `¿Cuál es la configuración manual principal utilizada en "${lessonName}"?`,
opts: ['Configuración A (puño cerrado)','Configuración B (mano abierta)','Configuración C (forma de C)','Configuración D (índice extendido)'],
correct: [0,1,2,3][lessonIdx % 4],
exp: `La configuración correcta depende del contexto específico de "${lessonName}" en ${LANGS[lang].code}.`
},
{
q: `En ${LANGS[lang].code}, "${lessonName}" se caracteriza principalmente por:`,
opts: ['Su configuración manual específica','Su ubicación en el cuerpo','Su movimiento particular','La combinación de todos los parámetros'],
correct: 3,
exp: `Una seña en ${LANGS[lang].code} se define por la combinación de configuración, ubicación, movimiento y elementos no manuales.`
},
{
q: `¿Qué parámetro de la seña "${lessonName}" describe la forma de la mano?`,
opts: ['Ubicación','Configuración manual','Movimiento','Expresión facial'],
correct: 1,
exp: `La configuración manual describe la forma que adopta la mano al realizar la seña.`
},
{
q: `¿Dónde se ubica generalmente la seña "${lessonName}"?`,
opts: ['Frente al cuerpo','En la cabeza','En el pecho','Depende del contexto específico'],
correct: 3,
exp: `La ubicación de "${lessonName}" varía según el contexto comunicativo en ${LANGS[lang].code}.`
},
{
q: `¿Qué tipo de movimiento tiene la seña "${lessonName}"?`,
opts: ['Estático (sin movimiento)','Movimiento rectilíneo','Movimiento circular','Varía según el contexto'],
correct: 3,
exp: `El movimiento de "${lessonName}" puede variar según el contexto y la intención comunicativa.`
},
{
q: `¿Cuál expresión facial acompaña comúnmente a "${lessonName}"?`,
opts: ['Neutra','Sonrisa','Cejas levantadas','Depende del contexto emocional'],
correct: 3,
exp: `La expresión facial en "${lessonName}" se adapta al contexto emocional de la comunicación.`
},
{
q: `En ${LANGS[lang].code}, ¿"${lessonName}" utiliza una o dos manos?`,
opts: ['Siempre una mano','Siempre dos manos','Puede usar una o dos según el contexto','No utiliza las manos'],
correct: 2,
exp: `Muchas señas en ${LANGS[lang].code} pueden realizarse con una o dos manos según el contexto.`
},
{
q: `¿Cuál es el propósito comunicativo principal de "${lessonName}"?`,
opts: ['Saludar','Despedirse','Expresar un concepto específico','Hacer una pregunta'],
correct: 2,
exp: `"${lessonName}" expresa un concepto específico dentro del vocabulario de ${LANGS[lang].code}.`
},
{
q: `¿Qué elemento NO es parte de los parámetros de "${lessonName}"?`,
opts: ['Configuración manual','Sonido vocal','Ubicación','Movimiento'],
correct: 1,
exp: `Las lenguas de señas son visuales-gestuales. El sonido vocal no es un parámetro de las señas.`
}
];

// Use the templates, cycling through them
for(let i = 0; i < 9; i++){
const template = questionTemplates[i % questionTemplates.length];
questions.push({
id: `${lessonName}-q${i+1}`,
question: template.q,
options: template.opts,
correct: template.correct,
explanation: template.exp,
handSign: i % 3 === 0 ? config : null
});
}

return questions;
};

const CONTENT_DATA = {
lsm: buildContent('lsm'),
lsf: buildContent('lsf'),
asl: buildContent('asl'),
