const completedLessons = Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;
const langProgress = totalLessons > 0 ? Math.round((completedLessons/totalLessons)*100) : 0;

let digiMsg = {text:`¡Hola ${user?.name||'amigo'}! Soy Digi. Necesitas 5/9 correctas para avanzar en cada lección.`,expr:'happy'};
if(langProgress>=80) digiMsg={text:'¡Increíble progreso! Ya dominas la mayor parte de '+lang.code+'.',expr:'celebrating'};
else if(langProgress>=40) digiMsg={text:'¡Excelente avance! Más de la mitad completada en '+lang.code+'.',expr:'excited'};
