// Build content with unique lessons
const buildContent = (lang) => {
const stages = STAGE_DATA[lang];
return {
stages: stages.map((stage, si) => ({
id: si + 1,
name: stage.name,
blocks: stage.blocks.map((block, bi) => ({
id: `${lang}-s${si+1}-b${bi+1}`,
name: block.name,
lessons: block.lessons.map((lessonName, li) => {
const lessonData = LESSON_DATABASE[lessonName] || {
title: lessonName,
introduction: `Esta lección te enseñará sobre "${lessonName}" en ${LANGS[lang].code}. Es un elemento único e importante del vocabulario.`,
anatomy: {
handshape: 'Configuración manual específica',
thumb: 'Posición del pulgar',
palm: 'Orientación de la palma',
orientation: 'Orientación general',
location: 'Ubicación específica',
movement: 'Tipo de movimiento',
facialExpression: 'Expresión facial',
repetition: 'Número de repeticiones'
},
stepByStep: [
'Observa la configuración manual',
'Identifica la posición de cada dedo',
'Nota la orientación de la palma',
'Identifica la ubicación',
'Observa el movimiento',
'Presta atención a la expresión facial',
'Practica lentamente',
'Repite hasta dominarla'
],
commonMistakes: [
'Configuración incorrecta',
'Orientación incorrecta',
'Ubicación incorrecta',
'Movimiento incorrecto'
],
context: `"${lessonName}" se usa en contextos específicos de comunicación en ${LANGS[lang].code}.`,
culturalNote: 'Consulta con la comunidad sorda local para variaciones regionales.',
visualCue: 'Observa la ilustración y practica frente a un espejo.'
};

return {
id: `${lang}-s${si+1}-b${bi+1}-l${li+1}`,
title: lessonName,
content: {
teaching: lessonData,
questions: generateUniqueQuestions(lessonName, lessonData, lang)
}
};
})
}))
}))
};
};

const generateUniqueQuestions = (lessonName, lessonData, lang) => {
return [
{
question: `¿Cuál es la configuración manual principal de "${lessonName}"?`,
options: ['Configuración A (puño cerrado)','Configuración B (mano abierta)','Configuración 5 (cinco dedos)',lessonData.anatomy.handshape.includes('B')?'Configuración B (mano abierta, dedos juntos, pulgar cruzado)':'Configuración específica enseñada'],
correct: lessonData.anatomy.handshape.includes('B')?3:3,
explanation: `La configuración correcta es: ${lessonData.anatomy.handshape}, como se explicó en la clase.`
},
{
question: `¿Dónde se ubica la mano al realizar "${lessonName}"?`,
options: ['En el pecho','En la cabeza','En el abdomen',lessonData.anatomy.location],
correct: 3,
explanation: `La ubicación correcta es: ${lessonData.anatomy.location}, como se mostró en la clase.`
},
{
question: `¿Qué tipo de movimiento tiene "${lessonName}"?`,
options: ['Sin movimiento','Movimiento circular','Movimiento lateral',lessonData.anatomy.movement],
correct: 3,
explanation: `El movimiento correcto es: ${lessonData.anatomy.movement}.`
},
{
question: `¿Cuál es un error común al realizar "${lessonName}"?`,
options: ['Hacerlo muy rápido',lessonData.commonMistakes[0],'No mirar a la persona','Todas las anteriores'],
correct: 1,
explanation: `Un error común es: ${lessonData.commonMistakes[0]}, como se mencionó en la clase.`
},
{
question: `¿Qué expresión facial acompaña a "${lessonName}"?`,
options: ['Neutra','Enojada','Triste',lessonData.anatomy.facialExpression],
correct: 3,
explanation: `La expresión facial correcta es: ${lessonData.anatomy.facialExpression}.`
},
{
question: `¿En qué contexto se usa "${lessonName}"?`,
options: ['Solo en situaciones formales','Solo con familia',lessonData.context.split('.')[0],'Solo en la escuela'],
correct: 2,
explanation: lessonData.context
},
{
question: `¿Cuántas veces se repite el movimiento de "${lessonName}"?`,
options: ['Una vez','Dos veces','Tres veces',lessonData.anatomy.repetition],
correct: 3,
explanation: `La repetición correcta es: ${lessonData.anatomy.repetition}.`
},
{
question: `¿Qué nota cultural es importante sobre "${lessonName}"?`,
options: ['No tiene importancia cultural','Solo se usa en México',lessonData.culturalNote.split('.')[0],'Es igual en todas las lenguas de señas'],
correct: 2,
explanation: lessonData.culturalNote
},
{
question: `Basándote en la clase, ¿cuál es el primer paso para realizar "${lessonName}"?`,
options: ['Mover la mano rápidamente',lessonData.stepByStep[0],'Gritar el nombre','Cerrar los ojos'],
correct: 1,
explanation: `El primer paso es: ${lessonData.stepByStep[0]}, como se explicó en la clase.`
}
];
