{mode==='register'?'¡Bienvenido a LSMexa!':'¡Hola de nuevo!'}
</h2>
<p style={{color:'var(--text2)',fontSize:14,marginTop:4}}>
{mode==='register'?'Crea tu cuenta':'Inicia sesión'}
</p>
</div>

{success && <div style={{background:'#064e3b',color:'#4ade80',padding:12,borderRadius:'var(--radius-sm)',marginBottom:16,fontSize:14,textAlign:'center'}}>{success}</div>}

<div style={{display:'flex',gap:8,marginBottom:24}}>
<button onClick={()=>{setMode('register');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='register'?'var(--violet)':'var(--surface2)',color:mode==='register'?'white':'var(--text2)'}}>Registro</button>
<button onClick={()=>{setMode('login');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='login'?'var(--violet)':'var(--surface2)',color:mode==='login'?'white':'var(--text2)'}}>Iniciar Sesión</button>
</div>

{mode==='register' && (
<div style={{marginBottom:16}}>
<label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label>
<input value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.name?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>
{errors.name && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.name}</p>}
