<input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="tu@correo.com" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.email?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>
{errors.email && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.email}</p>}
</div>

<div style={{marginBottom:24}}>
<label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Contraseña</label>
<input value={password} onChange={e=>setPassword(e.target.value)} type={showPass?'text':'password'} placeholder="Mínimo 8 caracteres" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.password?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>
{errors.password && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.password}</p>}
