lessons: block.lessons.map((lessonName, li) => {
const lessonData = getLessonData(lessonName);
const handSignMap = {'Letra A':'A','Letra B':'B','Letra C':'C','Letra D':'D','Letra E':'E','Letra F':'F','Letra G':'G','Letra H':'H','Letra I':'I','Letra J':'J','Letra K':'K','Letra L':'L','Letra M':'M','Letra N':'N','Letra O':'O','Letra P':'P','Letra Q':'Q','Letra R':'R','Letra S':'S','Letra T':'T','Letra U':'U','Letra V':'V','Letra W':'W','Letra X':'X','Letra Y':'Y','Letra Z':'Z','Numero 1':'NUM1','Numero 2':'NUM2','Numero 3':'NUM3','Numero 5':'NUM5','Leccion 1 - HOLA':'HELLO','Leccion 4 - GRACIAS':'THANKS','MAMA':'MOM','PAPA':'DAD','SI':'YES','NO':'NO'};
return {id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),title: lessonName,handSign: handSignMap[lessonName] || null,content: {teaching: lessonData,questions: getHardQuestions(lessonName, lessonData)}};
