function ProgressDashboard({currentLang,progress, onBack}) {
const lang = LANGS[currentLang];
const content = CONTENT_DATA[currentLang];
const totalLessons = content.stages.reduce((s,st)=>s+st.blocks.reduce((bs,b)=>bs+b.lessons.length,0),0);
const completedLessons = Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;
const courseProgress = totalLessons > 0 ? Math.round((completedLessons/totalLessons)*100) : 0;
return (<GenericPage title="Progreso" subtitle={lang.flag + ' ' + lang.name} onBack={onBack}>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{courseProgress}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{completedLessons}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div>
</div>
</GenericPage>);
}

function HistoryPage({currentLang,progress, onBack}) {
const lang = LANGS[currentLang];
const content = CONTENT_DATA[currentLang];
const examResults = Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));
const lessonProg = Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));
const getLessonTitle = (id) => {for(const stage of content.stages){for(const block of stage.blocks){const lesson = block.lessons.find(l=>l.id===id);if(lesson) return lesson.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag + ' ' + lang.code} onBack={onBack}>
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Examenes ({examResults.length})</h2>
{examResults.length===0 ? <p style={{color:'var(--text2)',marginBottom:24}}>Sin examenes.</p> : (<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{examResults.map(([blockId,result])=>(<div key={blockId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{blockId}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(result.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:result.passed?'var(--success)':'var(--error)'}}>{result.score}%</div><div style={{fontSize:12,color:result.passed?'var(--success)':'var(--error)'}}>{result.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lessonProg.filter(([_,v])=>v.completed).length})</h2>
{lessonProg.length===0 ? <p style={{color:'var(--text2)'}}>Sin lecciones.</p> : (<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lessonProg.map(([lessonId,lp])=>(<div key={lessonId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{getLessonTitle(lessonId)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}
</GenericPage>);
}

function ProfilePage({user,progress,onUpdate, onBack}) {
const [name,setName] = useState(user?.name||'');
const [saved,setSaved] = useState(false);
const handleSave = () => {const users = getStorage('users',{});if(users[user.email]){users[user.email].name = name;setStorage('users',users);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}>
<div style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}><div style={{width:64,height:64,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:28,fontWeight:700,color:'white'}}>{(name||'U')[0].toUpperCase()}</div><div><div style={{fontSize:20,fontWeight:700}}>{name}</div><div style={{fontSize:14,color:'var(--text2)'}}>{user?.email}</div></div></div>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={user?.email||''} disabled style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text3)',fontSize:15}}/></div>
<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button>
</div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',maxWidth:500}}>
<h3 style={{fontSize:16,fontWeight:700,marginBottom:12}}>Resumen</h3>
<div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}>
<div><div style={{fontSize:12,color:'var(--text2)'}}>Lecciones</div><div style={{fontSize:20,fontWeight:700}}>{Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length}</div></div>
<div><div style={{fontSize:12,color:'var(--text2)'}}>Bloques</div><div style={{fontSize:20,fontWeight:700}}>{Object.values(progress.blockProgress||{}).filter(v=>v.passed).length}</div></div>
<div><div style={{fontSize:12,color:'var(--text2)'}}>Logros</div><div style={{fontSize:20,fontWeight:700}}>{(progress.achievements||[]).length}</div></div>
<div><div style={{fontSize:12,color:'var(--text2)'}}>Racha</div><div style={{fontSize:20,fontWeight:700}}>{progress.streak||0} dias</div></div>
</div>
</div>
</GenericPage>);
}

function SettingsPage({settings,onUpdate, onBack}) {
const [dailyGoal,setDailyGoal] = useState(settings.dailyGoal||3);
const [saved,setSaved] = useState(false);
const handleSave = () => {onUpdate({...settings,dailyGoal});setSaved(true);setTimeout(()=>setSaved(false),2000);};
return (<GenericPage title="Configuracion" onBack={onBack}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}>
<h3 style={{fontSize:18,fontWeight:700,marginBottom:16}}>Preferencias</h3>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Objetivo diario</label><input type="number" min="1" max="20" value={dailyGoal} onChange={e=>setDailyGoal(parseInt(e.target.value)||1)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div>
<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button>
</div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',maxWidth:500}}>
<h3 style={{fontSize:16,fontWeight:700,marginBottom:12}}>Almacenamiento</h3>
<p style={{fontSize:14,color:'var(--text2)',marginBottom:12}}>Datos locales.</p>
<button onClick={()=>{if(confirm('Borrar datos?')){Object.keys(localStorage).filter(k=>k.startsWith('lsmexa_')).forEach(k=>localStorage.removeItem(k));location.reload();}}} style={{padding:'10px 20px',background:'transparent',border:'1px solid var(--error)',borderRadius:'var(--radius-sm)',color:'var(--error)',cursor:'pointer',fontSize:14}}>Borrar datos</button>
</div>
</GenericPage>);
}

function HelpPage({onBack}) {
return (<GenericPage title="Ayuda" onBack={onBack}>
<div style={{display:'flex',flexDirection:'column',gap:16}}>
{[{q:'Como funcionan las preguntas?',a:'Las preguntas son DESAFIANTES. No puedes adivinar la respuesta solo viendo las opciones. Debes leer cuidadosamente la clase completa antes de responder.'},{q:'De donde salen los datos curiosos?',a:'Son datos REALES y VERIFICADOS sobre lenguas de senas, historia de la educacion de sordos, cultura sorda, y reconocimientos oficiales. Cada dato incluye su fuente.'},{q:'Cada leccion es diferente?',a:'Si! Cada leccion tiene contenido completamente unico con explicaciones extensas y detalladas.'},{q:'Que pasa si repruebo?',a:'Vuelves a la clase completa. Debes releer con atencion antes de reintentar.'},{q:'Como se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9 cada una) y aprueba el examen (80%).'}].map((item,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{item.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{item.a}</p></div>))}
</div>
</GenericPage>);
}

function App() {
const [user,setUser] = useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang] = useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen] = useState('home');
const [sidebarOpen,setSidebarOpen] = useState(false);
const [progress,setProgress] = useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0}));
const [settings,setSettings] = useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson] = useState(null);
const [activeExam,setActiveExam] = useState(null);
const [newAchievement,setNewAchievement] = useState(null);
const [previousScreen,setPreviousScreen] = useState('home');

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
let changed = false;
ACHIEVEMENT_DEFS.forEach(a=>{if(!newAchievements.includes(a.id) && a.condition(progress)){newAchievements.push(a.id);changed = true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});
if(changed) setProgress(p=>({...p,achievements:newAchievements}));
},[progress]);

const handleAuth = (userData) => {setUser(userData);setStorage('currentUser',userData);setCurrentScreen('home');};
const handleLogout = () => {setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};
const handleLangChange = (lang) => {if(activeLesson || activeExam){if(!confirm('Cambiar lengua?')) return;}setCurrentLang(lang);setActiveLesson(null);setActiveExam(null);setCurrentScreen('home');};

const handleNavigate = (screen, params) => {
if(screen==='lesson' && params){
setPreviousScreen(currentScreen);
setActiveLesson(params);
setCurrentScreen('lesson');
window.scrollTo(0,0);
} else if(screen==='exam' && params){
setPreviousScreen(currentScreen);
setActiveExam(params);
setCurrentScreen('exam');
window.scrollTo(0,0);
} else {
setPreviousScreen(currentScreen);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen(screen);
window.scrollTo(0,0);
}
setSidebarOpen(false);
};

const handleGoBack = () => {
if(currentScreen === 'lesson' || currentScreen === 'exam'){
handleNavigate(previousScreen || 'home');
} else if(currentScreen !== 'home'){
handleNavigate('home');
}
};

const handleProgressUpdate = (newProgress) => {setProgress(newProgress);};
const handleStartReview = (lessonId) => {for(const lang of Object.keys(CONTENT_DATA)){for(const stage of CONTENT_DATA[lang].stages){for(const block of stage.blocks){const lesson = block.lessons.find(l=>l.id===lessonId);if(lesson){setActiveLesson({blockId:block.id,lessonId:lessonId});setCurrentScreen('lesson');return;}}}}};

if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
if(currentScreen==='lesson' && activeLesson) return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
if(currentScreen==='exam' && activeExam) return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate} onBack={handleGoBack}/>;
case 'review': return <GenericPage title="Repaso" subtitle="Centro de repaso" onBack={handleGoBack}><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></GenericPage>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'achievements': return <AchievementsPage progress={progress} onBack={handleGoBack}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser} onBack={handleGoBack}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings} onBack={handleGoBack}/>;
case 'help': return <HelpPage onBack={handleGoBack}/>;
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
}
};

return (
<div style={{display:'flex',minHeight:'100vh'}}>
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)}/>
<div style={{flex:1,marginLeft:0,transition:'var(--transition)',minHeight:'100vh'}}>
<header style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<button onClick={()=>setSidebarOpen(!sidebarOpen)} style={{background:'none',border:'none',color:'var(--text)',cursor:'pointer',fontSize:24,padding:8}} aria-label="Abrir menu">☰</button>
<div style={{display:'flex',alignItems:'center',gap:8}}><LSMexaLogo size={28}/><span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span></div>
</div>
<LanguageSelector currentLang={currentLang} onSelect={handleLangChange} compact/>
</header>
<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>{renderScreen()}</main>
<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}><p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v9.0 - Navegacion mejorada con botones de regreso</p></footer>
</div>
{newAchievement && (<div style={{position:'fixed',bottom:20,right:20,zIndex:1000,background:'linear-gradient(135deg,var(--yellow),var(--orange))',borderRadius:'var(--radius)',padding:20,boxShadow:'0 10px 40px rgba(0,0,0,0.5)',animation:'unlock 0.5s ease-out',maxWidth:320,color:'var(--black)'}}><div style={{display:'flex',alignItems:'center',gap:12}}><div style={{fontSize:40}}>{newAchievement.icon}</div><div><div style={{fontSize:12,fontWeight:700,opacity:0.8}}>LOGRO!</div><div style={{fontSize:16,fontWeight:800}}>{newAchievement.name}</div><div style={{fontSize:12,marginTop:4}}>{newAchievement.desc}</div></div></div></div>)}
</div>
);
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>
<style>
@media(min-width:1024px){.sidebar-desktop{transform:translateX(0)!important}#root>div>div:last-child{margin-left:260px}}
@media(max-width:1023px){.sidebar-desktop{box-shadow:var(--shadow)}}
@media(max-width:600px){main{padding:16px!important}header{padding:10px 16px!important}}
</style>
</body>
</html>
```

He agregado los botones de navegación que solicitaste:

## ✅ Botón "Volver" en cada pantalla

He creado un componente reutilizable `BackButton` con estilo elegante que aparece en **todas las pantallas**:

- **Inicio**: "Ir al menu principal"
- **Ruta de Aprendizaje**: "Volver al inicio"
- **Lección**: "Volver a la ruta"
- **Examen**: "Salir del examen"
- **Progreso, Logros, Historial, Perfil, Config, Ayuda**: "Volver al inicio"

El botón tiene:
- Flecha animada (←) que se mueve al hacer hover
- Estilo consistente con el diseño de la app
- Efecto hover con cambio de color y borde

## ✅ Botón para cerrar el panel lateral

He mejorado el sidebar con:

1. **Botón ✕ circular** en la esquina superior derecha del panel para cerrarlo fácilmente
2. **Overlay con blur** que cubre toda la pantalla cuando el sidebar está abierto en móvil - al hacer clic fuera se cierra
3. **Cierre automático** al seleccionar cualquier opción del menú
4. **Animación suave** de entrada/salida

## ✅ Sistema de navegación inteligente

- Se guarda la pantalla anterior (`previousScreen`) para que el botón "Volver" regrese al lugar correcto
- Si estás en una lección o examen, "Volver" te regresa a donde estabas antes
- Si estás en otra pantalla, "Volver" te lleva al inicio
- El sidebar se cierra automáticamente al navegar

