function FunFactModal({fact, onClose}) {
if(!fact) return null;
return (
<div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.8)',zIndex:1000,display:'flex',alignItems:'center',justifyContent:'center',padding:20}} onClick={onClose}>
<div className="modal-in" onClick={(e)=>e.stopPropagation()} style={{background:'linear-gradient(135deg,#1a1a2e 0%,#252540 100%)',borderRadius:'var(--radius-lg)',padding:28,maxWidth:520,width:'100%',border:'2px solid var(--yellow)',boxShadow:'0 20px 60px rgba(255,212,71,0.3)',position:'relative'}}>
<div style={{position:'absolute',top:-20,right:20,fontSize:40,animation:'bounce 2s infinite'}}>{fact.icon}</div>
<div style={{fontSize:11,color:'var(--yellow)',fontWeight:700,letterSpacing:2,marginBottom:8}}>💡 DATO CURIOSO VERIFICADO</div>
