<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button>
</div>
</GenericPage>);
}

function HelpPage({onBack}) {
return (<GenericPage title="Ayuda" onBack={onBack}>
<div style={{display:'flex',flexDirection:'column',gap:16}}>
{[{q:'Como funcionan las preguntas?',a:'Las preguntas son DESAFIANTES. Debes leer la clase completa antes de responder.'},{q:'De donde salen los datos curiosos?',a:'Son datos REALES y VERIFICADOS sobre lenguas de senas.'},{q:'Cada leccion es diferente?',a:'Si! Contenido unico con explicaciones detalladas.'},{q:'Que pasa si repruebo?',a:'Vuelves a la clase completa.'},{q:'Como se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9) y aprueba el examen (80%).'}].map((item,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{item.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{item.a}</p></div>))}
</div>
