function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
if(!content || !content.stages) return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;

const [currentQ,setCurrentQ] = useState(0);
const [answers,setAnswers] = useState([]);
const [selected,setSelected] = useState(null);
const [showResult,setShowResult] = useState(false);
const [examComplete,setExamComplete] = useState(false);

let block=null,blockIdx=-1,stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<(content.stages[si].blocks||[]).length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];blockIdx=bi;stageIdx=si;break;
}
}
if(block) break;
}
if(!block) return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;

const questions = [];
(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>{questions.push({question:q.question,options:q.options,correct:q.correct,explanation:q.explanation});});});
const examQuestions = questions.slice(0, 10);
const q = examQuestions[currentQ];
const passThreshold = 80;
const score = answers.filter((a,i)=>a===examQuestions[i]?.correct).length;
const scorePct = examQuestions.length > 0 ? Math.round((score/examQuestions.length)*100) : 0;
const passed = scorePct >= passThreshold;

const handleAnswer = (idx) => {if(showResult) return;setSelected(idx);setShowResult(true);};
const nextQuestion = () => {
const newAnswers = [...answers, selected];setAnswers(newAnswers);
if(currentQ < examQuestions.length-1){setCurrentQ(currentQ+1);setSelected(null);setShowResult(false);}
else {setExamComplete(true);const newProgress = {...progress};const bp = {...(newProgress.blockProgress||{})};bp[blockId] = {passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};newProgress.blockProgress = bp;if(scorePct>=passThreshold){const sp = {...(newProgress.stageProgress||{})};sp[currentLang] = {...(sp[currentLang]||{})};sp[currentLang][stageIdx+1] = 100;newProgress.stageProgress = sp;}onComplete(newProgress);}
};

if(examComplete){
return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<DigiGuide message={passed?'Aprobaste con '+scorePct+'%!':'Obtuviste '+scorePct+'%. Necesitas '+passThreshold+'%.'} expression={passed?'celebrating':'encouraging'} action={onBack} actionLabel={passed?'Continuar':'Repasar'}/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':''}</div>
<h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2>
<p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'APROBADO!':'Necesitas repasar'}</p>
</div>
<button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button>
</div>
);
}

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Salir del examen"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}>
<div><div style={{fontSize:13,color:'var(--text2)'}}>Examen</div><div style={{fontSize:18,fontWeight:700}}>{block.name}</div></div>
<div style={{textAlign:'right'}}><div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div><div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{examQuestions.length}</div></div>
</div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}><div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/examQuestions.length*100)+'%'}}/></div>
<DigiGuide message="Examen dificil. Lee con atencion." expression="thinking"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{q.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showResult){if(i===q.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}else if(i===selected&&i!==q.correct){bg='#7f1d1d';borderColor='var(--error)';color:'var(--error)'}}
else if(selected===i){bg='var(--violet)';borderColor='var(--violet)';color:'white'}
return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',color:color,cursor:showResult?'default':'pointer',fontSize:14,textAlign:'left',lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);
})}
</div>
{showResult && <div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p></div>}
</div>
{showResult && <div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQ<examQuestions.length-1?'Siguiente →':'Ver resultados'}</button></div>}
</div>
);
}

function Sidebar({currentScreen,onNavigate,user,onLogout,sidebarOpen,onCloseSidebar}) {
const menuItems = [{id:'home',label:'Inicio',icon:'🏠'},{id:'path',label:'Ruta',icon:'🗺️'},{id:'review',label:'Repaso',icon:'🔄'},{id:'progress',label:'Progreso',icon:'📊'},{id:'achievements',label:'Logros',icon:'🏆'},{id:'history',label:'Historial',icon:'📋'},{id:'profile',label:'Perfil',icon:'👤'},{id:'settings',label:'Config',icon:'⚙️'},{id:'help',label:'Ayuda',icon:'❓'}];
return (
<>
{sidebarOpen && <div className="sidebar-overlay" onClick={onCloseSidebar}/>}
<aside style={{width:260,height:'100vh',background:'var(--surface)',borderRight:'1px solid var(--surface3)',position:'fixed',left:0,top:0,zIndex:100,display:'flex',flexDirection:'column',transform:sidebarOpen?'translateX(0)':'translateX(-100%)',transition:'var(--transition)',overflowY:'auto'}} className="sidebar-desktop">
<button className="close-sidebar-btn" onClick={onCloseSidebar} aria-label="Cerrar menu"></button>
<div style={{padding:20,paddingTop:60,borderBottom:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12}}>
<LSMexaLogo size={36}/>
<div><div style={{fontSize:18,fontWeight:800,color:'#a78bfa'}}>LSMEXA</div><div style={{fontSize:11,color:'var(--text3)'}}>v10.0</div></div>
</div>
<nav style={{flex:1,padding:'8px 0'}}>
{menuItems.map(item=>(
<button key={item.id} onClick={()=>{onNavigate(item.id);onCloseSidebar()}} style={{width:'100%',display:'flex',alignItems:'center',gap:12,padding:'12px 20px',background:currentScreen===item.id?'var(--surface2)':'transparent',border:'none',borderLeft:currentScreen===item.id?'3px solid var(--violet)':'3px solid transparent',color:currentScreen===item.id?'var(--text)':'var(--text2)',cursor:'pointer',fontSize:14,textAlign:'left',fontWeight:currentScreen===item.id?600:400}}>
<span style={{fontSize:18}}>{item.icon}</span>{item.label}
</button>
))}
</nav>
<div style={{padding:16,borderTop:'1px solid var(--surface3)'}}>
<button onClick={onLogout} style={{width:'100%',padding:'10px',background:'transparent',border:'1px solid var(--error)',borderRadius:'var(--radius-sm)',color:'var(--error)',cursor:'pointer',fontSize:14,fontWeight:600}}>Cerrar Sesion</button>
</div>
</aside>
</>
);
}

function LanguageSelector({currentLang,onSelect,compact}) {
const [open,setOpen] = useState(false);
const langs = Object.values(LANGS);
const current = LANGS[currentLang] || LANGS.lsm;
if(compact) {return (<div style={{position:'relative'}}><button onClick={()=>setOpen(!open)} style={{display:'flex',alignItems:'center',gap:8,padding:'8px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',cursor:'pointer',fontSize:14,fontWeight:600}}><span>{current.flag}</span><span>{current.code}</span><span style={{fontSize:10}}>{open?'▲':'▼'}</span></button>{open && (<div style={{position:'absolute',top:'100%',right:0,marginTop:4,background:'var(--surface)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',boxShadow:'var(--shadow)',zIndex:200,minWidth:200}}>{langs.map(l=>(<button key={l.id} onClick={()=>{onSelect(l.id);setOpen(false)}} style={{width:'100%',display:'flex',alignItems:'center',gap:10,padding:'12px 16px',background:currentLang===l.id?'var(--violet)':'transparent',border:'none',color:'var(--text)',cursor:'pointer',fontSize:14,textAlign:'left'}}><span>{l.flag}</span><div><div style={{fontWeight:600}}>{l.code}</div><div style={{fontSize:11,color:'var(--text2)'}}>{l.name}</div></div></button>))}</div>)}</div>);}
return (<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))',gap:12}}>{langs.map(l=>(<button key={l.id} onClick={()=>onSelect(l.id)} style={{padding:20,background:currentLang===l.id?'var(--violet)':'var(--surface2)',border:currentLang===l.id?'2px solid var(--orange)':'2px solid var(--surface3)',borderRadius:'var(--radius)',cursor:'pointer',textAlign:'left',color:'var(--text)'}}><div style={{fontSize:28,marginBottom:8}}>{l.flag}</div><div style={{fontSize:18,fontWeight:700}}>{l.code}</div><div style={{fontSize:13,color:'var(--text2)',marginTop:4}}>{l.name}</div>{currentLang===l.id && <div style={{marginTop:8,fontSize:12,color:'var(--yellow)',fontWeight:600}}>Activa</div>}</button>))}</div>);
}

function GenericPage({title, subtitle, children, onBack}) {
return (
<div className="animate-in">
<BackButton onClick={onBack} label="Volver al inicio"/>
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>{title}</h1>
{subtitle && <p style={{color:'var(--text2)',marginBottom:24}}>{subtitle}</p>}
{children}
</div>
);
}

function AchievementsPage({progress, onBack}) {
const unlocked = progress.achievements || [];
return (<GenericPage title="Logros" subtitle={unlocked.length + ' de ' + ACHIEVEMENT_DEFS.length} onBack={onBack}>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(240px,1fr))',gap:16}}>
{ACHIEVEMENT_DEFS.map(a=>{const isUnlocked = unlocked.includes(a.id);return (<div key={a.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'2px solid '+(isUnlocked?'var(--yellow)':'var(--surface3)'),opacity:isUnlocked?1:0.5}}><div style={{fontSize:40,marginBottom:12}}>{a.icon}</div><div style={{fontSize:16,fontWeight:700,marginBottom:4}}>{a.name}</div><div style={{fontSize:13,color:'var(--text2)',marginBottom:8}}>{a.desc}</div>{isUnlocked && <div style={{fontSize:12,color:'var(--yellow)',fontWeight:600}}>DESBLOQUEADO</div>}{!isUnlocked && <div style={{fontSize:12,color:'var(--text3)'}}>BLOQUEADO</div>}</div>);})}
</div>
</GenericPage>);
}

function ProgressDashboard({currentLang,progress, onBack}) {
const lang = LANGS[currentLang] || LANGS.lsm;
const content = CONTENT_DATA[currentLang] || {stages:[]};
const totalLessons = (content.stages||[]).reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);
const completedLessons = Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;
const courseProgress = totalLessons > 0 ? Math.round((completedLessons/totalLessons)*100) : 0;
return (<GenericPage title="Progreso" subtitle={lang.flag + ' ' + lang.name} onBack={onBack}>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{courseProgress}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{completedLessons}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div>
</div>
</GenericPage>);
}

function HistoryPage({currentLang,progress, onBack}) {
const lang = LANGS[currentLang] || LANGS.lsm;
const content = CONTENT_DATA[currentLang] || {stages:[]};
const examResults = Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));
const lessonProg = Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));
const getLessonTitle = (id) => {for(const stage of (content.stages||[])){for(const block of (stage.blocks||[])){const lesson = (block.lessons||[]).find(l=>l.id===id);if(lesson) return lesson.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag + ' ' + lang.code} onBack={onBack}>
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Examenes ({examResults.length})</h2>
{examResults.length===0 ? <p style={{color:'var(--text2)',marginBottom:24}}>Sin examenes.</p> : (<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{examResults.map(([blockId,result])=>(<div key={blockId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{blockId}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(result.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:result.passed?'var(--success)':'var(--error)'}}>{result.score}%</div><div style={{fontSize:12,color:result.passed?'var(--success)':'var(--error)'}}>{result.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lessonProg.filter(([_,v])=>v.completed).length})</h2>
{lessonProg.length===0 ? <p style={{color:'var(--text2)'}}>Sin lecciones.</p> : (<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lessonProg.map(([lessonId,lp])=>(<div key={lessonId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{getLessonTitle(lessonId)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}
</GenericPage>);
}

function ProfilePage({user,progress,onUpdate, onBack}) {
const [name,setName] = useState(user?.name||'');
const [saved,setSaved] = useState(false);
const handleSave = () => {const users = getStorage('users',{});if(users[user.email]){users[user.email].name = name;setStorage('users',users);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}>
<div style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}><div style={{width:64,height:64,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:28,fontWeight:700,color:'white'}}>{(name||'U')[0].toUpperCase()}</div><div><div style={{fontSize:20,fontWeight:700}}>{name}</div><div style={{fontSize:14,color:'var(--text2)'}}>{user?.email}</div></div></div>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={user?.email||''} disabled style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text3)',fontSize:15}}/></div>
<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button>
</div>
</GenericPage>);
}

function SettingsPage({settings,onUpdate, onBack}) {
const [dailyGoal,setDailyGoal] = useState(settings.dailyGoal||3);
const [saved,setSaved] = useState(false);
const handleSave = () => {onUpdate({...settings,dailyGoal});setSaved(true);setTimeout(()=>setSaved(false),2000);};
return (<GenericPage title="Configuracion" onBack={onBack}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}>
<h3 style={{fontSize:18,fontWeight:700,marginBottom:16}}>Preferencias</h3>
<div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Objetivo diario</label><input type="number" min="1" max="20" value={dailyGoal} onChange={e=>setDailyGoal(parseInt(e.target.value)||1)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div>
<button onClick={handleSave} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button>
</div>
</GenericPage>);
}

function HelpPage({onBack}) {
return (<GenericPage title="Ayuda" onBack={onBack}>
<div style={{display:'flex',flexDirection:'column',gap:16}}>
{[{q:'Como funcionan las preguntas?',a:'Las preguntas son DESAFIANTES. Debes leer la clase completa antes de responder.'},{q:'De donde salen los datos curiosos?',a:'Son datos REALES y VERIFICADOS sobre lenguas de senas.'},{q:'Cada leccion es diferente?',a:'Si! Contenido unico con explicaciones detalladas.'},{q:'Que pasa si repruebo?',a:'Vuelves a la clase completa.'},{q:'Como se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9) y aprueba el examen (80%).'}].map((item,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{item.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{item.a}</p></div>))}
</div>
</GenericPage>);
}

function App() {
const [user,setUser] = useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang] = useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen] = useState('home');
const [sidebarOpen,setSidebarOpen] = useState(false);
const [progress,setProgress] = useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0}));
const [settings,setSettings] = useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson] = useState(null);
const [activeExam,setActiveExam] = useState(null);
const [newAchievement,setNewAchievement] = useState(null);
const [previousScreen,setPreviousScreen] = useState('home');
const [renderError,setRenderError] = useState(null);

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
let changed = false;
ACHIEVEMENT_DEFS.forEach(a=>{if(!newAchievements.includes(a.id) && a.condition(progress)){newAchievements.push(a.id);changed = true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});
if(changed) setProgress(p=>({...p,achievements:newAchievements}));
},[progress]);

const handleAuth = (userData) => {setUser(userData);setStorage('currentUser',userData);setCurrentScreen('home');};
const handleLogout = () => {setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};

const handleLangChange = (lang) => {
if(activeLesson || activeExam){
if(!confirm('Cambiar de lengua interrumpira tu actividad actual. ¿Continuar?')) return;
}
setCurrentLang(lang);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen('home');
setSidebarOpen(false);
setRenderError(null);
};

const handleNavigate = (screen, params) => {
setRenderError(null);
if(screen==='lesson' && params){
setPreviousScreen(currentScreen);
setActiveLesson(params);
setCurrentScreen('lesson');
window.scrollTo(0,0);
} else if(screen==='exam' && params){
setPreviousScreen(currentScreen);
setActiveExam(params);
setCurrentScreen('exam');
window.scrollTo(0,0);
} else {
setPreviousScreen(currentScreen);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen(screen);
window.scrollTo(0,0);
}
setSidebarOpen(false);
};

const handleGoBack = () => {
setRenderError(null);
if(currentScreen === 'lesson' || currentScreen === 'exam'){
handleNavigate(previousScreen || 'home');
} else if(currentScreen !== 'home'){
handleNavigate('home');
}
};

const handleProgressUpdate = (newProgress) => {setProgress(newProgress);};

if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
try {
if(currentScreen==='lesson' && activeLesson) return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
if(currentScreen==='exam' && activeExam) return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate} onBack={handleGoBack}/>;
case 'review': return <GenericPage title="Repaso" subtitle="Centro de repaso" onBack={handleGoBack}><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></GenericPage>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'achievements': return <AchievementsPage progress={progress} onBack={handleGoBack}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser} onBack={handleGoBack}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings} onBack={handleGoBack}/>;
case 'help': return <HelpPage onBack={handleGoBack}/>;
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
}
} catch(e) {
console.error('Error rendering screen:', e);
setRenderError(e.message);
return (
<div style={{padding:40,textAlign:'center',maxWidth:600,margin:'0 auto'}}>
<h2 style={{color:'var(--error)',marginBottom:16}}>Error al cargar la pantalla</h2>
<p style={{color:'var(--text2)',marginBottom:20}}>{e.message}</p>
<button onClick={()=>{setRenderError(null);setCurrentScreen('home');setActiveLesson(null);setActiveExam(null);}} style={{padding:'12px 24px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Ir al inicio</button>
</div>
);
}
};

return (
<div style={{display:'flex',minHeight:'100vh'}}>
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)}/>
<div className="main-content" style={{flex:1,minHeight:'100vh',transition:'var(--transition)'}}>
<header className="main-header" style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<button onClick={()=>setSidebarOpen(!sidebarOpen)} style={{background:'none',border:'none',color:'var(--text)',cursor:'pointer',fontSize:24,padding:8}} aria-label="Abrir menu"></button>
<div className="desktop-only" style={{display:'flex',alignItems:'center',gap:8}}><LSMexaLogo size={28}/><span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span></div>
</div>
<LanguageSelector currentLang={currentLang} onSelect={handleLangChange} compact/>
</header>
<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>{renderScreen()}</main>
<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}><p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v10.0 - Soporte completo para LSM, LSF, ASL y LSC</p></footer>
</div>
{newAchievement && (<div style={{position:'fixed',bottom:20,right:20,zIndex:1000,background:'linear-gradient(135deg,var(--yellow),var(--orange))',borderRadius:'var(--radius)',padding:20,boxShadow:'0 10px 40px rgba(0,0,0,0.5)',animation:'unlock 0.5s ease-out',maxWidth:320,color:'var(--black)'}}><div style={{display:'flex',alignItems:'center',gap:12}}><div style={{fontSize:40}}>{newAchievement.icon}</div><div><div style={{fontSize:12,fontWeight:700,opacity:0.8}}>LOGRO!</div><div style={{fontSize:16,fontWeight:800}}>{newAchievement.name}</div><div style={{fontSize:12,marginTop:4}}>{newAchievement.desc}</div></div></div></div>)}
{renderError && (
<div style={{position:'fixed',bottom:20,left:20,zIndex:1000,background:'var(--error)',borderRadius:'var(--radius)',padding:16,maxWidth:400,color:'white',boxShadow:'0 10px 40px rgba(0,0,0,0.5)'}}>
