// ============ AUTH PAGE ============
function AuthPage({onAuth}) {
const [mode,setMode] = useState('register');
const [name,setName] = useState('');
const [email,setEmail] = useState('');
const [password,setPassword] = useState('');
const [showPass,setShowPass] = useState(false);
const [errors,setErrors] = useState({});
const [success,setSuccess] = useState('');
const [loading,setLoading] = useState(false);

const validate = () => {
const e = {};
if(!name.trim()) e.name = 'El nombre es requerido';
if(!email.trim()) e.email = 'El correo es requerido';
else if(!validateEmail(email)) e.email = 'Formato invalido';
if(!password) e.password = 'La contrasena es requerida';
else if(password.length < 8) e.password = 'Minimo 8 caracteres';
else if(!/[A-Z]/.test(password)) e.password = 'Debe incluir mayuscula';
else if(!/[0-9]/.test(password)) e.password = 'Debe incluir numero';
setErrors(e);
return Object.keys(e).length === 0;
};

const handleRegister = () => {
if(!validate()) return;
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
if(users[email]) {setErrors({email:'Correo ya registrado'});setLoading(false);return}
users[email] = {name,email,passwordHash:hashPassword(password),createdAt:new Date().toISOString()};
setStorage('users',users);
setSuccess('Cuenta creada!');
setTimeout(()=>onAuth({name,email}),500);
setLoading(false);
},500);
};

const handleLogin = () => {
if(!email.trim()||!validateEmail(email)){setErrors({email:'Correo invalido'});return}
if(!password){setErrors({password:'Contrasena requerida'});return}
setLoading(true);
setTimeout(()=>{
const users = getStorage('users',{});
const user = users[email];
if(!user||user.passwordHash!==hashPassword(password)){setErrors({password:'Credenciales incorrectas'});setLoading(false);return}
setStorage('currentUser',{name:user.name,email:user.email});
onAuth({name:user.name,email:user.email});
setLoading(false);
},500);
};

return (
<div style={{minHeight:'100vh',display:'flex',alignItems:'center',justifyContent:'center',padding:20,background:'linear-gradient(135deg,#0f0f1a 0%,#1a1a2e 50%,#0f0f1a 100%)'}}>
<div style={{width:'100%',maxWidth:440,animation:'fadeIn 0.5s ease-out'}}>
<div style={{textAlign:'center',marginBottom:32}}><LSMexaLogoFull/></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius-lg)',padding:32,boxShadow:'var(--shadow)',border:'1px solid var(--surface3)'}}>
<div style={{textAlign:'center',marginBottom:24}}>
<DigiMascot expression="happy" size={100}/>
<h2 style={{fontSize:22,fontWeight:700,marginTop:12,color:'var(--text)'}}>{mode==='register'?'Bienvenido a LSMexa!':'Hola de nuevo!'}</h2>
<p style={{color:'var(--text2)',fontSize:14,marginTop:4}}>{mode==='register'?'Crea tu cuenta':'Inicia sesion'}</p>
</div>
{success && <div style={{background:'#064e3b',color:'#4ade80',padding:12,borderRadius:'var(--radius-sm)',marginBottom:16,fontSize:14,textAlign:'center'}}>{success}</div>}
<div style={{display:'flex',gap:8,marginBottom:24}}>
<button onClick={()=>{setMode('register');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='register'?'var(--violet)':'var(--surface2)',color:mode==='register'?'white':'var(--text2)'}}>Registro</button>
<button onClick={()=>{setMode('login');setErrors({});setSuccess('')}} style={{flex:1,padding:'10px',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600,background:mode==='login'?'var(--violet)':'var(--surface2)',color:mode==='login'?'white':'var(--text2)'}}>Iniciar Sesion</button>
</div>
{mode==='register' && (<div style={{marginBottom:16}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Tu nombre" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.name?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.name && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.name}</p>}</div>)}
<div style={{marginBottom:16}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="tu@correo.com" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.email?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.email && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.email}</p>}</div>
<div style={{marginBottom:24}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Contrasena</label><input value={password} onChange={e=>setPassword(e.target.value)} type={showPass?'text':'password'} placeholder="Minimo 8 caracteres" style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid '+(errors.password?'var(--error)':'var(--surface3)'),borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/>{errors.password && <p style={{color:'var(--error)',fontSize:12,marginTop:4}}>{errors.password}</p>}</div>
