// ============ LEARNING PATH ============
function LearningPath({currentLang,progress,onNavigate,onBack}) {
const lang = LANGS[currentLang] || LANGS.lsm;
const content = CONTENT_DATA[currentLang] || {stages:[]};
const stages = content.stages || [];

const isLessonUnlocked = (stageIdx, blockIdx, lessonIdx) => {
if(stageIdx === 0 && blockIdx === 0 && lessonIdx === 0) return true;
if(!stages[stageIdx]) return false;
const stage = stages[stageIdx];
if(!stage.blocks || !stage.blocks[blockIdx]) return false;
const block = stage.blocks[blockIdx];
if(!block.lessons || lessonIdx < 0 || lessonIdx >= block.lessons.length) return false;

let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx;
let prevLessonIdx = lessonIdx - 1;

if(prevLessonIdx < 0){
prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0 || !stages[prevStageIdx]) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
if(!stages[prevStageIdx] || !stages[prevStageIdx].blocks[prevBlockIdx]) return false;
prevLessonIdx = stages[prevStageIdx].blocks[prevBlockIdx].lessons.length - 1;
}

if(!stages[prevStageIdx] || !stages[prevStageIdx].blocks[prevBlockIdx]) return false;
const prevLesson = stages[prevStageIdx].blocks[prevBlockIdx].lessons[prevLessonIdx];
if(!prevLesson) return false;
return progress.lessonProgress?.[prevLesson.id]?.completed || false;
};

const isBlockUnlocked = (stageIdx, blockIdx) => {
if(stageIdx === 0 && blockIdx === 0) return true;
if(!stages[stageIdx]) return false;

let prevStageIdx = stageIdx;
let prevBlockIdx = blockIdx - 1;
if(prevBlockIdx < 0){
prevStageIdx = stageIdx - 1;
if(prevStageIdx < 0 || !stages[prevStageIdx]) return false;
prevBlockIdx = stages[prevStageIdx].blocks.length - 1;
}
if(!stages[prevStageIdx] || !stages[prevStageIdx].blocks[prevBlockIdx]) return false;
const prevBlockId = stages[prevStageIdx].blocks[prevBlockIdx].id;
return progress.blockProgress?.[prevBlockId]?.passed || false;
};

return (
<div className="animate-in">
<BackButton onClick={onBack} label="Volver al inicio"/>
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>Ruta de Aprendizaje</h1>
<p style={{color:'var(--text2)',marginBottom:8}}>{lang.flag} {lang.name}</p>
<p style={{color:'var(--text3)',fontSize:12,marginBottom:24}}>Idioma: {lang.supportLang} | Gramatica: {lang.grammar}</p>
{stages.map((stage,si)=>{
const stageColor = STAGE_COLORS[si] || '#666';
const stageBlocks = stage.blocks || [];
const stageLessons = stageBlocks.reduce((s,b)=>s+(b.lessons||[]).length,0);
const stageCompleted = stageBlocks.reduce((s,b)=>s+(b.lessons||[]).filter(l=>progress.lessonProgress?.[l.id]?.completed).length,0);
const stageProgress = stageLessons > 0 ? Math.round((stageCompleted/stageLessons)*100) : 0;
const stageUnlocked = si === 0 || progress.stageProgress?.[currentLang]?.[si] >= 100;
return (
<div key={stage.id} style={{marginBottom:32,opacity:stageUnlocked?1:0.5}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:16,flexWrap:'wrap'}}>
<div style={{width:44,height:44,borderRadius:'50%',background:stageColor,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,fontWeight:800,color:'white'}}>{si+1}</div>
<div style={{flex:1}}><div style={{fontSize:20,fontWeight:700}}>{stage.name}</div><div style={{fontSize:13,color:'var(--text2)'}}>{stageCompleted}/{stageLessons} ({stageProgress}%)</div></div>
<div style={{width:200,height:10,background:'var(--surface3)',borderRadius:5}}><div style={{height:'100%',background:stageColor,borderRadius:5,width:stageProgress+'%'}}/></div>
</div>
{stageBlocks.map((block,bi)=>{
const blockUnlocked = isBlockUnlocked(si, bi);
const blockPassed = progress.blockProgress?.[block.id]?.passed || false;
const blockLessons = block.lessons || [];
const blockLessonsCompleted = blockLessons.filter(l=>progress.lessonProgress?.[l.id]?.completed).length;
return (
<div key={block.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:16,border:'1px solid '+(blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)'),opacity:blockUnlocked?1:0.6}}>
<div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:12,flexWrap:'wrap',gap:8}}>
<div style={{display:'flex',alignItems:'center',gap:10}}>
<div style={{width:32,height:32,borderRadius:'50%',background:blockPassed?'var(--success)':blockUnlocked?'var(--violet)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>{blockPassed?'✓':bi+1}</div>
<div><div style={{fontSize:16,fontWeight:700}}>{block.name}</div><div style={{fontSize:12,color:'var(--text2)'}}>{blockLessonsCompleted}/{blockLessons.length} lecciones</div></div>
</div>
{blockPassed && <span style={{fontSize:12,color:'var(--success)',fontWeight:600}}>APROBADO</span>}
{!blockUnlocked && <span style={{fontSize:12,color:'var(--text3)'}}>BLOQUEADO</span>}
</div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:8}}>
{blockLessons.map((lesson,li)=>{
const lessonUnlocked = isLessonUnlocked(si, bi, li);
const lessonCompleted = progress.lessonProgress?.[lesson.id]?.completed || false;
const lessonScore = progress.lessonProgress?.[lesson.id]?.correct || 0;
return (
<div key={lesson.id} onClick={()=>lessonUnlocked&&onNavigate('lesson',{blockId:block.id,lessonId:lesson.id})} style={{padding:'10px 12px',background:lessonCompleted?'#064e3b':lessonUnlocked?'var(--violet)':'var(--surface2)',border:'1px solid '+(lessonCompleted?'var(--success)':lessonUnlocked?'var(--orange)':'var(--surface3)'),borderRadius:'var(--radius-sm)',cursor:lessonUnlocked?'pointer':'default',opacity:lessonUnlocked?1:0.5,display:'flex',alignItems:'center',gap:8}}>
<div style={{width:24,height:24,borderRadius:'50%',background:lessonCompleted?'var(--success)':lessonUnlocked?'var(--orange)':'var(--surface3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:700,color:'white'}}>{lessonCompleted?'✓':li+1}</div>
<div style={{flex:1,minWidth:0}}><div style={{fontSize:12,fontWeight:600,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{lesson.title}</div><div style={{fontSize:10,color:'var(--text3)'}}>{lessonCompleted ? lessonScore+'/9' : 'Leccion '+(li+1)}</div></div>
{!lessonUnlocked && <span style={{fontSize:10}}>🔒</span>}
</div>
);
})}
</div>
{blockUnlocked && blockLessonsCompleted === blockLessons.length && !blockPassed && (<div style={{marginTop:12,padding:12,background:'var(--orange)',borderRadius:'var(--radius-sm)',textAlign:'center',cursor:'pointer',fontWeight:700,color:'white'}} onClick={()=>onNavigate('exam',{blockId:block.id})}>EXAMEN DEL BLOQUE →</div>)}
</div>
);
})}
</div>
);
})}
</div>
);
}

// ============ LESSON PLAYER ============
function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
if(!content || !content.stages) return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;

const [phase,setPhase] = useState('teaching');
const [teachingStep,setTeachingStep] = useState(0);
const [currentQIdx,setCurrentQIdx] = useState(0);
const [selectedAnswer,setSelectedAnswer] = useState(null);
const [showFeedback,setShowFeedback] = useState(false);
const [isCorrect,setIsCorrect] = useState(null);
const [lessonComplete,setLessonComplete] = useState(false);
const [lessonFailed,setLessonFailed] = useState(false);
const [correctCount,setCorrectCount] = useState(0);
const [answers,setAnswers] = useState([]);
const [funFact,setFunFact] = useState(null);

let block=null, lesson=null, lessonIdx=-1, blockIdx=-1, stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<(content.stages[si].blocks||[]).length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];blockIdx=bi;stageIdx=si;
lesson=(block.lessons||[]).find(l=>l.id===lessonId);
lessonIdx=(block.lessons||[]).findIndex(l=>l.id===lessonId);
break;
}
}
if(block) break;
}
if(!lesson) return <div style={{padding:40,textAlign:'center'}}>Leccion no encontrada.</div>;

const lang = LANGS[currentLang] || LANGS.lsm;
const lessonContent = lesson.content;
const teaching = lessonContent.teaching;
const questions = lessonContent.questions;
const totalQuestions = questions.length;
const currentQ = questions[currentQIdx];
const MIN_CORRECT = 5;

const teachingPhases = [
{title:'Introduccion',content:teaching.intro,icon:'📖'},
{title:'Anatomia',content:(<div><div style={{marginBottom:12}}><strong>Configuracion:</strong> {teaching.anatomy.handshape}</div><div style={{marginBottom:12}}><strong>Pulgar:</strong> {teaching.anatomy.thumb}</div><div style={{marginBottom:12}}><strong>Palma:</strong> {teaching.anatomy.palm}</div><div style={{marginBottom:12}}><strong>Orientacion:</strong> {teaching.anatomy.orientation}</div><div style={{marginBottom:12}}><strong>Ubicacion:</strong> {teaching.anatomy.location}</div><div style={{marginBottom:12}}><strong>Movimiento:</strong> {teaching.anatomy.movement}</div><div style={{marginBottom:12}}><strong>Expresion:</strong> {teaching.anatomy.facialExpression}</div><div><strong>Repeticion:</strong> {teaching.anatomy.repetition}</div></div>),icon:''},
{title:'Paso a paso',content:(<ol style={{paddingLeft:20,lineHeight:2}}>{teaching.steps.map((step,i)=><li key={i} style={{marginBottom:8}}>{step}</li>)}</ol>),icon:''},
{title:'Errores comunes',content:(<ul style={{paddingLeft:20,lineHeight:2}}>{teaching.mistakes.map((err,i)=><li key={i} style={{marginBottom:8,color:'var(--error)'}}>✗ {err}</li>)}</ul>),icon:'️'},
{title:'Contexto',content:(<div><p style={{marginBottom:12,lineHeight:1.7}}>{teaching.context}</p><p style={{marginBottom:12,lineHeight:1.7}}><strong>Nota cultural:</strong> {teaching.cultural}</p><p style={{lineHeight:1.7}}><strong>Ayuda visual:</strong> {teaching.visual}</p></div>),icon:'💬'}
];

const startQuiz = () => {setPhase('quiz');setCurrentQIdx(0);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);setCorrectCount(0);setAnswers([]);};

const handleAnswer = (idx) => {
if(showFeedback) return;
setSelectedAnswer(idx);
const correct = currentQ.correct === idx;
setIsCorrect(correct);
setShowFeedback(true);
setAnswers([...answers, idx]);
if(correct) setCorrectCount(correctCount + 1);
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
const prev = lp[lessonId] || {completed:false,correct:0,total:0,attempts:0};
lp[lessonId] = {...prev,correct: correct ? prev.correct + 1 : prev.correct,total: prev.total + 1,attempts: prev.attempts + 1};
newProgress.lessonProgress = lp;
onComplete(newProgress);
};

const nextQuestion = () => {
if(currentQIdx < totalQuestions - 1){
setCurrentQIdx(currentQIdx + 1);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);
} else {
const passed = correctCount >= MIN_CORRECT;
if(passed){
const newProgress = {...progress};
const lp = {...(newProgress.lessonProgress||{})};
lp[lessonId] = {...(lp[lessonId]||{correct:0,total:0,attempts:0}),completed:true,correct:correctCount,total:totalQuestions};
newProgress.lessonProgress = lp;
const totalLessons = content.stages.reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);
const completedLessons = Object.values(lp).filter(v=>v.completed).length;
const cp = {...(newProgress.courseProgress||{})};
cp[currentLang] = Math.round((completedLessons/totalLessons)*100);
newProgress.courseProgress = cp;
const today = new Date().toDateString();
if(newProgress.lastActiveDate !== today){
newProgress.todayLessons = 1;newProgress.lastActiveDate = today;
const yesterday = new Date(Date.now()-86400000).toDateString();
if(newProgress.lastActiveDateBefore === yesterday || !newProgress.lastActiveDateBefore){newProgress.streak = (newProgress.streak||0) + 1;} else {newProgress.streak = 1;}
newProgress.lastActiveDateBefore = today;newProgress.activeDays = (newProgress.activeDays||0) + 1;
} else {newProgress.todayLessons = (newProgress.todayLessons||0) + 1;}
const stage = content.stages[stageIdx];
const stageLessons = (stage.blocks||[]).reduce((s,b)=>s+(b.lessons||[]).length,0);
const stageCompleted = (stage.blocks||[]).reduce((s,b)=>s+(b.lessons||[]).filter(l=>lp[l.id]?.completed).length,0);
const sp = {...(newProgress.stageProgress||{})};
sp[currentLang] = {...(sp[currentLang]||{})};
sp[currentLang][stageIdx+1] = Math.round((stageCompleted/stageLessons)*100);
newProgress.stageProgress = sp;
onComplete(newProgress);setLessonComplete(true);
} else {setLessonFailed(true);}
}
};

const restartLesson = () => {setPhase('teaching');setTeachingStep(0);setCurrentQIdx(0);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);setLessonFailed(false);setLessonComplete(false);setCorrectCount(0);setAnswers([]);};

if(lessonFailed){
return (
<div className="animate-in shake-anim" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<DigiGuide message={'Obtuviste '+correctCount+'/'+totalQuestions+'. Necesitas '+MIN_CORRECT+'/'+totalQuestions+'. ¡Relee la clase!'} expression="sad"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'2px solid var(--error)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>😔</div>
<h2 style={{fontSize:28,fontWeight:800,color:'var(--error)'}}>No Aprobada</h2>
<p style={{color:'var(--text2)',fontSize:16}}>{lesson.title}</p>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:20,marginTop:16}}><div style={{fontSize:48,fontWeight:800,color:'var(--error)'}}>{correctCount+'/'+totalQuestions}</div><div style={{fontSize:14,color:'var(--text2)',marginTop:8}}>Necesitas '+MIN_CORRECT+'/'+totalQuestions+'</div></div>
</div>
<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
<button onClick={restartLesson} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}>Reiniciar leccion</button>
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button>
</div>
</div>
);
}

if(lessonComplete){
const nextLessonId = lessonIdx < (block.lessons||[]).length - 1 ? block.lessons[lessonIdx + 1].id : (blockIdx < (content.stages[stageIdx].blocks||[]).length - 1 ? content.stages[stageIdx].blocks[blockIdx + 1].lessons[0].id : null);
return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<DigiGuide message={'Excelente! '+correctCount+'/'+totalQuestions+' en "'+lesson.title+'". '+(nextLessonId?'Siguiente leccion desbloqueada!':'Bloque completado!')} expression="celebrating"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:48,marginBottom:12}}>🎉</div>
<h2 style={{fontSize:24,fontWeight:700,marginBottom:8}}>Aprobada!</h2>
<p style={{color:'var(--text2)'}}>{lesson.title}</p>
<div style={{background:'#064e3b',borderRadius:'var(--radius-sm)',padding:20,marginTop:16,border:'1px solid var(--success)'}}><div style={{fontSize:48,fontWeight:800,color:'var(--success)'}}>{correctCount+'/'+totalQuestions}</div><div style={{fontSize:14,color:'var(--text)',marginTop:8}}>Superaste el minimo</div></div>
</div>
<div style={{display:'flex',gap:12,marginTop:20,flexWrap:'wrap'}}>
{nextLessonId && <button onClick={()=>{onBack();setTimeout(()=>onNavigate('lesson',{blockId:blockId,lessonId:nextLessonId}),100)}} style={{flex:1,padding:'14px 20px',background:'var(--orange)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:700}}>Siguiente leccion</button>}
<button onClick={onBack} style={{flex:1,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button>
</div>
</div>
);
}

if(phase === 'teaching'){
const currentTeachingPhase = teachingPhases[teachingStep];
const teachingProgress = ((teachingStep + 1) / teachingPhases.length) * 100;
return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:16,marginBottom:16,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<div style={{width:36,height:36,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>{lessonIdx+1}</div>
<div style={{flex:1,minWidth:200}}><div style={{fontSize:12,color:'var(--text2)'}}>{block.name}</div><div style={{fontSize:16,fontWeight:700}}>{lesson.title}</div></div>
<div style={{background:'var(--violet)',padding:'4px 12px',borderRadius:12,fontSize:12,fontWeight:700,color:'white'}}>{lang.code}</div>
</div>
<div style={{marginBottom:20}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{fontSize:13,color:'var(--text2)'}}>Progreso de clase</span><span style={{fontSize:13,color:'var(--text2)'}}>{teachingStep+1}/{teachingPhases.length}</span></div><div style={{height:6,background:'var(--surface3)',borderRadius:3}}><div style={{height:'100%',background:'var(--violet)',borderRadius:3,width:teachingProgress+'%'}}/></div></div>
<DigiGuide message={'Fase '+(teachingStep+1)+': '+currentTeachingPhase.title+'. Lee con atencion.'} expression="teaching"/>

<button onClick={()=>setFunFact(getRealFunFact(currentLang))} className="pulse-btn" style={{width:'100%',marginTop:12,padding:'14px 20px',background:'linear-gradient(135deg,#3d3520,#5a4a2a)',border:'2px solid var(--yellow)',borderRadius:'var(--radius)',cursor:'pointer',fontSize:14,fontWeight:700,color:'var(--yellow)',display:'flex',alignItems:'center',justifyContent:'center',gap:10}}>
<span style={{fontSize:20}}>💡</span>
<span>Dato curioso sobre {lang.code}</span>
</button>

<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<div style={{display:'flex',alignItems:'center',gap:12,marginBottom:20}}><span style={{fontSize:32}}>{currentTeachingPhase.icon}</span><h2 style={{fontSize:22,fontWeight:700,color:'var(--orange)'}}>{currentTeachingPhase.title}</h2></div>
{lesson.handSign && teachingStep === 1 && (<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:20,textAlign:'center',marginBottom:20,border:'2px solid var(--violet)'}}><HandSVG type={lesson.handSign} size={220}/></div>)}
<div style={{fontSize:15,lineHeight:1.8,color:'var(--text)',whiteSpace:'pre-line'}}>{currentTeachingPhase.content}</div>
</div>
<div style={{marginTop:20,display:'flex',justifyContent:'space-between',gap:12}}>
{teachingStep > 0 && <button onClick={()=>setTeachingStep(teachingStep-1)} style={{padding:'12px 24px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:14,fontWeight:600}}>← Anterior</button>}
<div style={{flex:1}}/>
<button onClick={()=>{if(teachingStep < teachingPhases.length - 1){setTeachingStep(teachingStep + 1);} else {startQuiz();}}} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{teachingStep < teachingPhases.length - 1 ? 'Siguiente fase →' : 'Comenzar evaluacion →'}</button>
</div>
</div>
);
}

const quizProgress = ((currentQIdx)/totalQuestions)*100;
return (
<div className="animate-in" style={{maxWidth:800,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:16,marginBottom:16,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',gap:12,flexWrap:'wrap'}}>
<div style={{width:36,height:36,borderRadius:'50%',background:'var(--orange)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:700,color:'white'}}>{lessonIdx+1}</div>
<div style={{flex:1,minWidth:200}}><div style={{fontSize:12,color:'var(--text2)'}}>{block.name}</div><div style={{fontSize:16,fontWeight:700}}>{lesson.title}</div></div>
<div style={{background:'var(--orange)',padding:'4px 12px',borderRadius:12,fontSize:12,fontWeight:700,color:'white'}}>{lang.code}</div>
</div>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius-sm)',padding:12,marginBottom:16,border:'1px solid '+(correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)')}}>
<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6,flexWrap:'wrap',gap:8}}><span style={{fontSize:13,fontWeight:600}}>Progreso</span><span style={{fontSize:13,fontWeight:600,color:correctCount>=MIN_CORRECT?'var(--success)':'var(--orange)'}}>{correctCount} correctas | Minimo: {MIN_CORRECT}/{totalQuestions}</span></div>
<div style={{height:8,background:'var(--surface3)',borderRadius:4}}><div style={{height:'100%',background:'var(--violet)',borderRadius:4,width:quizProgress+'%'}}/></div>
</div>
<DigiGuide message={currentQIdx === 0 ? 'Preguntas desafiantes. Lee con atencion.' : correctCount >= MIN_CORRECT ? 'Vas bien con '+correctCount+'.' : 'Llevas '+correctCount+'. Analiza bien.'} expression={correctCount >= MIN_CORRECT ? 'excited' : 'thinking'}/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{currentQ.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{currentQ.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showFeedback){if(i===currentQ.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}else if(i===selectedAnswer&&i!==currentQ.correct){bg='#7f1d1d';borderColor='var(--error)';color='var(--error)'}}
else if(selectedAnswer===i){bg='var(--violet)';borderColor='var(--violet)';color='white'}
return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showFeedback} style={{padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',color:color,cursor:showFeedback?'default':'pointer',fontSize:14,textAlign:'left',fontWeight:selectedAnswer===i?600:400,lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);
})}
</div>
{showFeedback && (<div style={{marginTop:20,padding:16,borderRadius:'var(--radius-sm)',background:isCorrect?'#064e3b':'#7f1d1d',border:'1px solid '+(isCorrect?'var(--success)':'var(--error)')}}><div style={{fontSize:16,fontWeight:700,color:isCorrect?'var(--success)':'var(--error)',marginBottom:6}}>{isCorrect?'Correcto!':'Incorrecto'}</div><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{currentQ.explanation}</p></div>)}
</div>
{showFeedback && (<div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQIdx<totalQuestions-1?'Siguiente →':'Finalizar'}</button></div>)}
{funFact && <FunFactModal fact={funFact} onClose={()=>setFunFact(null)}/>}
</div>
);
}

// ============ BLOCK EXAM ============
function BlockExam({blockId,currentLang,progress,onComplete,onBack}) {
const content = CONTENT_DATA[currentLang];
if(!content || !content.stages) return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;

const [currentQ,setCurrentQ] = useState(0);
const [answers,setAnswers] = useState([]);
const [selected,setSelected] = useState(null);
const [showResult,setShowResult] = useState(false);
const [examComplete,setExamComplete] = useState(false);

let block=null,blockIdx=-1,stageIdx=-1;
for(let si=0;si<content.stages.length;si++){
for(let bi=0;bi<(content.stages[si].blocks||[]).length;bi++){
if(content.stages[si].blocks[bi].id===blockId){
block=content.stages[si].blocks[bi];blockIdx=bi;stageIdx=si;break;
}
}
if(block) break;
}
if(!block) return <div style={{padding:40,textAlign:'center'}}>Bloque no encontrado.</div>;

const questions = [];
(block.lessons||[]).forEach(l=>{(l.content.questions||[]).forEach(q=>{questions.push({question:q.question,options:q.options,correct:q.correct,explanation:q.explanation});});});
const examQuestions = questions.slice(0, 10);
const q = examQuestions[currentQ];
const passThreshold = 80;
const score = answers.filter((a,i)=>a===examQuestions[i]?.correct).length;
const scorePct = examQuestions.length > 0 ? Math.round((score/examQuestions.length)*100) : 0;
const passed = scorePct >= passThreshold;

const handleAnswer = (idx) => {if(showResult) return;setSelected(idx);setShowResult(true);};
const nextQuestion = () => {
const newAnswers = [...answers, selected];setAnswers(newAnswers);
if(currentQ < examQuestions.length-1){setCurrentQ(currentQ+1);setSelected(null);setShowResult(false);}
else {setExamComplete(true);const newProgress = {...progress};const bp = {...(newProgress.blockProgress||{})};bp[blockId] = {passed:scorePct>=passThreshold,score:scorePct,attempts:(bp[blockId]?.attempts||0)+1,date:new Date().toISOString()};newProgress.blockProgress = bp;if(scorePct>=passThreshold){const sp = {...(newProgress.stageProgress||{})};sp[currentLang] = {...(sp[currentLang]||{})};sp[currentLang][stageIdx+1] = 100;newProgress.stageProgress = sp;}onComplete(newProgress);}
};

if(examComplete){
return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Volver a la ruta"/>
<DigiGuide message={passed?'Aprobaste con '+scorePct+'%!':'Obtuviste '+scorePct+'%. Necesitas '+passThreshold+'%.'} expression={passed?'celebrating':'encouraging'} action={onBack} actionLabel={passed?'Continuar':'Repasar'}/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}>
<div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':''}</div>
<h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2>
<p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'APROBADO!':'Necesitas repasar'}</p>
</div>
<button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button>
</div>
);
}

return (
<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}>
<BackButton onClick={onBack} label="Salir del examen"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:20,marginBottom:20,border:'1px solid var(--surface3)',display:'flex',alignItems:'center',justifyContent:'space-between',flexWrap:'wrap',gap:8}}>
<div><div style={{fontSize:13,color:'var(--text2)'}}>Examen</div><div style={{fontSize:18,fontWeight:700}}>{block.name}</div></div>
<div style={{textAlign:'right'}}><div style={{fontSize:13,color:'var(--text2)'}}>Pregunta</div><div style={{fontSize:18,fontWeight:700}}>{currentQ+1}/{examQuestions.length}</div></div>
</div>
<div style={{height:6,background:'var(--surface3)',borderRadius:3,marginBottom:24}}><div style={{height:'100%',background:'var(--orange)',borderRadius:3,width:((currentQ)/examQuestions.length*100)+'%'}}/></div>
<DigiGuide message="Examen dificil. Lee con atencion." expression="thinking"/>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,marginTop:16,border:'1px solid var(--surface3)'}}>
<h3 style={{fontSize:17,fontWeight:700,marginBottom:20,lineHeight:1.5}}>{q.question}</h3>
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{q.options.map((opt,i)=>{
let bg='var(--surface2)',borderColor='var(--surface3)',color='var(--text)';
if(showResult){if(i===q.correct){bg='#064e3b';borderColor='var(--success)';color='var(--success)'}else if(i===selected&&i!==q.correct){bg='#7f1d1d';borderColor='var(--error)';color:'var(--error)'}}
else if(selected===i){bg='var(--violet)';borderColor='var(--violet)';color:'white'}
return (<button key={i} onClick={()=>handleAnswer(i)} disabled={showResult} style={{padding:'14px 18px',background:bg,border:'2px solid '+borderColor,borderRadius:'var(--radius-sm)',color:color,cursor:showResult?'default':'pointer',fontSize:14,textAlign:'left',lineHeight:1.5}}><span style={{fontWeight:700,marginRight:10}}>{String.fromCharCode(65+i)}.</span>{opt}</button>);
})}
</div>
{showResult && <div style={{marginTop:16,padding:14,borderRadius:'var(--radius-sm)',background:selected===q.correct?'#064e3b':'#7f1d1d',border:'1px solid '+(selected===q.correct?'var(--success)':'var(--error)')}}><p style={{fontSize:14,color:'var(--text)',lineHeight:1.6}}>{q.explanation}</p></div>}
</div>
{showResult && <div style={{marginTop:20,display:'flex',justifyContent:'flex-end'}}><button onClick={nextQuestion} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{currentQ<examQuestions.length-1?'Siguiente →':'Ver resultados'}</button></div>}
</div>
);
}

// ============ GENERIC PAGE ============
function GenericPage({title, subtitle, children, onBack}) {
return (
<div className="animate-in">
<BackButton onClick={onBack} label="Volver al inicio"/>
<h1 style={{fontSize:28,fontWeight:800,marginBottom:8}}>{title}</h1>
{subtitle && <p style={{color:'var(--text2)',marginBottom:24}}>{subtitle}</p>}
{children}
</div>
);
}

function AchievementsPage({progress, onBack}) {
const unlocked = progress.achievements || [];
return (<GenericPage title="Logros" subtitle={unlocked.length + ' de ' + ACHIEVEMENT_DEFS.length} onBack={onBack}>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(240px,1fr))',gap:16}}>
{ACHIEVEMENT_DEFS.map(a=>{const isUnlocked = unlocked.includes(a.id);return (<div key={a.id} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'2px solid '+(isUnlocked?'var(--yellow)':'var(--surface3)'),opacity:isUnlocked?1:0.5}}><div style={{fontSize:40,marginBottom:12}}>{a.icon}</div><div style={{fontSize:16,fontWeight:700,marginBottom:4}}>{a.name}</div><div style={{fontSize:13,color:'var(--text2)',marginBottom:8}}>{a.desc}</div>{isUnlocked && <div style={{fontSize:12,color:'var(--yellow)',fontWeight:600}}>DESBLOQUEADO</div>}{!isUnlocked && <div style={{fontSize:12,color:'var(--text3)'}}>BLOQUEADO</div>}</div>);})}
</div>
</GenericPage>);
}

function ProgressDashboard({currentLang,progress, onBack}) {
const lang = LANGS[currentLang] || LANGS.lsm;
const content = CONTENT_DATA[currentLang] || {stages:[]};
const totalLessons = (content.stages||[]).reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);
const completedLessons = Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;
const courseProgress = totalLessons > 0 ? Math.round((completedLessons/totalLessons)*100) : 0;
return (<GenericPage title="Progreso" subtitle={lang.flag + ' ' + lang.name + ' - ' + lang.supportLang} onBack={onBack}>
<div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:16,marginBottom:20,border:'1px solid var(--violet)'}}>
<div style={{fontSize:13,color:'var(--text2)'}}><strong>Gramatica de {lang.code}:</strong> {lang.grammar}</div>
</div>
<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{courseProgress}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{completedLessons}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div>
<div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div>
</div>
</GenericPage>);
}

function HistoryPage({currentLang,progress, onBack}) {
const lang = LANGS[currentLang] || LANGS.lsm;
const content = CONTENT_DATA[currentLang] || {stages:[]};
const examResults = Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));
const lessonProg = Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));
const getLessonTitle = (id) => {for(const stage of (content.stages||[])){for(const block of (stage.blocks||[])){const lesson = (block.lessons||[]).find(l=>l.id===id);if(lesson) return lesson.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag + ' ' + lang.code} onBack={onBack}>
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Examenes ({examResults.length})</h2>
{examResults.length===0 ? <p style={{color:'var(--text2)',marginBottom:24}}>Sin examenes.</p> : (<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{examResults.map(([blockId,result])=>(<div key={blockId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{blockId}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(result.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:result.passed?'var(--success)':'var(--error)'}}>{result.score}%</div><div style={{fontSize:12,color:result.passed?'var(--success)':'var(--error)'}}>{result.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lessonProg.filter(([_,v])=>v.completed).length})</h2>
{lessonProg.length===0 ? <p style={{color:'var(--text2)'}}>Sin lecciones.</p> : (<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lessonProg.map(([lessonId,lp])=>(<div key={lessonId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{getLessonTitle(lessonId)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}
</GenericPage>);
}

function ProfilePage({user,progress,onUpdate, onBack}) {
const [name,setName] = useState(user?.name||'');
const [saved,setSaved] = useState(false);
const handleSave = () => {const users = getStorage('users',{});if(users[user.email]){users[user.email].name = name;setStorage('users',users);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}>
