// ============ APP PRINCIPAL ============
function App() {
const [user,setUser] = useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang] = useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen] = useState('home');
const [sidebarOpen,setSidebarOpen] = useState(window.innerWidth >= 1024);
const [progress,setProgress] = useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0}));
const [settings,setSettings] = useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson] = useState(null);
const [activeExam,setActiveExam] = useState(null);
const [newAchievement,setNewAchievement] = useState(null);
const [previousScreen,setPreviousScreen] = useState('home');
const [renderError,setRenderError] = useState(null);

// Detectar cambios de tamaño de ventana
useEffect(() => {
const handleResize = () => {
if(window.innerWidth >= 1024) {
setSidebarOpen(true);
} else {
setSidebarOpen(false);
}
};
window.addEventListener('resize', handleResize);
handleResize();
return () => window.removeEventListener('resize', handleResize);
}, []);

useEffect(()=>{setStorage('currentLang',currentLang)},[currentLang]);
useEffect(()=>{setStorage('progress',progress)},[progress]);
useEffect(()=>{setStorage('settings',settings)},[settings]);

useEffect(()=>{
const newAchievements = [...(progress.achievements||[])];
let changed = false;
ACHIEVEMENT_DEFS.forEach(a=>{if(!newAchievements.includes(a.id) && a.condition(progress)){newAchievements.push(a.id);changed = true;setNewAchievement(a);setTimeout(()=>setNewAchievement(null),4000);}});
if(changed) setProgress(p=>({...p,achievements:newAchievements}));
},[progress]);

const handleAuth = (userData) => {setUser(userData);setStorage('currentUser',userData);setCurrentScreen('home');};
const handleLogout = () => {setUser(null);localStorage.removeItem('lsmexa_currentUser');setCurrentScreen('home');};

const handleLangChange = (lang) => {
setCurrentLang(lang);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen('home');
if(window.innerWidth < 1024) {
setSidebarOpen(false);
}
setRenderError(null);
};

const handleNavigate = (screen, params) => {
setRenderError(null);
if(screen==='lesson' && params){
setPreviousScreen(currentScreen);
setActiveLesson(params);
setCurrentScreen('lesson');
window.scrollTo(0,0);
} else if(screen==='exam' && params){
setPreviousScreen(currentScreen);
setActiveExam(params);
setCurrentScreen('exam');
window.scrollTo(0,0);
} else {
setPreviousScreen(currentScreen);
setActiveLesson(null);
setActiveExam(null);
setCurrentScreen(screen);
window.scrollTo(0,0);
}
if(window.innerWidth < 1024) {
setSidebarOpen(false);
}
};

const handleGoBack = () => {
setRenderError(null);
if(currentScreen === 'lesson' || currentScreen === 'exam'){
handleNavigate(previousScreen || 'home');
} else if(currentScreen !== 'home'){
handleNavigate('home');
}
};

const handleProgressUpdate = (newProgress) => {setProgress(newProgress);};

if(!user) return <AuthPage onAuth={handleAuth}/>;

const renderScreen = () => {
try {
if(currentScreen==='lesson' && activeLesson) return <LessonPlayer blockId={activeLesson.blockId} lessonId={activeLesson.lessonId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
if(currentScreen==='exam' && activeExam) return <BlockExam blockId={activeExam.blockId} currentLang={currentLang} progress={progress} onComplete={handleProgressUpdate} onBack={handleGoBack}/>;
switch(currentScreen){
case 'home': return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
case 'path': return <LearningPath currentLang={currentLang} progress={progress} onNavigate={handleNavigate} onBack={handleGoBack}/>;
case 'review': return <GenericPage title="Repaso" subtitle={'Centro de repaso - ' + (LANGS[currentLang]?.code || 'LSM')} onBack={handleGoBack}><p style={{color:'var(--text2)'}}>Sin elementos pendientes.</p></GenericPage>;
case 'progress': return <ProgressDashboard currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'achievements': return <AchievementsPage progress={progress} onBack={handleGoBack}/>;
case 'history': return <HistoryPage currentLang={currentLang} progress={progress} onBack={handleGoBack}/>;
case 'profile': return <ProfilePage user={user} progress={progress} onUpdate={setUser} onBack={handleGoBack}/>;
case 'settings': return <SettingsPage settings={settings} onUpdate={setSettings} onBack={handleGoBack}/>;
case 'help': return <HelpPage onBack={handleGoBack}/>;
default: return <HomePage user={user} currentLang={currentLang} onNavigate={handleNavigate} progress={progress} onBack={handleGoBack}/>;
}
} catch(e) {
console.error('Error:', e);
setRenderError(e.message);
return (
<div style={{padding:40,textAlign:'center',maxWidth:600,margin:'0 auto'}}>
<h2 style={{color:'var(--error)',marginBottom:16}}>Error al cargar</h2>
<p style={{color:'var(--text2)',marginBottom:20}}>{e.message}</p>
<button onClick={()=>{setRenderError(null);setCurrentScreen('home');setActiveLesson(null);setActiveExam(null);}} style={{padding:'12px 24px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Ir al inicio</button>
</div>
);
}
};

return (
<div className="app-container">
<Sidebar currentScreen={currentScreen} onNavigate={handleNavigate} user={user} onLogout={handleLogout} sidebarOpen={sidebarOpen} onCloseSidebar={()=>setSidebarOpen(false)} currentLang={currentLang} onLangChange={handleLangChange}/>
<div className={'main-content' + (sidebarOpen ? '' : ' expanded')} style={{flex:1,minHeight:'100vh',transition:'margin-left 0.3s cubic-bezier(0.4,0,0.2,1)'}}>
<header className="main-header" style={{position:'sticky',top:0,zIndex:50,background:'var(--surface)',borderBottom:'1px solid var(--surface3)',padding:'12px 24px',display:'flex',alignItems:'center',justifyContent:'space-between'}}>
<div style={{display:'flex',alignItems:'center',gap:12}}>
<button onClick={()=>setSidebarOpen(!sidebarOpen)} style={{background:'none',border:'none',color:'var(--text)',cursor:'pointer',fontSize:24,padding:8}} aria-label={sidebarOpen ? 'Ocultar menu' : 'Mostrar menu'}>
{sidebarOpen ? '✕' : '☰'}
</button>
<div className="desktop-only" style={{display:'flex',alignItems:'center',gap:8}}><LSMexaLogo size={28}/><span style={{fontSize:16,fontWeight:700,color:'#a78bfa'}}>LSMEXA</span><span style={{fontSize:11,color:'var(--text3)',marginLeft:8}}>{LANGS[currentLang]?.code}</span></div>
</div>
</header>
<main style={{padding:24,maxWidth:1200,margin:'0 auto'}}>{renderScreen()}</main>
<footer style={{padding:20,textAlign:'center',borderTop:'1px solid var(--surface3)',marginTop:40}}><p style={{fontSize:12,color:'var(--text3)'}}>LSMexa v12.0 - 4 lenguas independientes</p></footer>
</div>
{newAchievement && (<div style={{position:'fixed',bottom:20,right:20,zIndex:1000,background:'linear-gradient(135deg,var(--yellow),var(--orange))',borderRadius:'var(--radius)',padding:20,boxShadow:'0 10px 40px rgba(0,0,0,0.5)',animation:'unlock 0.5s ease-out',maxWidth:320,color:'var(--black)'}}><div style={{display:'flex',alignItems:'center',gap:12}}><div style={{fontSize:40}}>{newAchievement.icon}</div><div><div style={{fontSize:12,fontWeight:700,opacity:0.8}}>LOGRO!</div><div style={{fontSize:16,fontWeight:800}}>{newAchievement.name}</div><div style={{fontSize:12,marginTop:4}}>{newAchievement.desc}</div></div></div></div>)}
{renderError && (
<div style={{position:'fixed',bottom:20,left:20,zIndex:1000,background:'var(--error)',borderRadius:'var(--radius)',padding:16,maxWidth:400,color:'white',boxShadow:'0 10px 40px rgba(0,0,0,0.5)'}}>
<div style={{fontWeight:700,marginBottom:8}}>Error</div>
<div style={{fontSize:13,opacity:0.9}}>{renderError}</div>
<button onClick={()=>setRenderError(null)} style={{marginTop:12,padding:'6px 12px',background:'white',color:'var(--error)',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:12,fontWeight:600}}>Cerrar</button>
</div>
)}
</div>
);
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>
</body>
</html>
```

He reestructurado completamente el layout para que funcione correctamente tanto en **escritorio (PC)** como en **móvil**. Aquí están los cambios clave:

## 🖥️ Cambios para Escritorio (PC)

1. **Sidebar visible por defecto**: En pantallas ≥1024px, el sidebar aparece automáticamente al cargar
2. **Botón ☰/✕ dinámico**: El botón del header cambia entre  (mostrar) y ✕ (ocultar) según el estado
3. **Contenido principal se ajusta**: El `margin-left` del contenido principal se ajusta automáticamente (280px con sidebar, 0 sin sidebar)
4. **Transiciones suaves**: Animaciones fluidas al mostrar/ocultar el sidebar

##  Cambios para Móvil

1. **Sidebar oculto por defecto**: En pantallas <1024px, el sidebar comienza oculto
2. **Overlay con blur**: Al abrir el sidebar en móvil, aparece un overlay oscuro con efecto blur
3. **Cierre automático**: Al seleccionar una opción del menú, el sidebar se cierra automáticamente
4. **Botón ☰ siempre visible**: En móvil, el botón siempre muestra ☰ para abrir el menú

## 🎯 Funcionalidades del botón X/☰

- **En escritorio**: Alterna entre mostrar/ocultar el sidebar
- **En móvil**: Abre el sidebar (☰) o lo cierra (✕)
- **Responsive**: Detecta automáticamente el tamaño de pantalla y ajusta el comportamiento

## 📐 Sistema de clases CSS

- `.sidebar`: Estilos base del sidebar
- `.sidebar.hidden`: Oculta el sidebar (escritorio)
- `.sidebar.visible`: Muestra el sidebar (móvil)
- `.main-content.expanded`: Contenido principal sin margen lateral
- Media queries para desktop (≥1024px) y mobile (<1024px)

Ahora la aplicación funciona perfectamente en ambos formatos, con el sidebar siempre visible en PC y controlable mediante el botón ☰/✕.

