const [phase, setPhase] = useState('enter');

useEffect(() => {
// Fase 1: Entrada con rotación (1.5s)
const timer1 = setTimeout(() => {
setPhase('spinning');
}, 1500);

// Fase 2: Giro continuo (2s)
const timer2 = setTimeout(() => {
setPhase('exit');
}, 3500);

// Fase 3: Salir y mostrar app
const timer3 = setTimeout(() => {
onComplete();
}, 4000);

return () => {
clearTimeout(timer1);
clearTimeout(timer2);
clearTimeout(timer3);
};
}, [onComplete]);

return (
<div className={`splash-screen ${phase === 'exit' ? 'splash-exit' : ''}`}>
<div className={`splash-logo ${phase === 'spinning' ? 'spinning' : ''}`}>
<LogoImage size={200} />
</div>
<div className="splash-text">LSMEXA</div>
<div className="splash-subtitle">Aprende Lenguas de Señas</div>
</div>
);
}

