const getLessonData = (lessonName, lang) => {
const db = LESSON_DB[lang] || LESSON_DB.lsm;
if(db[lessonName]) return db[lessonName];
return {title: lessonName,intro: 'Leccion sobre '+lessonName+' en '+LANGS[lang].code+'.',anatomy:{handshape:'Configuracion especifica',thumb:'Posicion pulgar',palm:'Orientacion',orientation:'General',location:'Ubicacion',movement:'Tipo',facialExpression:'Expresion',repetition:'Repeticiones'},steps:['Observa','Identifica','Nota','Identifica','Observa','Presta atencion','Practica','Repite'],mistakes:['Configuracion incorrecta','Orientacion incorrecta','Ubicacion incorrecta'],context:'Comunicacion cotidiana.',cultural:'Consulta comunidad sorda local.',visual:'Practica frente a espejo.'};
};

const STAGE_DATA = {
lsm:[{name:'Fundamentos LSM',blocks:[{name:'Saludos',lessons:['Leccion 1 - HOLA','Leccion 2 - ADIOS','Leccion 3 - GRACIAS']},{name:'Alfabeto A-C',lessons:['Letra A','Letra B','Letra C']},{name:'Numeros 1-3',lessons:['Numero 1','Numero 2','Numero 3']}]},{name:'Vocabulario',blocks:[{name:'Familia',lessons:['MAMA','PAPA','FAMILIA']},{name:'Comunicacion',lessons:['SI','NO','AYUDA']}]}],
lsf:[{name:'Fondements LSF',blocks:[{name:'Salutations',lessons:['Lecon 1 - BONJOUR','Lecon 2 - AU REVOIR','Lecon 3 - MERCI']},{name:'Alphabet A-C',lessons:['Lettre A','Lettre B','Lettre C']},{name:'Nombres 1-3',lessons:['Nombre 1','Nombre 2','Nombre 3']}]},{name:'Vocabulaire',blocks:[{name:'Famille',lessons:['MAMAN','PAPA','FAMILLE']},{name:'Communication',lessons:['OUI','NON','AIDE']}]}],
asl:[{name:'ASL Fundamentals',blocks:[{name:'Greetings',lessons:['Lesson 1 - HELLO','Lesson 2 - GOODBYE','Lesson 3 - THANK YOU']},{name:'Alphabet A-C',lessons:['Letter A','Letter B','Letter C']},{name:'Numbers 1-3',lessons:['Number 1','Number 2','Number 3']}]},{name:'Vocabulary',blocks:[{name:'Family',lessons:['MOM','DAD','FAMILY']},{name:'Communication',lessons:['YES','NO','HELP']}]}],
lsc:[{name:'Fundamentos LSC',blocks:[{name:'Saludos',lessons:['Leccion 1 - HOLA','Leccion 2 - CHAO','Leccion 3 - GRACIAS']},{name:'Alfabeto A-C',lessons:['Letra A','Letra B','Letra C']},{name:'Numeros 1-3',lessons:['Numero 1','Numero 2','Numero 3']}]},{name:'Vocabulario',blocks:[{name:'Familia',lessons:['MAMA','PAPA','FAMILIA']},{name:'Comunicacion',lessons:['SI','NO','AYUDA']}]}]
};

const buildContent = (lang) => {
const stages = STAGE_DATA[lang] || STAGE_DATA.lsm;
const handSignMap = {'Letra A':'A','Letra B':'B','Letter A':'A','Letter B':'B','Lettre A':'A','Lettre B':'B','Leccion 1 - HOLA':'HELLO','Lesson 1 - HELLO':'HELLO','Lecon 1 - BONJOUR':'HELLO','Leccion 3 - GRACIAS':'THANKS','Lesson 3 - THANK YOU':'THANKS','Lecon 3 - MERCI':'THANKS','MAMA':'MOM','MAMAN':'MOM','PAPA':'DAD','SI':'YES','OUI':'YES','NO':'NO','NON':'NO','Numero 1':'NUM1','Numero 2':'NUM2','Numero 3':'NUM3','Number 1':'NUM1','Number 2':'NUM2','Number 3':'NUM3','Nombre 1':'NUM1','Nombre 2':'NUM2','Nombre 3':'NUM3'};
return {stages: stages.map((stage, si) => ({id: si + 1,name: stage.name,blocks: (stage.blocks || []).map((block, bi) => ({id: lang+'-s'+(si+1)+'-b'+(bi+1),name: block.name,lessons: (block.lessons || []).map((lessonName, li) => {const lessonData = getLessonData(lessonName, lang);return {id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),title: lessonName,handSign: handSignMap[lessonName] || null,content: {teaching: lessonData,questions: getHardQuestions(lessonName, lessonData, lang)}};})}))}))};
};

const getHardQuestions = (lessonName, data, lang) => {
return [
{question:'¿Que configuracion manual usa esta sena en '+LANGS[lang].code+'?',options:['Configuracion A','Configuracion B',data.anatomy.handshape,'Configuracion 5'],correct:2,explanation:'Configuracion: '+data.anatomy.handshape},
{question:'¿Donde se ubica esta sena?',options:['Pecho','Cabeza','Abdomen',data.anatomy.location],correct:3,explanation:'Ubicacion: '+data.anatomy.location},
{question:'¿Que tipo de movimiento tiene?',options:['Sin movimiento','Circular','Lateral',data.anatomy.movement],correct:3,explanation:'Movimiento: '+data.anatomy.movement},
{question:'¿Cual es un error comun?',options:['Rapido',data.mistakes[0] || 'Error','Sin mirar','Todas'],correct:1,explanation:'Error: '+(data.mistakes[0] || 'ver errores')},
{question:'¿Que expresion facial usa?',options:['Neutra','Enojada','Triste',data.anatomy.facialExpression],correct:3,explanation:'Expresion: '+data.anatomy.facialExpression},
{question:'¿En que contexto se usa?',options:['Solo formal','Solo familia',data.context || 'General','Solo escuela'],correct:2,explanation:data.context || 'Uso general'},
{question:'¿Cuantas veces se repite?',options:['Una','Dos','Tres',data.anatomy.repetition],correct:3,explanation:'Repeticion: '+data.anatomy.repetition},
{question:'¿Que nota cultural es importante en '+LANGS[lang].code+'?',options:['Sin importancia','Solo local',data.cultural || 'Importante','Igual en todas'],correct:2,explanation:data.cultural || 'Nota cultural'},
{question:'¿Cual es el primer paso?',options:['Rapido',data.steps[0] || 'Paso 1','Gritar','Cerrar ojos'],correct:1,explanation:'Primer paso: '+(data.steps[0] || 'ver pasos')}
];
};

const CONTENT_DATA = {lsm: buildContent('lsm'),lsf: buildContent('lsf'),asl: buildContent('asl'),lsc: buildContent('lsc')};

const ACHIEVEMENT_DEFS = [
{id:'first_lesson',name:'Primera Leccion',desc:'Completa tu primera leccion',icon:'',condition:(p)=>Object.values(p.lessonProgress||{}).some(v=>v.completed)},
{id:'ten_lessons',name:'Diez Lecciones',desc:'Completa 10 lecciones',icon:'',condition:(p)=>Object.values(p.lessonProgress||{}).filter(v=>v.completed).length>=10},
{id:'first_block',name:'Primer Bloque',desc:'Aprueba tu primer examen',icon:'🏆',condition:(p)=>Object.values(p.blockProgress||{}).some(v=>v.passed)},
{id:'streak_3',name:'Racha de 3',desc:'Practica 3 dias seguidos',icon:'🔥',condition:(p)=>(p.streak||0)>=3},
{id:'perfect_lesson',name:'Leccion Perfecta',desc:'Obten 9/9',icon:'💯',condition:(p)=>Object.values(p.lessonProgress||{}).some(v=>v.completed && v.correct===9)},
{id:'polyglot',name:'Poliglota',desc:'Estudia 2 lenguas',icon:'🌍',condition:(p)=>Object.keys(p.courseProgress||{}).filter(k=>(p.courseProgress[k]||0)>0).length>=2}
];

const getStorage = (key, def) => {try{return JSON.parse(localStorage.getItem('lsmexa_'+key))||def}catch(e){return def}};
const setStorage = (key, val) => {try{localStorage.setItem('lsmexa_'+key,JSON.stringify(val))}catch(e){}};
const hashPassword = (p) => {let h=0;for(let i=0;i<p.length;i++){h=((h<<5)-h)+p.charCodeAt(i);h|=0}return'h_'+Math.abs(h).toString(36)+'_'+p.length};
const validateEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

