const getLessonData = (lessonName, lang) => {
const db = LESSON_DB[lang] || LESSON_DB.lsm;
if(db[lessonName]) return db[lessonName];
return {title: lessonName,intro: 'Lección sobre '+lessonName+' en '+LANGS[lang].code+'.',anatomy:{handshape:'Configuración específica',thumb:'Posición pulgar',palm:'Orientación',orientation:'General',location:'Ubicación',movement:'Tipo',facialExpression:'Expresión',repetition:'Repeticiones'},steps:['Observa','Identifica','Nota','Identifica','Observa','Presta atención','Practica','Repite'],mistakes:['Configuración incorrecta','Orientación incorrecta','Ubicación incorrecta'],context:'Comunicación cotidiana.',cultural:'Consulta comunidad sorda local.',visual:'Practica frente a espejo.'};
};

