{examResults.length===0 ? <p style={{color:'var(--text2)',marginBottom:24}}>Sin exámenes.</p> : (<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{examResults.map(([blockId,result])=>(<div key={blockId} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{blockId}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(result.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:result.passed?'var(--success)':'var(--error)'}}>{result.score}%</div><div style={{fontSize:12,color:result.passed?'var(--success)':'var(--error)'}}>{result.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}
<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lessonProg.filter(([_,v])=>v.completed).length})</h2>
