const handSignMap = {'Letra A':'A','Letra B':'B','Letter A':'A','Letter B':'B','Lettre A':'A','Lettre B':'B','Leccion 1 - HOLA':'HELLO','Lesson 1 - HELLO':'HELLO','Lecon 1 - BONJOUR':'HELLO','Leccion 3 - GRACIAS':'THANKS','Lesson 3 - THANK YOU':'THANKS','Lecon 3 - MERCI':'THANKS','MAMA':'MOM','MAMAN':'MOM','PAPA':'DAD','SI':'YES','OUI':'YES','NO':'NO','NON':'NO','Numero 1':'NUM1','Numero 2':'NUM2','Numero 3':'NUM3','Number 1':'NUM1','Number 2':'NUM2','Number 3':'NUM3','Nombre 1':'NUM1','Nombre 2':'NUM2','Nombre 3':'NUM3'};
return {stages: stages.map((stage, si) => ({id: si + 1,name: stage.name,blocks: (stage.blocks || []).map((block, bi) => ({id: lang+'-s'+(si+1)+'-b'+(bi+1),name: block.name,lessons: (block.lessons || []).map((lessonName, li) => {const lessonData = getLessonData(lessonName, lang);return {id: lang+'-s'+(si+1)+'-b'+(bi+1)+'-l'+(li+1),title: lessonName,handSign: handSignMap[lessonName] || null,content: {teaching: lessonData,questions: getHardQuestions(lessonName, lessonData, lang)}};})}))}))};
};

const getHardQuestions = (lessonName, data, lang) => {
return [
{question:'¿Qué configuración manual usa esta seña en '+LANGS[lang].code+'?',options:['Configuración A','Configuración B',data.anatomy.handshape,'Configuración 5'],correct:2,explanation:'Configuración: '+data.anatomy.handshape},
{question:'¿Dónde se ubica esta seña?',options:['Pecho','Cabeza','Abdomen',data.anatomy.location],correct:3,explanation:'Ubicación: '+data.anatomy.location},
{question:'¿Qué tipo de movimiento tiene?',options:['Sin movimiento','Circular','Lateral',data.anatomy.movement],correct:3,explanation:'Movimiento: '+data.anatomy.movement},
{question:'¿Cuál es un error común?',options:['Rápido',data.mistakes[0] || 'Error','Sin mirar','Todas'],correct:1,explanation:'Error: '+(data.mistakes[0] || 'ver errores')},
{question:'¿Qué expresión facial usa?',options:['Neutra','Enojada','Triste',data.anatomy.facialExpression],correct:3,explanation:'Expresión: '+data.anatomy.facialExpression},
{question:'¿En qué contexto se usa?',options:['Solo formal','Solo familia',data.context || 'General','Solo escuela'],correct:2,explanation:data.context || 'Uso general'},
{question:'¿Cuántas veces se repite?',options:['Una','Dos','Tres',data.anatomy.repetition],correct:3,explanation:'Repetición: '+data.anatomy.repetition},
{question:'¿Qué nota cultural es importante en '+LANGS[lang].code+'?',options:['Sin importancia','Solo local',data.cultural || 'Importante','Igual en todas'],correct:2,explanation:data.cultural || 'Nota cultural'},
{question:'¿Cuál es el primer paso?',options:['Rápido',data.steps[0] || 'Paso 1','Gritar','Cerrar ojos'],correct:1,explanation:'Primer paso: '+(data.steps[0] || 'ver pasos')}
];
};

