.lang-btn-compact{padding:8px 10px;background:var(--surface2);border:1px solid var(--surface3);border-radius:var(--radius-sm);color:var(--text);cursor:pointer;font-size:11px;text-align:center;transition:var(--transition);display:flex;align-items:center;justify-content:center;gap:6px;font-weight:600;font-family:'Inter',sans-serif}
