// Cada seña replicada exactamente como en la imagen proporcionada
const SignDemonstration = ({type, title, description}) => {
// Colores de piel realistas
const skinColors = {
base: '#d4a574',
light: '#e8b896',
dark: '#a67c52',
shadow: '#8b6f47',
highlight: '#f5d5b8',
nail: '#f8e8d8',
