};

// Configuraciones exactas basadas en la imagen
const signConfigs = {
A: {
name: 'A',
description: 'Puño cerrado, pulgar al lado del índice',
render: () => (
<g transform="translate(200, 250)">
{/* Antebrazo */}
<rect x="-30" y="80" width="60" height="120" rx="20" fill={`url(#skinGrad)`}/>
<rect x="-30" y="80" width="60" height="120" rx="20" fill={`url(#skinHighlight)`} opacity="0.3"/>

{/* Muñeca */}
<ellipse cx="0" cy="80" rx="35" ry="20" fill={`url(#skinGrad)`}/>

{/* Palma cerrada (puño) */}
<ellipse cx="0" cy="30" rx="40" ry="45" fill={`url(#skinGrad)`}/>
<ellipse cx="0" cy="30" rx="40" ry="45" fill={`url(#skinShadow)`} opacity="0.3"/>

{/* Nudillos visibles */}
{[-20, -7, 7, 20].map((x, i) => (
<ellipse key={i} cx={x} cy="5" rx="8" ry="10" fill={`url(#skinGrad)`}/>
))}

{/* Pliegues del puño */}
<path d="M -25 10 Q -15 8 -5 10" stroke={skinColors.shadow} strokeWidth="1.5" fill="none" opacity="0.6"/>
<path d="M -5 10 Q 5 8 15 10" stroke={skinColors.shadow} strokeWidth="1.5" fill="none" opacity="0.6"/>
<path d="M 15 10 Q 22 8 28 10" stroke={skinColors.shadow} strokeWidth="1.5" fill="none" opacity="0.6"/>

{/* Pulgar al lado */}
<ellipse cx="42" cy="20" rx="10" ry="25" fill={`url(#skinGrad)`} transform="rotate(15 42 20)"/>
<ellipse cx="42" cy="20" rx="10" ry="25" fill={`url(#skinHighlight)`} opacity="0.3" transform="rotate(15 42 20)"/>
<ellipse cx="45" cy="0" rx="5" ry="7" fill={skinColors.nail} transform="rotate(15 45 0)"/>
