<div style={{fontSize:11,color:'var(--yellow)',fontWeight:700,letterSpacing:2,marginBottom:8}}>DATO CURIOSO</div>
<h3 style={{fontSize:20,fontWeight:800,color:'var(--yellow)',marginBottom:12}}>{fact.title}</h3>
<p style={{fontSize:15,lineHeight:1.7,color:'var(--text)',marginBottom:16}}>{fact.text}</p>
