function LessonPlayer({blockId,lessonId,currentLang,progress,onComplete,onBack,onCuriousOpen}) {
const content=CONTENT_DATA[currentLang];
if(!content||!content.stages) return <div style={{padding:40,textAlign:'center'}}>Contenido no disponible.</div>;
const [phase,setPhase]=useState('teaching');const [teachingStep,setTeachingStep]=useState(0);const [currentQIdx,setCurrentQIdx]=useState(0);const [selectedAnswer,setSelectedAnswer]=useState(null);const [showFeedback,setShowFeedback]=useState(false);const [isCorrect,setIsCorrect]=useState(null);const [lessonComplete,setLessonComplete]=useState(false);const [lessonFailed,setLessonFailed]=useState(false);const [correctCount,setCorrectCount]=useState(0);const [answers,setAnswers]=useState([]);const [funFact,setFunFact]=useState(null);
let block=null,lesson=null,lessonIdx=-1,blockIdx=-1,stageIdx=-1;
for(let si=0;si<content.stages.length;si++){const bks=content.stages[si].blocks||[];for(let bi=0;bi<bks.length;bi++){if(bks[bi].id===blockId){block=bks[bi];blockIdx=bi;stageIdx=si;const ls=block.lessons||[];lesson=ls.find(l=>l.id===lessonId);lessonIdx=ls.findIndex(l=>l.id===lessonId);break;}}if(block)break;}
if(!lesson) return <div style={{padding:40,textAlign:'center'}}>Lección no encontrada.</div>;
const lang=LANGS[currentLang]||LANGS.lsm;const teaching=lesson.content.teaching;const questions=lesson.content.questions;const totalQuestions=questions.length;const currentQ=questions[currentQIdx];const MIN_CORRECT=5;
const teachingPhases=[
{title:'Introducción',content:teaching.intro,icon:'📖'},
{title:'Anatomía de la Seña',content:(<div><div style={{marginBottom:12}}><strong>Configuración:</strong> {teaching.anatomy.handshape}</div><div style={{marginBottom:12}}><strong>Pulgar:</strong> {teaching.anatomy.thumb}</div><div style={{marginBottom:12}}><strong>Palma:</strong> {teaching.anatomy.palm}</div><div style={{marginBottom:12}}><strong>Orientación:</strong> {teaching.anatomy.orientation}</div><div style={{marginBottom:12}}><strong>Ubicación:</strong> {teaching.anatomy.location}</div><div style={{marginBottom:12}}><strong>Movimiento:</strong> {teaching.anatomy.movement}</div><div style={{marginBottom:12}}><strong>Expresión facial:</strong> {teaching.anatomy.facialExpression}</div><div><strong>Repetición:</strong> {teaching.anatomy.repetition}</div></div>),icon:'🤚'},
{title:'Paso a paso',content:(<ol style={{paddingLeft:20,lineHeight:2}}>{teaching.steps.map((s,i)=><li key={i} style={{marginBottom:8}}>{s}</li>)}</ol>),icon:'📝'},
{title:'Errores comunes',content:(<ul style={{paddingLeft:20,lineHeight:2}}>{teaching.mistakes.map((m,i)=><li key={i} style={{marginBottom:8,color:'var(--error)'}}>✗ {m}</li>)}</ul>),icon:'⚠️'},
{title:'Contexto y cultura',content:(<div><p style={{marginBottom:12,lineHeight:1.7}}>{teaching.context}</p><p style={{marginBottom:12,lineHeight:1.7}}><strong>Nota cultural:</strong> {teaching.cultural}</p><p style={{lineHeight:1.7}}><strong>Ayuda visual:</strong> {teaching.visual}</p></div>),icon:'💬'}
];
const startQuiz=()=>{setPhase('quiz');setCurrentQIdx(0);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);setCorrectCount(0);setAnswers([]);};
const handleAnswer=(idx)=>{if(showFeedback)return;setSelectedAnswer(idx);const ok=currentQ.correct===idx;setIsCorrect(ok);setShowFeedback(true);setAnswers([...answers,idx]);if(ok)setCorrectCount(correctCount+1);const np={...progress};const lp={...(np.lessonProgress||{})};const prev=lp[lessonId]||{completed:false,correct:0,total:0,attempts:0};lp[lessonId]={...prev,correct:ok?prev.correct+1:prev.correct,total:prev.total+1,attempts:prev.attempts+1};np.lessonProgress=lp;onComplete(np);};
const nextQuestion=()=>{if(currentQIdx<totalQuestions-1){setCurrentQIdx(currentQIdx+1);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);}else{const passed=correctCount>=MIN_CORRECT;if(passed){const np={...progress};const lp={...(np.lessonProgress||{})};lp[lessonId]={...(lp[lessonId]||{correct:0,total:0,attempts:0}),completed:true,correct:correctCount,total:totalQuestions};np.lessonProgress=lp;const tl=content.stages.reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);const cl=Object.values(lp).filter(v=>v.completed).length;const cp={...(np.courseProgress||{})};cp[currentLang]=Math.round((cl/tl)*100);np.courseProgress=cp;const today=new Date().toDateString();if(np.lastActiveDate!==today){np.todayLessons=1;np.lastActiveDate=today;const yest=new Date(Date.now()-86400000).toDateString();if(np.lastActiveDateBefore===yest||!np.lastActiveDateBefore){np.streak=(np.streak||0)+1;}else{np.streak=1;}np.lastActiveDateBefore=today;np.activeDays=(np.activeDays||0)+1;}else{np.todayLessons=(np.todayLessons||0)+1;}const stage=content.stages[stageIdx];const sl=(stage.blocks||[]).reduce((s,b)=>s+(b.lessons||[]).length,0);const scomp=(stage.blocks||[]).reduce((s,b)=>s+(b.lessons||[]).filter(l=>lp[l.id]?.completed).length,0);const sp2={...(np.stageProgress||{})};sp2[currentLang]={...(sp2[currentLang]||{})};sp2[currentLang][stageIdx+1]=Math.round((scomp/sl)*100);np.stageProgress=sp2;onComplete(np);setLessonComplete(true);}else{setLessonFailed(true);}}};
const restartLesson=()=>{setPhase('teaching');setTeachingStep(0);setCurrentQIdx(0);setSelectedAnswer(null);setShowFeedback(false);setIsCorrect(null);setLessonFailed(false);setLessonComplete(false);setCorrectCount(0);setAnswers([]);};
