function ProgressDashboard({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const tl=stages.reduce((s,st)=>s+(st.blocks||[]).reduce((bs,b)=>bs+(b.lessons||[]).length,0),0);const cl=Object.values(progress.lessonProgress||{}).filter(v=>v.completed).length;const cp=tl>0?Math.round((cl/tl)*100):0;
return (<GenericPage title="Progreso" subtitle={lang.flag+' '+lang.name+' - '+lang.supportLang} onBack={onBack}><div style={{background:'var(--surface2)',borderRadius:'var(--radius)',padding:16,marginBottom:20,border:'1px solid var(--violet)'}}><div style={{fontSize:13,color:'var(--text2)'}}><strong>Gramática de {lang.code}:</strong> {lang.grammar}</div></div><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(180px,1fr))',gap:16,marginBottom:32}}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--orange)'}}>{cp}%</div><div style={{fontSize:14,color:'var(--text2)'}}>Progreso</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--success)'}}>{cl}</div><div style={{fontSize:14,color:'var(--text2)'}}>Lecciones</div></div><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:40,fontWeight:800,color:'var(--yellow)'}}>{progress.streak||0}</div><div style={{fontSize:14,color:'var(--text2)'}}>Racha</div></div></div></GenericPage>);}
function HistoryPage({currentLang,progress,onBack}){const lang=LANGS[currentLang]||LANGS.lsm;const content=CONTENT_DATA[currentLang]||{stages:[]};const stages=content.stages||[];const er=Object.entries(progress.examResults||{}).filter(([k])=>k.startsWith(currentLang));const lp2=Object.entries(progress.lessonProgress||{}).filter(([k])=>k.startsWith(currentLang));const glt=(id)=>{for(const st of stages){for(const b of (st.blocks||[])){const l=(b.lessons||[]).find(x=>x.id===id);if(l)return l.title;}}return id;};
return (<GenericPage title="Historial" subtitle={lang.flag+' '+lang.code} onBack={onBack}><h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Exámenes ({er.length})</h2>{er.length===0?<p style={{color:'var(--text2)',marginBottom:24}}>Sin exámenes.</p>:(<div style={{display:'flex',flexDirection:'column',gap:8,marginBottom:32}}>{er.map(([bid,r])=>(<div key={bid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:16,border:'1px solid var(--surface3)',display:'flex',justifyContent:'space-between',alignItems:'center',flexWrap:'wrap',gap:8}}><div><div style={{fontSize:14,fontWeight:600}}>{bid}</div><div style={{fontSize:12,color:'var(--text3)'}}>{new Date(r.date).toLocaleString()}</div></div><div style={{textAlign:'right'}}><div style={{fontSize:20,fontWeight:700,color:r.passed?'var(--success)':'var(--error)'}}>{r.score}%</div><div style={{fontSize:12,color:r.passed?'var(--success)':'var(--error)'}}>{r.passed?'APROBADO':'NO APROBADO'}</div></div></div>))}</div>)}<h2 style={{fontSize:18,fontWeight:700,marginBottom:12}}>Lecciones ({lp2.filter(([_,v])=>v.completed).length})</h2>{lp2.length===0?<p style={{color:'var(--text2)'}}>Sin lecciones.</p>:(<div style={{display:'flex',flexDirection:'column',gap:6,maxHeight:400,overflowY:'auto'}}>{lp2.map(([lid,lp])=>(<div key={lid} style={{background:'var(--surface)',borderRadius:'var(--radius-sm)',padding:12,border:'1px solid '+(lp.completed?'var(--success)':'var(--surface3)'),display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontSize:13,fontWeight:600}}>{glt(lid)}</div><div style={{fontSize:12,color:lp.completed?'var(--success)':'var(--text2)'}}>{lp.correct||0}/9 {lp.completed?'✓':''}</div></div>))}</div>)}</GenericPage>);}
function ProfilePage({user,progress,onUpdate,onBack}){const [name,setName]=useState(user?.name||'');const [saved,setSaved]=useState(false);const hs=()=>{const u=getStorage('users',{});if(u[user.email]){u[user.email].name=name;setStorage('users',u);setStorage('currentUser',{...user,name});onUpdate({...user,name});setSaved(true);setTimeout(()=>setSaved(false),2000);}};
return (<GenericPage title="Perfil" onBack={onBack}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}><div style={{display:'flex',alignItems:'center',gap:16,marginBottom:24}}><div style={{width:64,height:64,borderRadius:'50%',background:'var(--violet)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:28,fontWeight:700,color:'white'}}>{(name||'U')[0].toUpperCase()}</div><div><div style={{fontSize:20,fontWeight:700}}>{name}</div><div style={{fontSize:14,color:'var(--text2)'}}>{user?.email}</div></div></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Nombre</label><input value={name} onChange={e=>setName(e.target.value)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Correo</label><input value={user?.email||''} disabled style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text3)',fontSize:15}}/></div><button onClick={hs} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button></div></GenericPage>);}
function SettingsPage({settings,onUpdate,onBack}){const [dg,setDg]=useState(settings.dailyGoal||3);const [saved,setSaved]=useState(false);const hs=()=>{onUpdate({...settings,dailyGoal:dg});setSaved(true);setTimeout(()=>setSaved(false),2000);};
return (<GenericPage title="Configuración" onBack={onBack}><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,border:'1px solid var(--surface3)',maxWidth:500}}><h3 style={{fontSize:18,fontWeight:700,marginBottom:16}}>Preferencias</h3><div style={{marginBottom:20}}><label style={{display:'block',fontSize:13,fontWeight:600,color:'var(--text2)',marginBottom:6}}>Objetivo diario</label><input type="number" min="1" max="20" value={dg} onChange={e=>setDg(parseInt(e.target.value)||1)} style={{width:'100%',padding:'12px 14px',background:'var(--surface2)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',color:'var(--text)',fontSize:15,outline:'none'}}/></div><button onClick={hs} style={{padding:'12px 28px',background:'var(--violet)',color:'white',border:'none',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>{saved?'Guardado':'Guardar'}</button></div></GenericPage>);}
function HelpPage({onBack}){return (<GenericPage title="Ayuda" onBack={onBack}><div style={{display:'flex',flexDirection:'column',gap:16}}>{[{q:'¿Cuántas lenguas hay?',a:'4 lenguas independientes: LSM, LSF, ASL, LSC. Cada una con su propia gramática.'},{q:'¿Cómo cambio de lengua?',a:'Usa los botones en el panel lateral izquierdo.'},{q:'¿Las gramáticas son iguales?',a:'NO. Cada lengua tiene gramática propia.'},{q:'¿Qué pasa si repruebo?',a:'Vuelves a la clase completa.'},{q:'¿Cómo se desbloquea el siguiente bloque?',a:'Completa todas las lecciones (5/9) y aprueba el examen (80%).'}].map((it,i)=>(<div key={i} style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:24,border:'1px solid var(--surface3)'}}><div style={{fontSize:16,fontWeight:700,color:'var(--orange)',marginBottom:8}}>{it.q}</div><p style={{fontSize:14,color:'var(--text2)',lineHeight:1.7}}>{it.a}</p></div>))}</div></GenericPage>);}

function App() {
const [showSplash,setShowSplash]=useState(true);
const [user,setUser]=useState(()=>getStorage('currentUser',null));
const [currentLang,setCurrentLang]=useState(()=>getStorage('currentLang','lsm'));
const [currentScreen,setCurrentScreen]=useState('home');
const [sidebarOpen,setSidebarOpen]=useState(window.innerWidth>=1024);
const [progress,setProgress]=useState(()=>getStorage('progress',{courseProgress:{},stageProgress:{},blockProgress:{},lessonProgress:{},examResults:{},reviewItems:{},achievements:[],streak:0,todayLessons:0,dailyGoal:3,lastActiveDate:null,lastActiveDateBefore:null,earlyLessons:0,nightLessons:0,activeDays:0,reviewSessions:0,lessonsRetaken:0,visitedSections:[],curiousOpened:0}));
const [settings,setSettings]=useState(()=>getStorage('settings',{dailyGoal:3,textSize:'normal',highContrast:false,reduceMotion:false}));
const [activeLesson,setActiveLesson]=useState(null);
const [activeExam,setActiveExam]=useState(null);
