<radialGradient id="digiCheek" cx="50%" cy="50%" r="50%"><stop offset="0%" stopColor="#FF9A9A" stopOpacity="0.6"/><stop offset="100%" stopColor="#FF6B6B" stopOpacity="0"/></radialGradient>
