</defs>
<g filter="url(#digiShadow)"><path d="M 85 85 Q 95 80, 100 70 Q 105 60, 100 55 Q 95 50, 90 55 Q 85 60, 82 70 Q 80 78, 85 85 Z" fill="url(#digiTail)"/><path d="M 95 60 Q 98 58, 100 60 Q 102 62, 100 65 Q 98 67, 95 65 Q 93 63, 95 60 Z" fill="#FFD447" opacity="0.8"/></g>
