<g filter="url(#digiShadow)"><path d="M 82 75 Q 90 72, 92 68 Q 94 64, 92 62 Q 90 60, 88 62 Q 86 64, 84 70 Q 83 73, 82 75 Z" fill="url(#digiBody)"/><circle cx="91" cy="63" r="3.5" fill="url(#digiBody)"/></g>
<g filter="url(#digiShadow)"><circle cx="60" cy="52" r="26" fill="url(#digiBody)"/></g>
