{e.eyes==='side'&&(<g filter="url(#digiGlow)"><ellipse cx="52" cy="50" rx="5" ry="6" fill="white"/><ellipse cx="70" cy="50" rx="5" ry="6" fill="white"/><circle cx="54" cy="50" r="3.5" fill="#1a1a2e"/><circle cx="72" cy="50" r="3.5" fill="#1a1a2e"/><circle cx="55" cy="48" r="1.5" fill="white"/><circle cx="73" cy="48" r="1.5" fill="white"/></g>)}
{e.eyebrows==='raised'&&(<><path d="M 45 43 Q 50 40, 55 43" stroke="#4A3FA0" strokeWidth="2" fill="none" strokeLinecap="round"/><path d="M 65 43 Q 70 40, 75 43" stroke="#4A3FA0" strokeWidth="2" fill="none" strokeLinecap="round"/></>)}
{e.eyebrows==='sad'&&(<><path d="M 45 44 Q 50 46, 55 43" stroke="#4A3FA0" strokeWidth="2" fill="none" strokeLinecap="round"/><path d="M 65 43 Q 70 46, 75 44" stroke="#4A3FA0" strokeWidth="2" fill="none" strokeLinecap="round"/></>)}
