const hashStr = (s) => {let h=0;for(let i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;}return Math.abs(h);};
const seededShuffle = (arr, seed) => {const a=[...arr];let s=seed||1;const rnd=()=>{s=(s*9301+49297)%233280;return s/233280;};for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));const t=a[i];a[i]=a[j];a[j]=t;}return a;};
