function buildQuestions(conceptId, data, pool, lang){
const fields = [
{q:'Según la clase, ¿cuál es la configuración de la mano?', correct:data.anatomy.handshape, key:'handshape'},
{q:'¿Dónde se ubica exactamente esta seña?', correct:data.anatomy.location, key:'location'},
{q:'¿Qué movimiento describe la lección?', correct:data.anatomy.movement, key:'movement'},
{q:'¿Cómo se orienta la palma al ejecutarla?', correct:data.anatomy.palm, key:'palm'},
{q:'¿Qué orientación general enseña la clase?', correct:data.anatomy.orientation, key:'orientation'},
{q:'¿Qué expresión facial debe acompañarla?', correct:data.anatomy.facialExpression, key:'facialExpression'},
{q:'¿Cuántas repeticiones indica la lección?', correct:data.anatomy.repetition, key:'repetition'},
{q:'¿Cuál es el primer paso explicado en clase?', correct:data.steps[0], key:'steps0'},
{q:'¿Cuál de estos es un error común mencionado?', correct:data.mistakes[0], key:'mistakes0'},
{q:'¿En qué contexto se usa principalmente?', correct:data.context, key:'context'}
];
const seedBase = hashStr(lang + conceptId);
return fields.slice(0,9).map((f, idx) => {
const others = pool.filter(p => p.id !== conceptId).map(p => p.data).filter(Boolean);
let distractors = [];
if(f.key === 'steps0'){ distractors = seededShuffle(others.map(o => o.steps && o.steps[0]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
else if(f.key === 'mistakes0'){ distractors = seededShuffle(others.map(o => o.mistakes && o.mistakes[1]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
else { const k = {handshape:'handshape',location:'location',movement:'movement',palm:'palm',orientation:'orientation',facialExpression:'facialExpression',repetition:'repetition',context:'context'}[f.key]; distractors = seededShuffle(others.map(o => o.anatomy && o.anatomy[k]).filter(v => v && v !== f.correct), seedBase+idx).slice(0,3); }
while(distractors.length < 3){ const pad = (PADS[f.key]||PADS.context)[distractors.length % 3]; if(!distractors.includes(pad) && pad !== f.correct) distractors.push(pad); else distractors.push(pad + ' (' + (distractors.length+1) + ')'); }
const options = seededShuffle([f.correct, ...distractors.slice(0,3)], seedBase + idx * 7 + 13);
return {question:f.q, options:options, correct:options.indexOf(f.correct), explanation:'La clase lo indica: ' + f.correct};
});
}

