function DigiAssistant(){const[showComment,setShowComment]=useState(false);const[currentComment,setCurrentComment]=useState('');const[digiExpression,setDigiExpression]=useState('happy');useEffect(()=>{const show=()=>{setCurrentComment(DIGI_COMMENTS[Math.floor(Math.random()*DIGI_COMMENTS.length)]);setDigiExpression(['happy','excited','encouraging','teaching'][Math.floor(Math.random()*4)]);setShowComment(true);setTimeout(()=>setShowComment(false),5000);};const t1=setTimeout(show,10000);const iv=setInterval(()=>setTimeout(show,Math.random()*30000+30000),60000);return()=>{clearTimeout(t1);clearInterval(iv);};},[]);return(<div className="digi-assistant">{showComment&&(<div className="digi-speech-bubble"><p>{currentComment}</p></div>)}<div className="digi-character" onClick={()=>setShowComment(!showComment)}><DigiMascot expression={digiExpression} size={140} animated={true}/></div></div>);}
function SplashScreen({onComplete}){const[phase,setPhase]=useState('enter');useEffect(()=>{const t1=setTimeout(()=>setPhase('spinning'),1800);const t2=setTimeout(()=>setPhase('exit'),4000);const t3=setTimeout(()=>onComplete(),4600);return()=>{clearTimeout(t1);clearTimeout(t2);clearTimeout(t3);};},[onComplete]);return(<div className={`splash-screen ${phase==='exit'?'splash-exit':''}`}><div className={`splash-logo ${phase==='spinning'?'spinning':''}`}><LSMexaLogoSVG size={280}/></div><div className="splash-text">LSMEXA</div></div>);}
