@keyframes spinIn{0%{opacity:0;transform:rotate(-180deg) scale(0.5)}100%{opacity:1;transform:rotate(0deg) scale(1)}}
@keyframes fadeOut{0%{opacity:1}100%{opacity:0}}
@keyframes textReveal{0%{opacity:0;letter-spacing:20px}100%{opacity:1;letter-spacing:4px}}
@keyframes digiFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-15px)}}
@keyframes digiWave{0%,100%{transform:rotate(0deg)}25%{transform:rotate(-20deg)}75%{transform:rotate(15deg)}}
@keyframes speechBubble{0%{opacity:0;transform:scale(0.8) translateY(10px)}100%{opacity:1;transform:scale(1) translateY(0)}}
.animate-in{animation:fadeIn 0.4s ease-out}.unlock-anim{animation:unlock 0.5s ease-out}.shake-anim{animation:shake 0.5s ease-out}.modal-in{animation:modalIn 0.3s ease-out}.pulse-btn{animation:pulse 2s infinite}.digi-float{animation:digiFloat 3s ease-in-out infinite}.digi-wave-arm{animation:digiWave 1.5s ease-in-out infinite;transform-origin:38px 75px}
