.auth-greeting-bubble::before{content:'';position:absolute;bottom:-12px;left:40px;width:0;height:0;border-left:12px solid transparent;border-right:12px solid transparent;border-top:12px solid var(--yellow)}
.auth-greeting-bubble p{font-size:18px;line-height:1.5;color:var(--text);margin:0;font-weight:600}
.app-container{display:flex;min-height:100vh}
.sidebar{width:280px;height:100vh;background:var(--surface);border-right:1px solid var(--surface3);position:fixed;left:0;top:0;z-index:100;display:flex;flex-direction:column;transition:transform 0.3s cubic-bezier(0.4,0,0.2,1);overflow-y:auto}
.main-content{flex:1;min-height:100vh;transition:margin-left 0.3s cubic-bezier(0.4,0,0.2,1)}
