function buildQuestions(conceptId,data,pool,lang){
const fields=[{q:'Según la clase, ¿cuál es la configuración de la mano?',correct:data.anatomy.handshape,key:'handshape'},{q:'¿Dónde se ubica exactamente esta seña?',correct:data.anatomy.location,key:'location'},{q:'¿Qué movimiento describe la lección?',correct:data.anatomy.movement,key:'movement'},{q:'¿Cómo se orienta la palma al ejecutarla?',correct:data.anatomy.palm,key:'palm'},{q:'¿Qué orientación general enseña la clase?',correct:data.anatomy.orientation,key:'orientation'},{q:'¿Qué expresión facial debe acompañarla?',correct:data.anatomy.facialExpression,key:'facialExpression'},{q:'¿Cuántas repeticiones indica la lección?',correct:data.anatomy.repetition,key:'repetition'},{q:'¿Cuál es el primer paso explicado en clase?',correct:(data.steps&&data.steps[0])||'',key:'steps0'},{q:'¿Cuál de estos es un error común mencionado?',correct:(data.mistakes&&data.mistakes[0])||'',key:'mistakes0'}];
const seedBase=hashStr(lang+conceptId);
return fields.filter(f=>f.correct).map((f,idx)=>{const others=pool.filter(p=>p.id!==conceptId&&p.data).map(p=>p.data);let dis=[];
if(f.key==='steps0'){dis=seededShuffle(others.map(o=>o.steps&&o.steps[0]).filter(v=>v&&v!==f.correct),seedBase+idx).slice(0,3);}
else if(f.key==='mistakes0'){dis=seededShuffle(others.map(o=>o.mistakes&&o.mistakes[1]).filter(v=>v&&v!==f.correct),seedBase+idx).slice(0,3);}
else{dis=seededShuffle(others.map(o=>o.anatomy&&o.anatomy[f.key]).filter(v=>v&&v!==f.correct),seedBase+idx).slice(0,3);}
let pi=0;while(dis.length<3&&pi<6){const pad=(PADS[f.key]||PADS.context)[pi%3];if(pad&&pad!==f.correct&&!dis.includes(pad)){dis.push(pad);}pi++;}
const options=seededShuffle([f.correct].concat(dis.slice(0,3)),seedBase+idx*7+13);
return{question:f.q,options:options,correct:options.indexOf(f.correct),explanation:'La clase lo indica: '+f.correct};});
}
