if(examComplete){return(<div className="animate-in" style={{maxWidth:700,margin:'0 auto',padding:20}}><BackButton onClick={onBack} label="Volver"/><div style={{background:'var(--surface)',borderRadius:'var(--radius)',padding:32,marginTop:24,border:'1px solid var(--surface3)',textAlign:'center'}}><div style={{fontSize:64,marginBottom:12}}>{passed?'🏆':'📚'}</div><h2 style={{fontSize:36,fontWeight:800,color:passed?'var(--success)':'var(--orange)'}}>{scorePct}%</h2><p style={{color:'var(--text2)',fontSize:16,marginTop:8}}>{passed?'¡NIVELADO!':'Necesitas repasar el bloque'}</p></div><button onClick={onBack} style={{marginTop:20,padding:'14px 20px',background:'var(--surface2)',color:'var(--text)',border:'1px solid var(--surface3)',borderRadius:'var(--radius-sm)',cursor:'pointer',fontSize:15,fontWeight:600}}>Volver a la ruta</button></div>);}
