@media(max-width:600px){.main-content{padding:16px!important}.main-header{padding:10px 16px!important}.splash-logo{width:200px;height:200px}.splash-text{font-size:32px}.back-btn{top:70px;left:10px;padding:8px 12px;font-size:12px}.auth-digi-character svg{max-width:300px}.auth-greeting-bubble{top:20px;right:20px;max-width:180px;padding:12px 16px}.auth-greeting-bubble p{font-size:13px}}
